const RECIPE_GROUPS = [{"id":"espresso_pure","icon":"coffee","title":"خانواده اسپرسو","items":[{"id":24,"title":"اسپرسو نرمال (Espresso Normale)","body":"<ul><li><strong>گام ۱ (آسیاب و دوز):</strong> قهوه را ریز آسیاب کنید. مؤسسه‌ی ملی اسپرسوی ایتالیا دوز ۶٫۵ تا ۷٫۵ گرم را برای هر فنجان مبنا می‌گیرد؛ به‌طور تقریبی ۷، ۱۴ و ۲۱ گرم قهوه برای تک، دوبل و سه‌بل.</li><li><strong>گام ۲ (فشردن قهوه (تمپ)):</strong> قهوه را فشرده کنید؛ فشردن، نفوذ یکنواخت آب در پودر را بهتر می‌کند.</li><li><strong>گام ۳ (عصاره‌گیری):</strong> آب بسیار داغ را تحت فشار از قهوه عبور دهید. مشخصات مؤسسه: دمای آب هنگام خروج ۸۶ تا ۹۰ درجه‌ی سانتی‌گراد، فشار آب ورودی ۸ تا ۱۰ بار، زمان عبور ۲۰ تا ۳۰ ثانیه. زمان معمول ۲۵ تا ۳۰ ثانیه است.</li><li><strong>گام ۴ (سرو):</strong> حجم نهایی در فنجان (همراه کرما) ۲۲٫۵ تا ۲۷٫۵ میلی‌لیتر و دمای فنجان ۶۴ تا ۷۰ درجه است. کافئین هر فنجان طبق این استاندارد کمتر از ۱۰۰ میلی‌گرم است.</li></ul>","kind":"item","description":"اسپرسو با عبور دادن آب بسیار داغ، تحت فشار زیاد، از میان قهوه‌ی ریزآسیاب‌شده و فشرده ساخته می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","ترازوی دقیق","تمپر"],"ingredients":[{"amount":"۶٫۵–۷٫۵","unit":"گرم","name":"قهوه‌ی ریزآسیاب‌شده برای یک اسپرسوی تک (دوبل: حدود ۱۴ گرم)"},{"amount":"۲۲٫۵–۲۷٫۵","unit":"میلی‌لیتر","name":"اسپرسو در فنجان، همراه با کرما"}],"steps":[{"label":"آسیاب و دوز","text":"قهوه را ریز آسیاب کنید. مؤسسه‌ی ملی اسپرسوی ایتالیا دوز ۶٫۵ تا ۷٫۵ گرم را برای هر فنجان مبنا می‌گیرد؛ به‌طور تقریبی ۷، ۱۴ و ۲۱ گرم قهوه برای تک، دوبل و سه‌بل.","meta":"۶٫۵ تا ۷٫۵ گرم"},{"label":"فشردن قهوه (تمپ)","text":"قهوه را فشرده کنید؛ فشردن، نفوذ یکنواخت آب در پودر را بهتر می‌کند."},{"label":"عصاره‌گیری","text":"آب بسیار داغ را تحت فشار از قهوه عبور دهید. مشخصات مؤسسه: دمای آب هنگام خروج ۸۶ تا ۹۰ درجه‌ی سانتی‌گراد، فشار آب ورودی ۸ تا ۱۰ بار، زمان عبور ۲۰ تا ۳۰ ثانیه. زمان معمول ۲۵ تا ۳۰ ثانیه است.","meta":"۸۶ تا ۹۰ درجه‌ی سانتی‌گراد · ۸ تا ۱۰ بار · ۲۰ تا ۳۰ ثانیه"},{"label":"سرو","text":"حجم نهایی در فنجان (همراه کرما) ۲۲٫۵ تا ۲۷٫۵ میلی‌لیتر و دمای فنجان ۶۴ تا ۷۰ درجه است. کافئین هر فنجان طبق این استاندارد کمتر از ۱۰۰ میلی‌گرم است.","meta":"۲۲٫۵ تا ۲۷٫۵ میلی‌لیتر"}],"proTip":"کرما لایه‌ی کف متراکمی است که بالای نوشیدنی می‌نشیند و ویژه‌ی اسپرسوست. وقتی آب تحت فشار بسیار زیاد دی‌اکسیدکربن بیشتری را در خود حل کند، کرما تولید می‌شود.","variation":"معمولاً ریسترتو نیمِ حجم نورمال و لونگو دو تا سه برابر حجم نورمال است. برای یک دوبل (۱۴ گرم قهوه‌ی خشک) نورمال حدود ۶۰ میلی‌لیتر آب مصرف می‌کند.","history":"در ۱۸۸۴ آنجلو موریوندو دستگاهی را ثبت کرد که با بخار، آب را از میان قهوه عبور می‌داد؛ ایان برستن او را «اگر نه نخستین، قطعاً از نخستین مخترعان دستگاه اسپرسو» می‌داند. در ۱۹۰۱ لوئیجی بتسرای میلانی برای دستگاه قهوه‌ی خود ثبت اختراع کرد و در ۱۹۰۳ دزیدریو پاوونی حق ثبت او را خرید و از ۱۹۰۵ فروش دستگاه را آغاز کرد. فشار این دستگاه‌ها حدود ۱٫۵ بار بود و دم‌کردن هر اسپرسو نزدیک یک دقیقه (حدود دو برابر امروز) طول می‌کشید. در ۱۹۳۵ فرانچسکو ایلی دستگاه «ایلتا» را با هوای فشرده به‌جای بخار ثبت کرد. در ۱۹۳۸ آکیله گاجا در میلان ثبت اختراعی مشابه گرفت و در ۱۹۴۷ سازوکار پیستونی را تکمیل کرد که آب را تا ۱۲ اتمسفر تحت فشار می‌گذاشت؛ فروش آن از سال بعد شروع شد. تحول بزرگ بعدی در ۱۹۶۱ با دستگاه فائما E۶۱ ارنستو والنته بود که با پمپ برقی آب را تا ۹ بار فشار می‌داد.","src":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"id":25,"title":"ریسترتو (Ristretto)","body":"<ul><li><strong>گام ۱ (دوز):</strong> از همان مقدار قهوه‌ی یک شات دوبل معمولی استفاده کنید؛ حدود ۱۴ تا ۱۸ گرم.</li><li><strong>گام ۲ (عصاره‌گیری کوتاه):</strong> با نصف آب معمول عصاره بگیرید تا حدود ۲۰ میلی‌لیتر حاصل شود. زمان عصاره‌گیری ۲۰ تا ۳۰ ثانیه است.</li><li><strong>گام ۳ (سرو):</strong> شات را همان‌طور مستقیم بنوشید یا با شیر یا آب ترکیب کنید؛ ریسترتوی تنها پرمایه‌تر و با بدنه‌ی بیشتر و تلخی کمتر توصیف شده و ریسترتوی رقیق‌شده کم‌تلخی‌تر و با شخصیت اسپرسوی پررنگ‌تر.</li></ul>","kind":"item","description":"ریسترتو «شات کوتاه» از اسپرسوی بسیار غلیظ است: حدود ۲۰ میلی‌لیتر از سبد دوبل.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","ترازوی دقیق","تمپر"],"ingredients":[{"amount":"۱۴–۱۸","unit":"گرم","name":"قهوه‌ی ریزآسیاب‌شده (همان مقدار شات دوبل معمولی)"},{"amount":"۲۰","unit":"میلی‌لیتر","name":"خروجی ریسترتو (شات دوبل معمولی حدود ۴۰ میلی‌لیتر)"}],"steps":[{"label":"دوز","text":"از همان مقدار قهوه‌ی یک شات دوبل معمولی استفاده کنید؛ حدود ۱۴ تا ۱۸ گرم.","meta":"۱۴–۱۸ گرم"},{"label":"عصاره‌گیری کوتاه","text":"با نصف آب معمول عصاره بگیرید تا حدود ۲۰ میلی‌لیتر حاصل شود. زمان عصاره‌گیری ۲۰ تا ۳۰ ثانیه است.","meta":"۲۰ میلی‌لیتر · ۲۰–۳۰ ثانیه"},{"label":"سرو","text":"شات را همان‌طور مستقیم بنوشید یا با شیر یا آب ترکیب کنید؛ ریسترتوی تنها پرمایه‌تر و با بدنه‌ی بیشتر و تلخی کمتر توصیف شده و ریسترتوی رقیق‌شده کم‌تلخی‌تر و با شخصیت اسپرسوی پررنگ‌تر."}],"proTip":"ابتدای شات غلیظ‌ترین بخش آن است و انتهایش بسیار سبک‌تر؛ ریسترتو نسبت بیشتری از ترکیب‌های زودعصاره‌شونده دارد و در مجموع مواد کمتری (از جمله کافئین) از قهوه استخراج می‌کند.","variation":"ریسترتوی دوبل حدود ۳۰ میلی‌لیتر است و مقدار ریسترتو «نیمِ حجم نورمال» دانسته می‌شود؛ بنابراین منابع در عدد دقیق هم‌نظر نیستند.","history":"«ریسترتو» در ایتالیایی به معنی «کوتاه‌شده و باریک» است و نام کامل آن «کافه ریسترتو» است. در فرانسه آن را «کافه سره» (café serré) می‌نامند.","src":[["Wikipedia — Ristretto","https://en.wikipedia.org/wiki/Ristretto"],["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"],["Coffee Review — Traditional espresso drink descriptions","https://www.coffeereview.com/coffee-reference/espresso/espresso-cuisines/traditional-drink-descriptions/"]]},{"id":26,"title":"دوپیو (Doppio)","body":"<ul><li><strong>گام ۱ (دوز):</strong> برای شات دوبل حدود ۱۴ گرم قهوه‌ی خشک وزن کنید (تک: حدود ۷، سه‌بل: حدود ۲۱ گرم).</li><li><strong>گام ۲ (عصاره‌گیری):</strong> مانند اسپرسوی نورمال عصاره بگیرید؛ برای دوبل ۱۴ گرمی، نورمال حدود ۶۰ میلی‌لیتر آب مصرف می‌کند.</li></ul>","kind":"item","description":"«دوپیو» واژه‌ی ایتالیایی برای شات دوبل است؛ حدود دو برابر اسپرسوی تک.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","ترازوی دقیق","تمپر"],"ingredients":[{"amount":"۱۴","unit":"گرم","name":"قهوه‌ی ریزآسیاب‌شده (دوبل)"},{"amount":"۶۰","unit":"میلی‌لیتر","name":"آب برای یک نورمال دوبل (تقریبی)"}],"steps":[{"label":"دوز","text":"برای شات دوبل حدود ۱۴ گرم قهوه‌ی خشک وزن کنید (تک: حدود ۷، سه‌بل: حدود ۲۱ گرم).","meta":"۱۴ گرم"},{"label":"عصاره‌گیری","text":"مانند اسپرسوی نورمال عصاره بگیرید؛ برای دوبل ۱۴ گرمی، نورمال حدود ۶۰ میلی‌لیتر آب مصرف می‌کند.","meta":"≈۶۰ میلی‌لیتر"}],"proTip":"حجم یک دوپیو در ایتالیا حدود ۷۵ میلی‌لیتر و در آمریکا حدود ۹۰ تا ۱۵۰ میلی‌لیتر گزارش شده است؛ در هر دو حالت دوپیو با دو برابر قهوه‌ی تک ساخته می‌شود.","variation":"ریسترتوی دوبل حدود نصف آب نورمال، یعنی نزدیک ۳۰ میلی‌لیتر، مصرف می‌کند.","history":"اسپرسوی تک اندازه‌ی سنتی است، زیرا حداکثر مقداری بود که با دستگاه اهرمی به‌راحتی گرفته می‌شد. واژه‌ی ایتالیایی «دوپیو» اغلب برای شات دوبل به کار می‌رود.","src":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"],["Coffee Review — Traditional espresso drink descriptions","https://www.coffeereview.com/coffee-reference/espresso/espresso-cuisines/traditional-drink-descriptions/"]]},{"id":27,"title":"لونگو (Lungo)","body":"<ul><li><strong>گام ۱ (عصاره‌گیری بلند):</strong> با دستگاه اسپرسو و حدود دو برابر آب یک شات معمولی عصاره بگیرید. نسبت قهوه‌ی آسیاب‌شده به مایع حدود ۱:۴ است (نورمال ۱:۲).</li><li><strong>گام ۲ (زمان و حجم):</strong> یک لونگو ممکن است تا یک دقیقه طول بکشد (شات معمولی ۱۸ تا ۳۰ ثانیه) و ۵۰ تا ۷۰ میلی‌لیتر را پر کند.</li></ul>","kind":"item","description":"لونگو اسپرسویی به سبک ایتالیایی است که با حدود دو برابر آبِ شات معمولی گرفته می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","ترازوی دقیق","تمپر"],"ingredients":[{"amount":"۵۰–۷۰","unit":"میلی‌لیتر","name":"حجم یک لونگو (شات معمولی: ۲۵ تا ۳۰ میلی‌لیتر)"}],"steps":[{"label":"عصاره‌گیری بلند","text":"با دستگاه اسپرسو و حدود دو برابر آب یک شات معمولی عصاره بگیرید. نسبت قهوه‌ی آسیاب‌شده به مایع حدود ۱:۴ است (نورمال ۱:۲).","meta":"نسبت ۱:۴"},{"label":"زمان و حجم","text":"یک لونگو ممکن است تا یک دقیقه طول بکشد (شات معمولی ۱۸ تا ۳۰ ثانیه) و ۵۰ تا ۷۰ میلی‌لیتر را پر کند.","meta":"تا ۱ دقیقه · ۵۰–۷۰ میلی‌لیتر"}],"proTip":"ترکیب لونگو با قهوه‌ی روش‌های دیگر یکی نیست و نصفِ قدرت اسپرسو هم نیست؛ چون ترکیب‌های طعمی با سرعت‌های متفاوت حل می‌شوند و با زیاد شدن آب، ترکیب نوشیدنی تغییر می‌کند.","variation":"لونگو دو تا سه برابر حجم نورمال است.","history":"«لونگو» در ایتالیایی به معنی «بلند» است و نام کامل آن «کافه لونگو» است. در فرانسوی «کافه آلونژه» نام دارد و در استان کبک کانادا محبوب است. قهوه‌ی آن معمولاً ترکیبی از عربیکا و روبوستاست.","src":[["Wikipedia — Lungo","https://en.wikipedia.org/wiki/Lungo"],["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"id":28,"title":"کافه کرما (Caffè Crema)","body":"<ul><li><strong>گام ۱ (آسیاب درشت‌تر):</strong> قهوه را درشت‌تر از اسپرسوی نورمال و لونگو آسیاب کنید.</li><li><strong>گام ۲ (عصاره‌گیری خیلی بلند):</strong> اسپرسو را بلندتر از لونگو بگیرید؛ حجم نهایی ۱۲۰ تا ۲۴۰ میلی‌لیتر است.</li></ul>","kind":"item","description":"کافه کرما اسپرسوی بسیار بلندتر از لونگوست.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا (سبک اروپای مرکزی)","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","ترازوی دقیق","تمپر"],"ingredients":[{"amount":"۱۲۰–۲۴۰","unit":"میلی‌لیتر","name":"حجم کافه کرما (در جای دیگر ۱۲۰ تا ۱۸۰ آمده است)"}],"steps":[{"label":"آسیاب درشت‌تر","text":"قهوه را درشت‌تر از اسپرسوی نورمال و لونگو آسیاب کنید."},{"label":"عصاره‌گیری خیلی بلند","text":"اسپرسو را بلندتر از لونگو بگیرید؛ حجم نهایی ۱۲۰ تا ۲۴۰ میلی‌لیتر است.","meta":"۱۲۰–۲۴۰ میلی‌لیتر"}],"proTip":"کافه کرما مانند اسپرسو دم می‌شود، اما با آسیاب درشت‌تر؛ زمان عصاره‌گیری آن به‌مراتب بیشتر از لونگوست.","variation":"لونگو دو تا سه برابر حجم نورمال است و کافه کرما از آن هم بلندتر. در آمریکانو برخلاف این‌ها، آب داغ پس از عصاره‌گیری به اسپرسو اضافه می‌شود.","history":"","src":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"],["Wikipedia — Caffè Americano","https://en.wikipedia.org/wiki/Caff%C3%A8_Americano"],["Wikipedia — Lungo","https://en.wikipedia.org/wiki/Lungo"]]}],"hero":"assets/images/espresso_pure.svg"},{"id":"espresso_diluted","icon":"droplet","title":"اسپرسو رقیق‌شده","items":[{"id":32,"title":"آمریکانو (Americano)","body":"<ul><li><strong>گام ۱ (اسپرسو):</strong> یک یا دو شات اسپرسو بگیرید.</li><li><strong>گام ۲ (افزودن آب):</strong> آب داغ را به اسپرسو اضافه کنید (اسپرسو پایین است). قدرت آمریکانو با تعداد شات و مقدار آب تغییر می‌کند و معمولاً برای جلوگیری از رقیق‌شدن بیش‌ازحد نسبت ۱:۱ اسپرسو به آب به کار می‌رود.</li></ul>","kind":"item","description":"آمریکانو یک یا دو شات اسپرسو است که با آب داغ ترکیب می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا / آمریکا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","کتری"],"ingredients":[{"amount":"۱–۲","unit":"شات","name":"اسپرسو"},{"amount":"۳۰–۴۷۰","unit":"میلی‌لیتر","name":"آب داغ (۱ تا ۱۶ اونس مایع؛ معمولاً نسبت ۱:۱ اسپرسو به آب)"}],"steps":[{"label":"اسپرسو","text":"یک یا دو شات اسپرسو بگیرید."},{"label":"افزودن آب","text":"آب داغ را به اسپرسو اضافه کنید (اسپرسو پایین است). قدرت آمریکانو با تعداد شات و مقدار آب تغییر می‌کند و معمولاً برای جلوگیری از رقیق‌شدن بیش‌ازحد نسبت ۱:۱ اسپرسو به آب به کار می‌رود.","meta":"۱:۱"}],"proTip":"ریختن آب روی اسپرسوی ازپیش‌ریخته‌شده کرما را از بین می‌برد و نتیجه آمریکانو نام دارد؛ اگر اسپرسو روی آب ریخته شود نوشیدنی لانگ بلک است.","variation":"«ایتالیانو» (آمریکانوی کوتاه) نسبت اسپرسو به آب ۱:۱ دارد.","history":"واژه‌ی «آمریکانو» به معنی «آمریکایی» است و از ایتالیایی یا اسپانیایی آمریکایی می‌آید و قدمتش به دهه‌ی ۱۹۷۰ برمی‌گردد. باوری رایج اما تأییدنشده می‌گوید منشأ نام به جنگ جهانی دوم برمی‌گردد، زمانی که سربازان آمریکایی در اروپا اسپرسو را با آب داغ رقیق می‌کردند تا به قهوه‌ی آشنای خود نزدیک شود. همچنین ممکن است در خودِ آمریکا ابداع شده باشد.","src":[["Wikipedia — Caff%C3%A8 Americano","https://en.wikipedia.org/wiki/Caff%C3%A8_Americano"],["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"id":33,"title":"لانگ بلک (Long Black)","body":"<ul><li><strong>گام ۱ (آب):</strong> ابتدا آب داغ را در فنجان بریزید؛ معمولاً حدود ۱۰۰ تا ۱۲۰ میلی‌لیتر.</li><li><strong>گام ۲ (اسپرسو):</strong> شات دوبل اسپرسو را روی آب داغ بریزید. اگر درست ساخته شود کرما حفظ می‌شود و در لانگ بلک پررنگ‌تر است.</li></ul>","kind":"item","description":"لانگ بلک با ریختن شات دوبل اسپرسو روی آب داغ ساخته می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"استرالیا و نیوزیلند","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","کتری"],"ingredients":[{"amount":"۲","unit":"شات","name":"اسپرسو (شات دوبل)"},{"amount":"۱۰۰–۱۲۰","unit":"میلی‌لیتر","name":"آب داغ (حدود ۴ اونس؛ بسته به سلیقه)"}],"steps":[{"label":"آب","text":"ابتدا آب داغ را در فنجان بریزید؛ معمولاً حدود ۱۰۰ تا ۱۲۰ میلی‌لیتر.","meta":"۱۰۰–۱۲۰ میلی‌لیتر"},{"label":"اسپرسو","text":"شات دوبل اسپرسو را روی آب داغ بریزید. اگر درست ساخته شود کرما حفظ می‌شود و در لانگ بلک پررنگ‌تر است."}],"proTip":"نسبت آب کمتر نسبت به آمریکانو، طعم قوی‌تری به لانگ بلک می‌دهد.","variation":"آمریکانو با ریختن آب روی اسپرسو ساخته می‌شود، نه برعکس.","history":"لانگ بلک در استرالیا و نیوزیلند رایج است و در دهه‌های ۱۹۵۰ و ۱۹۶۰ معرفی شد.","src":[["Wikipedia — Long black","https://en.wikipedia.org/wiki/Long_black"],["Wikipedia — Caff%C3%A8 Americano","https://en.wikipedia.org/wiki/Caff%C3%A8_Americano"]]},{"id":34,"title":"آیس آمریکانو (Iced Americano)","body":"<ul><li><strong>گام ۱ (ساخت):</strong> اسپرسو را با آب سرد روی یخ سرو کنید.</li></ul>","kind":"item","description":"آیس آمریکانو نسخه‌ی سردِ آمریکانوست؛ بنا بر تعریف، قهوه‌ی یخی قهوه‌ای است که سرد سرو می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","کتری"],"ingredients":[{"amount":"۱","unit":"شات","name":"اسپرسو"},{"amount":"—","unit":"","name":"آب سرد"},{"amount":"—","unit":"","name":"یخ"}],"steps":[{"label":"ساخت","text":"اسپرسو را با آب سرد روی یخ سرو کنید."}],"proTip":"قهوه‌ی یخی را معمولاً غلیظ‌تر دم می‌کنند چون آب‌شدن یخ آن را رقیق می‌کند.","variation":"آیس آمریکانو اسپرسو را با آب سرد ترکیب می‌کند، نه آب داغ. در روش دیگر قهوه‌ی یخی، قهوه‌ی داغ و غلیظ‌تر روی یخ ریخته می‌شود.","history":"عبارت «قهوه‌ی یخی» در اواخر قرن نوزدهم در منوها و دستورها دیده می‌شود و کارزار سال ۱۹۲۰ کمیته‌ی تبلیغات قهوه‌ی آمریکا آن را رایج کرد.","src":[["Wikipedia — Iced coffee","https://en.wikipedia.org/wiki/Iced_coffee"],["Wikipedia — Caffè Americano","https://en.wikipedia.org/wiki/Caff%C3%A8_Americano"]]}],"hero":"assets/images/espresso_diluted.svg"},{"id":"espresso_milk","icon":"milk","title":"اسپرسو و شیر","items":[{"id":38,"title":"کاپوچینو (Cappuccino)","body":"<ul><li><strong>گام ۱ (اسپرسو):</strong> یک شات اسپرسو بگیرید. در ایتالیا یک کاپوچینو ۲۵ میلی‌لیتر اسپرسو دارد و بقیه‌ی فنجان با مقادیر مساوی شیر و کف پر می‌شود. برای کاپوچینوی سنتی اسپرسوی برشته‌ی تیره بیشتر استفاده می‌شود.</li><li><strong>گام ۲ (شیر و کف):</strong> شیر داغ و کف شیر را اضافه کنید. نسبت سنتی: یک‌سوم اسپرسو، یک‌سوم شیر بخارداده‌شده و یک‌سوم کف شیر.</li><li><strong>گام ۳ (سرو):</strong> در فنجان کوچک دسته‌دار (حداکثر ۱۸۰ میلی‌لیتر) سرو کنید. حجم کل بین ۱۵۰ تا ۱۸۰ میلی‌لیتر است. روی آن پودر شکلات یا کاکائو (سنتی ایتالیایی) می‌پاشند؛ در اروپا و استرالیا کاکائو و در آمریکا و کره‌ی جنوبی دارچین رایج‌تر است.</li></ul>","kind":"item","description":"کاپوچینو در سنت، با اسپرسو و شیر بخارداده‌شده همراه با لایه‌ای از کف شیر ساخته می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","پارچ شیر و لوله‌ی بخار","ترازو"],"ingredients":[{"amount":"۱–۳","unit":"شات","name":"اسپرسو (تک، دوبل یا سه‌بل)"},{"amount":"۱۵۰–۱۸۰","unit":"میلی‌لیتر","name":"حجم کل اسپرسو، شیر و کف در فنجان سنتی"}],"steps":[{"label":"اسپرسو","text":"یک شات اسپرسو بگیرید. در ایتالیا یک کاپوچینو ۲۵ میلی‌لیتر اسپرسو دارد و بقیه‌ی فنجان با مقادیر مساوی شیر و کف پر می‌شود. برای کاپوچینوی سنتی اسپرسوی برشته‌ی تیره بیشتر استفاده می‌شود.","meta":"۲۵ میلی‌لیتر"},{"label":"شیر و کف","text":"شیر داغ و کف شیر را اضافه کنید. نسبت سنتی: یک‌سوم اسپرسو، یک‌سوم شیر بخارداده‌شده و یک‌سوم کف شیر.","meta":"۱/۳ + ۱/۳ + ۱/۳"},{"label":"سرو","text":"در فنجان کوچک دسته‌دار (حداکثر ۱۸۰ میلی‌لیتر) سرو کنید. حجم کل بین ۱۵۰ تا ۱۸۰ میلی‌لیتر است. روی آن پودر شکلات یا کاکائو (سنتی ایتالیایی) می‌پاشند؛ در اروپا و استرالیا کاکائو و در آمریکا و کره‌ی جنوبی دارچین رایج‌تر است.","meta":"۱۵۰–۱۸۰ میلی‌لیتر"}],"proTip":"در مسابقات جهانی باریستا، کاپوچینو یک شات اسپرسو با شیر و کف است و عمق کف دست‌کم ۱ سانتی‌متر.","variation":"زنجیره‌های آمریکایی کاپوچینو را در حجم ۳۶۰ میلی‌لیتر یا بیشتر عرضه می‌کنند؛ نسخه‌ی کوتاه‌شده‌ی فست‌فودها تا ۶۰۰ میلی‌لیتر هم می‌رسد.","history":"نام از رهبانان کاپوچین گرفته شده و به رنگ ردای آن‌ها اشاره دارد. در وین نسخه‌ی اولیه‌ای با خامه‌ی زده‌شده و ادویه «کاپوتسینر» نام گرفت (احتمالاً در قرن هجدهم) و کاپوتسینر در اواخر دهه‌ی ۱۷۰۰ در منوی قهوه‌خانه‌های امپراتوری هابسبورگ دیده می‌شد. در قرن نوزدهم ایتالیایی‌ها آن را «قهوه‌ی سیاه با چند قطره شیر یا خامه» توصیف می‌کردند. شیر بخارداده‌شده افزوده‌ی بعدی است و مصرف شیر تازه در کافه‌ها پدیده‌ای قرن بیستمی؛ دستگاه‌های اسپرسو هم در ابتدای قرن بیستم معرفی شدند. کافه رجیو (۱۹۲۷) مدعی است کاپوچینو را به آمریکا آورده است. افسانه‌ی رایج درباره‌ی منشأ آن تأییدنشده است.","src":[["Wikipedia — Cappuccino","https://en.wikipedia.org/wiki/Cappuccino"]]},{"id":39,"title":"کافه لاته (Caffè Latte)","body":"<ul><li><strong>گام ۱ (اسپرسو):</strong> یک یا چند شات اسپرسو را در لیوان بگیرید.</li><li><strong>گام ۲ (شیر):</strong> شیر داغ بخارداده‌شده را اضافه کنید. شیر لاته طوری بخار داده می‌شود که حباب‌های بسیار ریز در شیر داغ بماند (میکروفوم)؛ بافت میکروفوم بر طعم و حس نوشیدنی اثر می‌گذارد.</li><li><strong>گام ۳ (سرو):</strong> در لیوان (یا گاهی فنجان) حدود ۲۳۰ میلی‌لیتری و بدون لایه‌ی کف ضخیم سرو کنید؛ کاپوچینو در فنجان کوچک ۱۴۰ میلی‌لیتری و با لایه‌ی کف ضخیم می‌آید.</li></ul>","kind":"item","description":"کافه لاته با اسپرسو و شیر بخارداده‌شده ساخته می‌شود و به‌طور سنتی در لیوان سرو می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","پارچ شیر و لوله‌ی بخار","ترازو"],"ingredients":[{"amount":"۱+","unit":"شات","name":"اسپرسو (یک یا چند شات)"},{"amount":"۲۳۰","unit":"میلی‌لیتر","name":"حجم لیوان سرو (حدود ۸ اونس مایع)"}],"steps":[{"label":"اسپرسو","text":"یک یا چند شات اسپرسو را در لیوان بگیرید."},{"label":"شیر","text":"شیر داغ بخارداده‌شده را اضافه کنید. شیر لاته طوری بخار داده می‌شود که حباب‌های بسیار ریز در شیر داغ بماند (میکروفوم)؛ بافت میکروفوم بر طعم و حس نوشیدنی اثر می‌گذارد."},{"label":"سرو","text":"در لیوان (یا گاهی فنجان) حدود ۲۳۰ میلی‌لیتری و بدون لایه‌ی کف ضخیم سرو کنید؛ کاپوچینو در فنجان کوچک ۱۴۰ میلی‌لیتری و با لایه‌ی کف ضخیم می‌آید.","meta":"۲۳۰ میلی‌لیتر"}],"proTip":"لاته خیلی شیری‌تر از کاپوچینو است و طعم قهوه‌ی ملایم‌تری دارد. شیر را می‌توان طوری ریخت که روی میکروفوم سفید و کرمای قهوه‌ای نقش بسازد؛ این تکنیک «لاته آرت» نام دارد.","variation":"در ایتالیا نوشیدنی‌های شیری مانند کافه لاته، لاته ماکیاتو و کاپوچینو اغلب فقط برای صبحانه آماده می‌شوند.","history":"واژه‌ی «لاته» در ایتالیایی یعنی «شیر»؛ سفارش «لاته» در ایتالیا یک لیوان شیر است. در انگلیسی از «caffè e latte» (قهوه و شیر) آمده و اولین ثبت «caffè latte» در انگلیسی به ۱۸۴۷ برمی‌گردد. گفته می‌شود نوشیدنی «از لحاظ فنی» در قرن هفدهم اروپا شکل گرفت؛ لاته‌ی مدرن در قرن بیستم و پس از اختراع دستگاه اسپرسو در قرن نوزدهم پدید آمد و افزودن لوله‌ی بخار به دستگاه اسپرسو در ۱۹۰۳ امکان گرم‌کردن و بافت‌دادن به شیر را فراهم کرد.","src":[["Wikipedia — Latte","https://en.wikipedia.org/wiki/Latte"]]},{"id":40,"title":"فلت وایت (Flat White)","body":"<ul><li><strong>گام ۱ (اسپرسو):</strong> یک اسپرسوی دوبل (حدود ۵۰ میلی‌لیتر) بگیرید.</li><li><strong>گام ۲ (شیر):</strong> حدود ۱۳۰ میلی‌لیتر شیر بخارداده‌شده با لایه‌ی میکروفومِ ۵ میلی‌متری اضافه کنید. لایه‌ی میکروفوم نازک‌تر از کاپوچینوست و ایدئالاً سطحی براق‌تر دارد.</li><li><strong>گام ۳ (سرو):</strong> معمولاً در فنجان سرامیکی دسته‌دار سرو می‌شود: در استرالیا حدود ۲۰۰ میلی‌لیتر و در نیوزیلند اغلب کوچک‌تر، ۱۷۵ میلی‌لیتر.</li></ul>","kind":"item","description":"فلت وایت قهوه‌ای با نسبت اسپرسو به شیرِ بیشتر از لاته و لایه‌ی نازک میکروفوم است.","difficulty":"","prepTime":"","totalTime":"","origin":"استرالیا / نیوزیلند","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","پارچ شیر و لوله‌ی بخار","ترازو"],"ingredients":[{"amount":"۵۰","unit":"میلی‌لیتر","name":"اسپرسوی دوبل (توصیف آنت مولدوار)"},{"amount":"۱۳۰","unit":"میلی‌لیتر","name":"شیر بخارداده‌شده با لایه‌ی ۵ میلی‌متری میکروفوم"}],"steps":[{"label":"اسپرسو","text":"یک اسپرسوی دوبل (حدود ۵۰ میلی‌لیتر) بگیرید.","meta":"۵۰ میلی‌لیتر"},{"label":"شیر","text":"حدود ۱۳۰ میلی‌لیتر شیر بخارداده‌شده با لایه‌ی میکروفومِ ۵ میلی‌متری اضافه کنید. لایه‌ی میکروفوم نازک‌تر از کاپوچینوست و ایدئالاً سطحی براق‌تر دارد.","meta":"۱۳۰ میلی‌لیتر · ۵ میلی‌متر"},{"label":"سرو","text":"معمولاً در فنجان سرامیکی دسته‌دار سرو می‌شود: در استرالیا حدود ۲۰۰ میلی‌لیتر و در نیوزیلند اغلب کوچک‌تر، ۱۷۵ میلی‌لیتر.","meta":"۱۷۵–۲۰۰ میلی‌لیتر"}],"proTip":"فلت وایت نسبت به لاته شیر و میکروفوم کمتری دارد؛ نسبت اسپرسو به شیر در آن معمولاً بیشتر است.","variation":"لاته معمولاً در ظرف ۲۲۵ میلی‌لیتری و کاپوچینو در فنجان ۱۵۰ تا ۱۶۰ میلی‌لیتری سرو می‌شود.","history":"خاستگاه فلت وایت محل مناقشه است: کافه‌داران استرالیا و نیوزیلند هر دو مدعی ابداع آن هستند. ایان برستن حدس می‌زند احتمالاً در دهه‌ی ۱۹۵۰ در انگلستان پدید آمده. عبارت در فیلمی بریتانیایی در ۱۹۶۳ و در نقد یک کافه‌ی سیدنی در مه ۱۹۸۳ دیده شده است. آلت پرستون آن را در ۱۹۸۵ به منوی «مورز اسپرسو بار» سیدنی افزود. نیوزیلند به کافه‌ی DKD در اوکلند و یک «کاپوچینوی ناموفق» در بار بودگا (ولینگتون، ۱۹۸۹) استناد می‌کند.","src":[["Wikipedia — Flat white","https://en.wikipedia.org/wiki/Flat_white"]]},{"id":41,"title":"اسپرسو ماکیاتو (Espresso Macchiato)","body":"<ul><li><strong>گام ۱ (اسپرسو):</strong> یک شات اسپرسو بگیرید.</li><li><strong>گام ۲ (شیر):</strong> مقدار کمی شیر بخارداده‌شده را مستقیم داخل شات اسپرسو بریزید. در یکی از دستورها شیر ۵ تا ۱۰ گرم (حدود ۱ تا ۲ قاشق چای‌خوری) و دمایش ۶۰ تا ۶۶ درجه‌ی سانتی‌گراد است.</li></ul>","kind":"item","description":"اسپرسو ماکیاتو اسپرسویی است با مقدار کمی شیر که معمولاً کف‌دار است.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","پارچ شیر و لوله‌ی بخار","ترازو"],"ingredients":[{"amount":"۱","unit":"شات","name":"اسپرسو"},{"amount":"۵–۱۰","unit":"گرم","name":"شیر (حدود ۱ تا ۲ قاشق چای‌خوری)"}],"steps":[{"label":"اسپرسو","text":"یک شات اسپرسو بگیرید."},{"label":"شیر","text":"مقدار کمی شیر بخارداده‌شده را مستقیم داخل شات اسپرسو بریزید. در یکی از دستورها شیر ۵ تا ۱۰ گرم (حدود ۱ تا ۲ قاشق چای‌خوری) و دمایش ۶۰ تا ۶۶ درجه‌ی سانتی‌گراد است.","meta":"۵–۱۰ گرم · ۶۰–۶۶ درجه‌ی سانتی‌گراد"}],"proTip":"اسپرسو ماکیاتو بالاترین نسبت اسپرسو به شیر را در میان نوشیدنی‌های ساخته‌شده با این مواد دارد.","variation":"در پرتغال این نوشیدنی «کافه پینگادو» (قهوه با یک قطره) نام دارد.","history":"در ایتالیایی «ماکیاتو» یعنی «لکه‌دار»؛ نام از تفاوت اسپرسوی ساده با اسپرسویی می‌آید که با کمی شیر «نشان‌دار» شده است.","src":[["Wikipedia — Caff%C3%A8 macchiato","https://en.wikipedia.org/wiki/Caff%C3%A8_macchiato"]]},{"id":42,"title":"لاته ماکیاتو (Latte Macchiato)","body":"<ul><li><strong>گام ۱ (شیر):</strong> شیر را بخار بدهید و در لیوان بریزید؛ لاته ماکیاتو کف بیشتری دارد تا فقط شیر داغ. برای دیده‌شدن لایه‌ها لیوان شیشه‌ای ضروری است.</li><li><strong>گام ۲ (اسپرسو):</strong> اسپرسو را به شیر اضافه کنید؛ برای ساخت لایه می‌توان آن را روی پشت قاشق ریخت. اسپرسو بین شیر مایع سنگین‌تر در پایین و کف سبک‌تر بالا لایه‌ای می‌سازد.</li></ul>","kind":"item","description":"در لاته ماکیاتو اسپرسو به شیر اضافه می‌شود، نه شیر به اسپرسو؛ نوشیدنی معمولاً لایه‌لایه است.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","پارچ شیر و لوله‌ی بخار","ترازو"],"ingredients":[{"amount":"۰٫۵ یا کمتر","unit":"شات","name":"اسپرسو (اغلب نیم شات یا کمتر)"},{"amount":"—","unit":"","name":"شیر با کف بیشتر"}],"steps":[{"label":"شیر","text":"شیر را بخار بدهید و در لیوان بریزید؛ لاته ماکیاتو کف بیشتری دارد تا فقط شیر داغ. برای دیده‌شدن لایه‌ها لیوان شیشه‌ای ضروری است."},{"label":"اسپرسو","text":"اسپرسو را به شیر اضافه کنید؛ برای ساخت لایه می‌توان آن را روی پشت قاشق ریخت. اسپرسو بین شیر مایع سنگین‌تر در پایین و کف سبک‌تر بالا لایه‌ای می‌سازد."}],"proTip":"«ماکیا» لکه‌ی کوچک کف اسپرسوی قهوه‌ای (کرما) است که روی شیر باقی می‌ماند.","variation":"در کافه لاته اسپرسو اول در فنجان ریخته می‌شود و بعد شیر اضافه می‌شود؛ ترتیب معکوس لاته ماکیاتوست.","history":"نام ایتالیایی «شیر لکه‌دار» است و بازی با «کافه ماکیاتو» است، نوشیدنی قدیمی‌تری که اسپرسوی نشان‌شده با یک یا دو قاشق شیر یا خامه است.","src":[["Wikipedia — Latte macchiato","https://en.wikipedia.org/wiki/Latte_macchiato"],["Wikipedia — Latte","https://en.wikipedia.org/wiki/Latte"]]},{"id":43,"title":"موکا (Mocha)","body":"<ul><li><strong>گام ۱ (اسپرسو و شکلات):</strong> مانند کافه لاته بر پایه‌ی اسپرسو و شیر داغ بسازید و کاکائو و شکر اضافه کنید؛ برخی نسخه‌ها به‌جای آن شربت شکلات یا شکلات تلخ یا شیری دارند.</li><li><strong>گام ۲ (شیر و سرو):</strong> معمولاً با کف شیر و در لیوان به‌جای ماگ سرو می‌شود. روی آن پودر دارچین، شکر یا کاکائو می‌پاشند و گاهی به‌جای آن خامه‌ی زده‌شده می‌گذارند.</li></ul>","kind":"item","description":"کافه موکا گونه‌ی شکلاتی کافه لاته است؛ بر پایه‌ی اسپرسو و شیر داغ.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","پارچ شیر و لوله‌ی بخار","ترازو"],"ingredients":[{"amount":"۱+","unit":"شات","name":"اسپرسو"},{"amount":"—","unit":"","name":"شیر داغ"},{"amount":"—","unit":"","name":"پودر کاکائو و شکر (معمولاً)، یا شربت شکلات، یا شکلات تلخ/شیری"}],"steps":[{"label":"اسپرسو و شکلات","text":"مانند کافه لاته بر پایه‌ی اسپرسو و شیر داغ بسازید و کاکائو و شکر اضافه کنید؛ برخی نسخه‌ها به‌جای آن شربت شکلات یا شکلات تلخ یا شیری دارند."},{"label":"شیر و سرو","text":"معمولاً با کف شیر و در لیوان به‌جای ماگ سرو می‌شود. روی آن پودر دارچین، شکر یا کاکائو می‌پاشند و گاهی به‌جای آن خامه‌ی زده‌شده می‌گذارند."}],"proTip":"کافئین موکا حدود ۴۳۰ میلی‌گرم در لیتر است؛ یعنی ۱۵۲ میلی‌گرم برای لیوان ۳۵۰ میلی‌لیتری.","variation":"موکاچینو: یک شات دوبل اسپرسو با ترکیبی از شیر بخارداده‌شده و پودر کاکائو یا شیر شکلاتی.","history":"نام از شهر مخا (موکا) در یمن می‌آید؛ بندری معروف به تجارت قهوه از قرن پانزدهم تا هفدهم. اروپایی‌ها قهوه‌ی وارداتی از عربستان را «موکا» می‌نامیدند. پس از آنکه نوشیدنی شکلات در قرن هفدهم به ایتالیا رسید، شکلات با قهوه ترکیب شد؛ در تورین شکلات با قهوه و خامه مخلوط می‌شد و «باواریسا» می‌ساخت. دستوری از ۱۹۲۰ با شیر، قهوه و کاکائو چاپ شده است.","src":[["Wikipedia — Caff%C3%A8 mocha","https://en.wikipedia.org/wiki/Caff%C3%A8_mocha"]]},{"id":44,"title":"کورتادو (Cortado)","body":"<ul><li><strong>گام ۱ (اسپرسو):</strong> یک شات اسپرسو بگیرید.</li><li><strong>گام ۲ (شیر):</strong> حدود همان مقدار شیر گرم اضافه کنید. شیر کورتادو بخار داده می‌شود اما کف‌دار نیست. نسبت دقیق از منطقه‌ای به منطقه‌ی دیگر تفاوت زیادی دارد.</li></ul>","kind":"item","description":"کورتادو اسپرسویی است که با مقداری تقریباً برابر شیر گرم «بریده» می‌شود تا اسیدیته‌اش کم شود.","difficulty":"","prepTime":"","totalTime":"","origin":"اسپانیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","پارچ شیر و لوله‌ی بخار","ترازو"],"ingredients":[{"amount":"۱","unit":"شات","name":"اسپرسو"},{"amount":"≈ برابر اسپرسو","unit":"","name":"شیر گرم (بخارداده‌شده، نه کف‌دار)"}],"steps":[{"label":"اسپرسو","text":"یک شات اسپرسو بگیرید."},{"label":"شیر","text":"حدود همان مقدار شیر گرم اضافه کنید. شیر کورتادو بخار داده می‌شود اما کف‌دار نیست. نسبت دقیق از منطقه‌ای به منطقه‌ی دیگر تفاوت زیادی دارد."}],"proTip":"در کوبا «کورتادیتو» نوشیدنی کوچکی با یک شات ۳۰ میلی‌لیتری اسپرسوست.","variation":"در پرتغال نوشیدنی بزرگ‌تر «گالائو» با نسبت ۱:۳ رایج است. کورتادو بسیار شبیه (یا همان) ماکیاتوی ایتالیایی و «نوآزت» فرانسوی است.","history":"واژه‌ی «کورتادو» اسپانیایی و به معنی «بریده» است (کاتالان: تالات). نوشیدنی در سراسر اسپانیا رایج است. «کورتادیتو» در دهه‌ی ۱۹۶۰ توسط کوبایی‌های آمریکا به محله‌ی لیتل‌هاوانا در میامی رسید.","src":[["Wikipedia — Cortado","https://en.wikipedia.org/wiki/Cortado"]]},{"id":45,"title":"پیکولو لاته (Piccolo Latte)","body":"<ul><li><strong>گام ۱ (ریسترتو):</strong> یک شات ریسترتو بگیرید و آن را در لیوان ماکیاتو بریزید. در استرالیا این نوشیدنی «پیکولو لاته» یا فقط «پیکولو» نام دارد.</li><li><strong>گام ۲ (شیر):</strong> لیوان را با شیر بخارداده‌شده پر کنید؛ شیر را مانند کافه لاته آماده کنید.</li></ul>","kind":"item","description":"پیکولو لاته نام استرالیایی نوشیدنی‌ای است که با یک شات ریسترتو در لیوان ماکیاتو ساخته می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"استرالیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","پارچ شیر و لوله‌ی بخار","ترازو"],"ingredients":[{"amount":"۱","unit":"شات","name":"ریسترتو"},{"amount":"—","unit":"","name":"شیر بخارداده‌شده (برای پر کردن لیوان ماکیاتو)"}],"steps":[{"label":"ریسترتو","text":"یک شات ریسترتو بگیرید و آن را در لیوان ماکیاتو بریزید. در استرالیا این نوشیدنی «پیکولو لاته» یا فقط «پیکولو» نام دارد."},{"label":"شیر","text":"لیوان را با شیر بخارداده‌شده پر کنید؛ شیر را مانند کافه لاته آماده کنید."}],"proTip":"","variation":"ریسترتو شاتی کوتاه است: همان قهوه‌ی شات دوبل با نصف آب، حدود ۲۰ میلی‌لیتر.","history":"","src":[["Wikipedia — Cortado","https://en.wikipedia.org/wiki/Cortado"],["Wikipedia — Ristretto","https://en.wikipedia.org/wiki/Ristretto"]]},{"id":46,"title":"جبل‌الطارق (Gibraltar)","body":"<ul><li><strong>گام ۱ (اسپرسو):</strong> حدود ۶۰ میلی‌لیتر اسپرسوی دوبل بگیرید.</li><li><strong>گام ۲ (شیر):</strong> حدود ۷۵ میلی‌لیتر شیر بخارداده‌شده‌ی کف‌دار اضافه کنید و در لیوان ۱۳۵ میلی‌لیتری «لیبی جبل‌الطارق» سرو کنید.</li></ul>","kind":"item","description":"جبل‌الطارق (Gibraltar) نوشیدنی‌ای است که در لیوان ۱۳۵ میلی‌لیتری «لیبی جبل‌الطارق» سرو می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"سان‌فرانسیسکو (نام)","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","پارچ شیر و لوله‌ی بخار","ترازو","لیوان ۱۳۵ میلی‌لیتری لیبی جبل‌الطارق"],"ingredients":[{"amount":"۶۰","unit":"میلی‌لیتر","name":"اسپرسوی دوبل"},{"amount":"۷۵","unit":"میلی‌لیتر","name":"شیر بخارداده‌شده‌ی کف‌دار (تقریبی)"}],"steps":[{"label":"اسپرسو","text":"حدود ۶۰ میلی‌لیتر اسپرسوی دوبل بگیرید.","meta":"۶۰ میلی‌لیتر"},{"label":"شیر","text":"حدود ۷۵ میلی‌لیتر شیر بخارداده‌شده‌ی کف‌دار اضافه کنید و در لیوان ۱۳۵ میلی‌لیتری «لیبی جبل‌الطارق» سرو کنید.","meta":"۷۵ میلی‌لیتر"}],"proTip":"","variation":"کورتادو اصطلاحی کلی‌تر است و به هر اسپرسوی «بریده‌شده» با شیرِ تقریباً برابر گفته می‌شود.","history":"نام «جبل‌الطارق» در سان‌فرانسیسکو پدید آمد؛ برشته‌کارانی از جمله بلو بوتل و بعدتر ریچوال با سرو کورتادو در لیوان‌هایی به همین نام به رواج آن کمک کردند.","src":[["Wikipedia — Cortado","https://en.wikipedia.org/wiki/Cortado"]]},{"id":47,"title":"ماروکینو (Marocchino)","body":"<ul><li><strong>گام ۱ (کاکائو):</strong> دیواره‌ی لیوان شیشه‌ای کوچک را ابتدا با پودر کاکائو بپاشید.</li><li><strong>گام ۲ (کف شیر و اسپرسو):</strong> کف شیر و سپس اسپرسو را اضافه کنید.</li><li><strong>گام ۳ (تزئین):</strong> بالای نوشیدنی بار دیگر کاکائو بپاشید.</li></ul>","kind":"item","description":"ماروکینو نوشیدنی‌ای از اسپرسو، پودر کاکائو و کف شیر است که در لیوان کوچک شیشه‌ای سرو می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"الساندریا، ایتالیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","پارچ شیر و لوله‌ی بخار","ترازو","لیوان شیشه‌ای کوچک"],"ingredients":[{"amount":"—","unit":"","name":"اسپرسو (گاهی شات کوچک یا ریسترتو)"},{"amount":"—","unit":"","name":"پودر کاکائو"},{"amount":"—","unit":"","name":"کف شیر"}],"steps":[{"label":"کاکائو","text":"دیواره‌ی لیوان شیشه‌ای کوچک را ابتدا با پودر کاکائو بپاشید."},{"label":"کف شیر و اسپرسو","text":"کف شیر و سپس اسپرسو را اضافه کنید."},{"label":"تزئین","text":"بالای نوشیدنی بار دیگر کاکائو بپاشید."}],"proTip":"اسپرسینو و بیچرین نوشیدنی‌هایی شبیه ماروکینو هستند.","variation":"در برخی مناطق شمال ایتالیا کاکائوی داغ غلیظ اضافه می‌شود و در آلبا (پیه‌مونت) از نوتلا استفاده می‌شود.","history":"ماروکینو نوشیدنی‌ای است که در الساندریا (ایتالیا) ساخته شد. نام آن از رنگش گرفته شده است: «ماروکینو» نوعی چرم قهوه‌ایِ روشن بود (در ایتالیایی یعنی «مراکشی») که در دهه‌ی ۱۹۳۰ برای ساخت کش مو هم به کار می‌رفت.","src":[["Wikipedia — Marocchino","https://en.wikipedia.org/wiki/Marocchino"]]},{"id":48,"title":"اسپرسو کن پانا (Espresso con Panna)","body":"<ul><li><strong>گام ۱ (اسپرسو):</strong> یک یا دو شات اسپرسو بگیرید.</li><li><strong>گام ۲ (خامه):</strong> خامه‌ی فرم‌گرفته را روی اسپرسو بگذارید.</li><li><strong>گام ۳ (سرو):</strong> به‌طور سنتی در فنجانی حدود ۱۸۰ میلی‌لیتری (۶ اونس) سرو می‌شود.</li></ul>","kind":"item","description":"اسپرسو کن پانا (espresso con panna، یعنی «اسپرسو با خامه») یک یا دو شات اسپرسو است که روی آن خامه‌ی فرم‌گرفته می‌گذارند.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","پارچ شیر و لوله‌ی بخار","ترازو"],"ingredients":[{"amount":"۱–۲","unit":"شات","name":"اسپرسو"},{"amount":"—","unit":"","name":"خامه‌ی فرم‌گرفته"}],"steps":[{"label":"اسپرسو","text":"یک یا دو شات اسپرسو بگیرید."},{"label":"خامه","text":"خامه‌ی فرم‌گرفته را روی اسپرسو بگذارید."},{"label":"سرو","text":"به‌طور سنتی در فنجانی حدود ۱۸۰ میلی‌لیتری (۶ اونس) سرو می‌شود.","meta":"حدود ۱۸۰ میلی‌لیتر"}],"proTip":"گاهی روی خامه کمی پودر کاکائوی بدون شکر می‌پاشند.","variation":"در فرانسه و بریتانیا این نوشیدنی «کافه ویوا» (café viennois) نام دارد.","history":"","src":[["Wikipedia — Espresso con panna","https://en.wikipedia.org/wiki/Espresso_con_panna"],["Coffee Review — Traditional espresso drink descriptions","https://www.coffeereview.com/coffee-reference/espresso/espresso-cuisines/traditional-drink-descriptions/"]]},{"id":49,"title":"کافه بروه (Caffè Breve)","body":"<ul><li><strong>گام ۱ (اسپرسو و نیم‌وخامه):</strong> اسپرسو را بگیرید و نیم‌وخامه‌ی بخارداده‌شده را به‌جای شیر اضافه کنید.</li></ul>","kind":"item","description":"کافه بروه نوشیدنی اسپرسویی با شیر است که به‌جای شیر از «نیم‌وخامه» (half-and-half) بخارداده‌شده استفاده می‌کند.","difficulty":"","prepTime":"","totalTime":"","origin":"آمریکا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر","پارچ شیر و لوله‌ی بخار","ترازو"],"ingredients":[{"amount":"۱","unit":"شات","name":"اسپرسو"},{"amount":"—","unit":"","name":"نیم‌وخامه‌ی بخارداده‌شده"}],"steps":[{"label":"اسپرسو و نیم‌وخامه","text":"اسپرسو را بگیرید و نیم‌وخامه‌ی بخارداده‌شده را به‌جای شیر اضافه کنید."}],"proTip":"","variation":"موکا بروه: با حدود یک اونس شکلات، معمولاً همراه خامه‌ی زده‌شده. آیس بروه: روی یخ سرو می‌شود.","history":"","src":[["Wikipedia — Caff%C3%A8 breve","https://en.wikipedia.org/wiki/Caff%C3%A8_breve"]]},{"id":641,"title":"ملبورن مجیک (Melbourne Magic)","body":"<ul><li><strong>گام ۱ (ترکیب):</strong> دو شات ریسترتو را با سه‌چهارم یک فلت وایت ترکیب کنید.</li></ul>","kind":"item","description":"دو شات ریسترتو با سه‌چهارم یک فلت وایت.","difficulty":"","prepTime":"","totalTime":"","origin":"ملبورن، استرالیا","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"۲","unit":"شات","name":"ریسترتو"},{"amount":"—","unit":"","name":"فلت وایت (سه‌چهارم)"}],"steps":[{"label":"ترکیب","text":"دو شات ریسترتو را با سه‌چهارم یک فلت وایت ترکیب کنید."}],"proTip":"","variation":"","history":"","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":650,"title":"کافه بورجیا (Café Borgia)","body":"<ul><li><strong>گام ۱ (ترکیب):</strong> موکا را با پرتقال، خامه و دارچین تکمیل کنید.</li></ul>","kind":"item","description":"موکا با پوست یا طعم پرتقال، خامه‌ی زده‌شده و دارچین.","difficulty":"","prepTime":"","totalTime":"","origin":"","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"—","unit":"","name":"موکا"},{"amount":"—","unit":"","name":"پوست یا طعم پرتقال"},{"amount":"—","unit":"","name":"خامه‌ی زده‌شده"},{"amount":"—","unit":"","name":"دارچین"}],"steps":[{"label":"ترکیب","text":"موکا را با پرتقال، خامه و دارچین تکمیل کنید."}],"proTip":"","variation":"","history":"","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":674,"title":"موکاچینو (Mochaccino)","body":"<ul><li><strong>گام ۱ (ترکیب):</strong> لاته را با کاکائو یا شکلات ترکیب کنید.</li></ul>","kind":"item","description":"لاته با کاکائو یا شکلات در بخش‌هایی از اروپا و خاورمیانه، یا کاپوچینوی شکلاتی در آمریکا.","difficulty":"","prepTime":"","totalTime":"","origin":"","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"—","unit":"","name":"لاته"},{"amount":"—","unit":"","name":"کاکائو یا شکلات"}],"steps":[{"label":"ترکیب","text":"لاته را با کاکائو یا شکلات ترکیب کنید."}],"proTip":"","variation":"","history":"","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":675,"title":"بیچرین (Bicerin)","body":"<ul><li><strong>گام ۱ (لایه‌بندی):</strong> اجزا را در لیوان کوچک لایه‌لایه بریزید.</li></ul>","kind":"item","description":"نوشیدنی سنتی تورین که در لیوان کوچک لایه‌لایه سرو می‌شود: اسپرسو، گاناش (شکلات داغ غلیظ) و شیر کف‌دار.","difficulty":"","prepTime":"","totalTime":"","origin":"تورین، ایتالیا","caffeineLevel":0,"equipment":["لیوان کوچک شیشه‌ای"],"ingredients":[{"amount":"—","unit":"","name":"اسپرسو"},{"amount":"—","unit":"","name":"گاناش (شکلات داغ غلیظ)"},{"amount":"—","unit":"","name":"شیر کف‌دار"}],"steps":[{"label":"لایه‌بندی","text":"اجزا را در لیوان کوچک لایه‌لایه بریزید."}],"proTip":"","variation":"اسپرسینو و ماروکینو نوشیدنی‌های مشابه دانسته می‌شوند. صفحه ترتیب و نسبت لایه‌ها را نمی‌دهد.","history":"«بیچرین» در پیدمونتی یعنی «لیوان کوچک». کافه‌ی Caffè al Bicerin روبه‌روی زیارتگاه کونزولاتا در تورین از قرن هجدهم آن را سرو کرده است.","src":[["Wikipedia — Bicerin","https://en.wikipedia.org/wiki/Bicerin"]]}],"hero":"assets/images/espresso_milk.svg"},{"id":"espresso_extra","icon":"sparkle","title":"اسپرسو و افزودنی‌های خاص","items":[{"id":54,"title":"آفوگاتو (Affogato)","body":"<ul><li><strong>گام ۱ (جلاتو):</strong> یک گوله جلاتوی فیوردی‌لاته یا وانیلی در لیوان بلند و کم‌عرض در کف بگذارید.</li><li><strong>گام ۲ (اسپرسو):</strong> یک شات اسپرسو روی آن بریزید تا جلاتو آب شود و در ته لیوان با اسپرسو ترکیب شود.</li><li><strong>گام ۳ (سرو):</strong> اغلب پس از غذا به‌عنوان ترکیب قهوه‌ـ‌دسر با قاشق یا نی نوشیده می‌شود؛ بیسکوتی هم کنار آن سرو می‌شود.</li></ul>","kind":"item","description":"آفوگاتو (affogato al caffè، یعنی «غرق‌شده در قهوه») یک گوله بستنی جلاتو است که روی آن اسپرسو ریخته می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر"],"ingredients":[{"amount":"۱","unit":"گوله","name":"جلاتوی فیوردی‌لاته (شیری ساده) یا وانیلی"},{"amount":"۱","unit":"شات","name":"اسپرسو"}],"steps":[{"label":"جلاتو","text":"یک گوله جلاتوی فیوردی‌لاته یا وانیلی در لیوان بلند و کم‌عرض در کف بگذارید."},{"label":"اسپرسو","text":"یک شات اسپرسو روی آن بریزید تا جلاتو آب شود و در ته لیوان با اسپرسو ترکیب شود."},{"label":"سرو","text":"اغلب پس از غذا به‌عنوان ترکیب قهوه‌ـ‌دسر با قاشق یا نی نوشیده می‌شود؛ بیسکوتی هم کنار آن سرو می‌شود."}],"proTip":"","variation":"برخی نسخه‌ها یک شات آمارتو، بیچرین، کالوا یا لیکور دیگر اضافه می‌کنند؛ گاهی نارگیل، توت، شانه‌ی عسل یا چند طعم جلاتو هم می‌آید.","history":"خاستگاه آفوگاتو مشخص نیست. قدیمی‌ترین کاربرد ثبت‌شده‌ی این واژه در فرهنگ‌های انگلیسی‌زبان به سال ۱۹۸۸ برمی‌گردد.","src":[["Wikipedia — Affogato","https://en.wikipedia.org/wiki/Affogato"]]},{"id":55,"title":"کافه کورتو (Caffè Corretto)","body":"<ul><li><strong>گام ۱ (اسپرسو):</strong> یک شات اسپرسو بگیرید.</li><li><strong>گام ۲ (مشروب):</strong> معمولاً چند قطره از مشروب دلخواه را داخل شات اسپرسو می‌ریزند؛ گاهی مشروب جداگانه در یک شات کنار قهوه سرو می‌شود.</li></ul>","kind":"item","description":"کافه کورتو (caffè corretto) یک شات اسپرسو با مقدار کمی مشروب است؛ معمولاً گراپا و گاهی سامبوکا یا براندی.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر"],"ingredients":[{"amount":"۱","unit":"شات","name":"اسپرسو"},{"amount":"—","unit":"","name":"مقدار کمی مشروب (معمولاً گراپا، گاهی سامبوکا یا براندی)"}],"steps":[{"label":"اسپرسو","text":"یک شات اسپرسو بگیرید."},{"label":"مشروب","text":"معمولاً چند قطره از مشروب دلخواه را داخل شات اسپرسو می‌ریزند؛ گاهی مشروب جداگانه در یک شات کنار قهوه سرو می‌شود."}],"proTip":"این نوشیدنی الکل دارد.","variation":"سفارش‌ها بر اساس مشروب: corretto alla grappa، alla sambuca، al cognac یا corretto di Spadino. در اسپانیا نوشیدنی مشابه «کاراخیو» نام دارد.","history":"واژه‌ی ایتالیایی corretto به معنای «اصلاح‌شده» است. کافه کورتو در اریتره هم، به‌جا مانده از استعمار ایتالیا، رایج است و در آنجا از «آرکی» محلی و کنیاک استفاده می‌شود. «رِکسِنتین» سنتی در منطقه‌ی وِنِتو ایتالیاست: کمی قهوه در فنجان می‌ماند و با همان مشروب شسته می‌شود.","src":[["Wikipedia — Caff%C3%A8 corretto","https://en.wikipedia.org/wiki/Caff%C3%A8_corretto"]]},{"id":56,"title":"اسپرسو رومانو (Espresso Romano)","body":"<ul><li><strong>گام ۱ (اسپرسو و لیمو):</strong> اسپرسو را با یک تکه‌ی پیچ‌خورده‌ی پوست لیمو در کنار آن سرو کنید.</li></ul>","kind":"item","description":"اسپرسو رومانو اسپرسویی است که با یک تکه‌ی پیچ‌خورده‌ی پوست لیمو در کنار آن سرو می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر"],"ingredients":[{"amount":"۱","unit":"شات","name":"اسپرسو"},{"amount":"۱","unit":"تکه","name":"پوست لیمو (twist)"}],"steps":[{"label":"اسپرسو و لیمو","text":"اسپرسو را با یک تکه‌ی پیچ‌خورده‌ی پوست لیمو در کنار آن سرو کنید."}],"proTip":"","variation":"","history":"","src":[["Coffee Review — Traditional espresso drink descriptions","https://www.coffeereview.com/coffee-reference/espresso/espresso-cuisines/traditional-drink-descriptions/"]]},{"id":57,"title":"کافه تونیک (Coffee Tonic)","body":"<ul><li><strong>گام ۱ (تونیک و یخ):</strong> آب تونیک یخ‌دار را در لیوان بریزید؛ لیوان کالینز با نی پیشنهاد شده است.</li><li><strong>گام ۲ (اسپرسو):</strong> اسپرسو را روی تونیک یخ‌دار بریزید تا نوشیدنی لایه‌لایه شود.</li></ul>","kind":"item","description":"اسپرسو تونیک (کافه تونیک) از اسپرسو و آب تونیک ساخته می‌شود و می‌توان طعم‌دهنده‌ی دیگری هم به آن افزود.","difficulty":"","prepTime":"","totalTime":"","origin":"اسلو / سوئد (۲۰۰۷)","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب برر"],"ingredients":[{"amount":"—","unit":"","name":"اسپرسو"},{"amount":"—","unit":"","name":"آب تونیک (روی یخ)"},{"amount":"—","unit":"","name":"اختیاری: شربت شکر، تزئین لیمو یا طعم‌هایی مثل آلبالو، لیمو ترش و عسل"}],"steps":[{"label":"تونیک و یخ","text":"آب تونیک یخ‌دار را در لیوان بریزید؛ لیوان کالینز با نی پیشنهاد شده است."},{"label":"اسپرسو","text":"اسپرسو را روی تونیک یخ‌دار بریزید تا نوشیدنی لایه‌لایه شود."}],"proTip":"اگر ترتیب برعکس شود و تونیک روی اسپرسو ریخته شود، کفِ سر تشکیل می‌شود.","variation":"می‌توان شربت شکر، تزئین لیمو یا طعم‌هایی مثل آلبالو، لیمو ترش و عسل اضافه کرد؛ افزودن این طعم‌ها را به باریستاهای ژاپنی نسبت می‌دهند.","history":"قدیمی‌ترین سابقه‌ی ثبت‌شده به ۲۰۰۷ در اسلو برمی‌گردد، جایی که باریستایی آن را برای بنیان‌گذاران آینده‌ی شرکت سوئدی کوپی روسترز ترکیب کرد. بعدتر در همان سال با نام «Kaffe & Tonic» در منوی کوپی در هلسینگبورگ سوئد آمد. محبوبیتش در اسکاندیناوی بالا گرفت و در دهه‌ی ۲۰۱۰ از طریق مسابقات بین‌المللی باریستا به آمریکای شمالی رسید و تا ۲۰۱۵ به ژاپن رسید. در ۲۰۱۹ کافه نرو با فیور-تری دو نسخه از آن را عرضه کرد.","src":[["Wikipedia — Espresso and tonic","https://en.wikipedia.org/wiki/Espresso_and_tonic"]]},{"id":640,"title":"کافه زورو (Café Zorro)","body":"<ul><li><strong>گام ۱ (ترکیب):</strong> دوپیو را با آب داغ به نسبت ۱ به ۱ ترکیب کنید.</li></ul>","kind":"item","description":"دوپیو (اسپرسوی دوبل) که به آب داغ با نسبت ۱ به ۱ اضافه می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"۱","unit":"شات دوبل","name":"اسپرسو (دوپیو)"},{"amount":"۱","unit":"هم‌حجم اسپرسو","name":"آب داغ"}],"steps":[{"label":"ترکیب","text":"دوپیو را با آب داغ به نسبت ۱ به ۱ ترکیب کنید."}],"proTip":"","variation":"","history":"","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":642,"title":"باراکیتو (Barraquito)","body":"<ul><li><strong>گام ۱ (شیر تغلیظ‌شده):</strong> ابتدا شیر تغلیظ‌شده را در لیوان شفاف بریزید.</li><li><strong>گام ۲ (لیکور):</strong> لیکور ۴۳ (یا تیا ماریا) را روی آن اضافه کنید.</li><li><strong>گام ۳ (اسپرسو و لیمو):</strong> اسپرسو و سپس پوست لیمو را به همین ترتیب اضافه کنید.</li><li><strong>گام ۴ (شیر کف‌دار):</strong> شیر کف‌شده را به هر روشی که در دسترس است روی آن بریزید.</li><li><strong>گام ۵ (دارچین):</strong> در پایان کمی دارچین رویش بپاشید.</li></ul>","kind":"item","description":"نوشیدنی تنریفه با اسپرسو، شیر تغلیظ‌شده، شیر کف‌دار، لیمو، دارچین و لیکور ۴۳.","difficulty":"","prepTime":"","totalTime":"","origin":"تنریفه","caffeineLevel":0,"equipment":["لیوان شفاف بلند (برای دیدن لایه‌ها)"],"ingredients":[{"amount":"—","unit":"","name":"اسپرسو"},{"amount":"—","unit":"","name":"شیر تغلیظ‌شده"},{"amount":"—","unit":"","name":"شیر کف‌دار"},{"amount":"—","unit":"","name":"لیمو"},{"amount":"—","unit":"","name":"دارچین"},{"amount":"—","unit":"","name":"لیکور ۴۳"}],"steps":[{"label":"شیر تغلیظ‌شده","text":"ابتدا شیر تغلیظ‌شده را در لیوان شفاف بریزید."},{"label":"لیکور","text":"لیکور ۴۳ (یا تیا ماریا) را روی آن اضافه کنید."},{"label":"اسپرسو و لیمو","text":"اسپرسو و سپس پوست لیمو را به همین ترتیب اضافه کنید."},{"label":"شیر کف‌دار","text":"شیر کف‌شده را به هر روشی که در دسترس است روی آن بریزید."},{"label":"دارچین","text":"در پایان کمی دارچین رویش بپاشید."}],"proTip":"","variation":"باراکیتو اسپسیال: نسخه‌ی کامل با لیکور، دارچین و لیمو. باراکیتو ویرخن: بدون الکل و بدون لیکور. در شمال جزیره، در مناطقی مثل پورتو د لا کروز و بوئنا‌ویستا، نام «ساپروکو» هم برای آن به کار می‌رود. در سانتا کروز و لا لاگونا اگر فقط «باراکیتو» سفارش دهید، معمولاً قهوه با شیر تغلیظ‌شده و شیر معمولی می‌آید.","history":"طبق باور رایج در سانتا کروز دو تنریفه، این نوشیدنی در میانه‌ی قرن بیستم پدید آمد. یک روایت آن را به دون سباستین روبیو، مشتری بار امپریال، می‌رساند که کورتادو با شیر تغلیظ‌شده، یک شات لیکور ۴۳، پوست لیمو و دارچین را در لیوانی بلند سفارش می‌داد.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Wikipedia — Barraquito","https://en.wikipedia.org/wiki/Barraquito"]]},{"id":651,"title":"کافه سریع و کثیف (Quick and Dirty)","body":"<ul><li><strong>گام ۱ (ترکیب):</strong> اسپرسو را با شربت شکلات یا موکا ترکیب کنید.</li></ul>","kind":"item","description":"سه شات اسپرسو با شربت شکلات یا موکا؛ چهار شات یا بیشتر «Fast & Filthy» نام دارد.","difficulty":"","prepTime":"","totalTime":"","origin":"","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"۳","unit":"شات","name":"اسپرسو"},{"amount":"—","unit":"","name":"شربت شکلات یا موکا"}],"steps":[{"label":"ترکیب","text":"اسپرسو را با شربت شکلات یا موکا ترکیب کنید."}],"proTip":"","variation":"چهار شات یا بیشتر: «Fast & Filthy».","history":"","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":653,"title":"پدروکی (Pedrocchi)","body":"<ul><li><strong>گام ۱ (اسپرسو):</strong> اسپرسوی داغ را لایه‌ی پایینی لیوان قرار دهید.</li><li><strong>گام ۲ (خامه و شربت نعنا):</strong> خامه‌ی تازه و شربت نعنا را به‌صورت لایه‌ی غلیظ میانی روی اسپرسو بریزید.</li><li><strong>گام ۳ (کاکائو):</strong> پودر کاکائو را روی آن بپاشید.</li><li><strong>گام ۴ (سرو):</strong> هم نزنید و شیرین نکنید.</li></ul>","kind":"item","description":"اسپرسو، شربت نعنا با خامه‌ی تازه و پودر کاکائو روی آن؛ نه هم زده می‌شود و نه شیرین.","difficulty":"","prepTime":"","totalTime":"","origin":"پادوا، ایتالیا","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"—","unit":"","name":"اسپرسو"},{"amount":"—","unit":"","name":"شربت نعنا با خامه‌ی تازه"},{"amount":"—","unit":"","name":"پودر کاکائو"}],"steps":[{"label":"اسپرسو","text":"اسپرسوی داغ را لایه‌ی پایینی لیوان قرار دهید."},{"label":"خامه و شربت نعنا","text":"خامه‌ی تازه و شربت نعنا را به‌صورت لایه‌ی غلیظ میانی روی اسپرسو بریزید."},{"label":"کاکائو","text":"پودر کاکائو را روی آن بپاشید."},{"label":"سرو","text":"هم نزنید و شیرین نکنید."}],"proTip":"","variation":"","history":"","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":654,"title":"کافه مدیچی (Caffè Medici)","body":"<ul><li><strong>گام ۱ (ترکیب):</strong> دوپیو را روی شربت شکلات و پوست پرتقال بگیرید و خامه بگذارید.</li></ul>","kind":"item","description":"دوپیو روی شربت شکلات و پوست پرتقال با خامه‌ی زده‌شده.","difficulty":"","prepTime":"","totalTime":"","origin":"سیاتل","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"۱","unit":"شات دوبل","name":"اسپرسو (دوپیو)"},{"amount":"—","unit":"","name":"شربت شکلات"},{"amount":"—","unit":"","name":"پوست پرتقال"},{"amount":"—","unit":"","name":"خامه‌ی زده‌شده"}],"steps":[{"label":"ترکیب","text":"دوپیو را روی شربت شکلات و پوست پرتقال بگیرید و خامه بگذارید."}],"proTip":"","variation":"","history":"خاستگاه آن را کافه‌ی Last Exit on Brooklyn در سیاتل می‌دانند.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":666,"title":"فلت رد (Flat Red)","body":"<ul><li><strong>گام ۱ (ترکیب):</strong> اسپرسو را با آب میوه‌ی بخارداده‌شده ترکیب کنید.</li></ul>","kind":"item","description":"اسپرسو با آب پرتقال و انار بخارداده‌شده، بدون شیر و شکر.","difficulty":"","prepTime":"","totalTime":"","origin":"کی‌یف، اوکراین","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"—","unit":"","name":"اسپرسو"},{"amount":"—","unit":"","name":"آب پرتقال و انار بخارداده‌شده"}],"steps":[{"label":"ترکیب","text":"اسپرسو را با آب میوه‌ی بخارداده‌شده ترکیب کنید."}],"proTip":"","variation":"","history":"آن را ساخته‌ی باریستای اوکراینی وادیم گرانوفسکی در کی‌یف در ۲۰۱۶ می‌دانند.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":673,"title":"کافه توبیو (Caffè Tobio)","body":"<ul><li><strong>گام ۱ (ترکیب):</strong> قهوه و اسپرسو را به‌اندازه‌ی مساوی ترکیب کنید.</li></ul>","kind":"item","description":"قهوه و اسپرسو به‌اندازه‌ی مساوی.","difficulty":"","prepTime":"","totalTime":"","origin":"","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"۱","unit":"بخش","name":"قهوه"},{"amount":"۱","unit":"بخش","name":"اسپرسو"}],"steps":[{"label":"ترکیب","text":"قهوه و اسپرسو را به‌اندازه‌ی مساوی ترکیب کنید."}],"proTip":"","variation":"","history":"","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]}],"hero":"assets/images/espresso_extra.svg"},{"id":"pour_over","icon":"pourover","title":"دم‌آوری ثقلی (پوراوور)","items":[{"id":62,"title":"وی‌شصت (V۶۰)","body":"<ul><li><strong>گام ۱ (خیساندن فیلتر):</strong> ابتدا کمی آب داغ روی فیلتر کاغذی بریزید تا طعم کاغذ برود.</li><li><strong>گام ۲ (بلوم):</strong> مقدار کمی آب داغ روی قهوه بریزید و حدود ۳۰ تا ۴۵ ثانیه صبر کنید؛ گاز دی‌اکسیدکربن از قهوه خارج می‌شود و طعم بهتر می‌شود.</li><li><strong>گام ۳ (ریختن آب):</strong> بقیه‌ی آب سنجیده‌شده را آهسته و دایره‌وار روی قهوه بریزید. ریختن خیلی سریع نتیجه‌ی آبکی‌تر و ریختن آهسته طعم غنی‌تر می‌دهد.</li></ul>","kind":"item","description":"وی‌شصت یک دریپر مخروطی است که یک سوراخ بزرگ در ته دارد؛ طبق توضیح سازنده با تغییر سرعت ریختن آب می‌توان قهوه را قوی‌تر یا سبک‌تر گرفت.","difficulty":"","prepTime":"","totalTime":"","origin":"ژاپن","caffeineLevel":0,"equipment":["V60","فیلتر کونیکال","کتری گردن‌غازی","ترازو"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی آسیاب‌شده"},{"amount":"—","unit":"","name":"آب داغ"}],"steps":[{"label":"خیساندن فیلتر","text":"ابتدا کمی آب داغ روی فیلتر کاغذی بریزید تا طعم کاغذ برود."},{"label":"بلوم","text":"مقدار کمی آب داغ روی قهوه بریزید و حدود ۳۰ تا ۴۵ ثانیه صبر کنید؛ گاز دی‌اکسیدکربن از قهوه خارج می‌شود و طعم بهتر می‌شود.","meta":"۳۰–۴۵ ثانیه"},{"label":"ریختن آب","text":"بقیه‌ی آب سنجیده‌شده را آهسته و دایره‌وار روی قهوه بریزید. ریختن خیلی سریع نتیجه‌ی آبکی‌تر و ریختن آهسته طعم غنی‌تر می‌دهد."}],"proTip":"سازنده می‌نویسد: تغییر سرعت ریختن امکان دم‌کردن قهوه‌ی «قوی‌تر یا سبک‌تر» را به سلیقه‌ی شما می‌دهد.","variation":"وی‌شصت در اندازه‌ی ۰۱ (برای یک تا دو فنجان) و ۰۲ و در جنس‌های پلاستیکی، شیشه‌ی نسوز و سرامیکی عرضه می‌شود.","history":"هاریو V۶۰ را در سال ۲۰۰۴ عرضه کرد. فیلتر کاغذی قهوه را ملیتا بنتز در آلمان در ۱۹۰۸ اختراع کرد.","src":[["Hario Europe — V60 Dripper Plastic 01","https://hario-europe.com/products/hario-v60-dripper-plastic-01"],["Wikipedia — Pour-over coffee","https://en.wikipedia.org/wiki/Pour-over_coffee"]]},{"id":63,"title":"کمکس (Chemex)","body":"<ul><li><strong>گام ۱ (خیساندن فیلتر):</strong> فیلتر کمکس را با آب داغ بشویید تا طعم کاغذ برود.</li><li><strong>گام ۲ (آسیاب):</strong> قهوه را درشت آسیاب کنید؛ برای بهترین طعم باید شبیه نمک کوشر باشد.</li><li><strong>گام ۳ (دم‌آوری):</strong> آب ۹۳ تا ۹۶ درجه را از میان قهوه و فیلتر عبور دهید.</li></ul>","kind":"item","description":"کمکس شیشه‌ای ساعت‌شنی با قیف مخروطی و یقه‌ی چوبی است که فیلتر کاغذی ضخیم مخصوص خودش را دارد.","difficulty":"","prepTime":"","totalTime":"","origin":"آمریکا","caffeineLevel":0,"equipment":["کمکس","فیلتر کمکس","کتری گردن‌غازی","ترازو"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی درشت‌آسیاب (شبیه نمک کوشر)"},{"amount":"—","unit":"","name":"آب ۹۳ تا ۹۶ درجه‌ی سانتی‌گراد"}],"steps":[{"label":"خیساندن فیلتر","text":"فیلتر کمکس را با آب داغ بشویید تا طعم کاغذ برود."},{"label":"آسیاب","text":"قهوه را درشت آسیاب کنید؛ برای بهترین طعم باید شبیه نمک کوشر باشد."},{"label":"دم‌آوری","text":"آب ۹۳ تا ۹۶ درجه را از میان قهوه و فیلتر عبور دهید.","meta":"۹۳–۹۶ درجه‌ی سانتی‌گراد"}],"proTip":"فیلترهای کمکس از کاغذ چسبانده‌شده ساخته می‌شوند و از فیلترهای معمولی ضخیم‌ترند.","variation":"","history":"کمکس را پیتر شلومباوم در ۱۹۴۱ اختراع کرد و شرکت کمکس در چیکوپی ماساچوست آن را تولید می‌کرد.","src":[["Wikipedia — Chemex Coffeemaker","https://en.wikipedia.org/wiki/Chemex_Coffeemaker"]]},{"id":64,"title":"کالیتا ویو (Kalita Wave)","body":"<ul><li><strong>گام ۱ (بلوم):</strong> ۵۰ گرم آب بریزید و تا ثانیه‌ی ۰:۳۰ صبر کنید.</li><li><strong>گام ۲ (ریختن دوم):</strong> در ثانیه‌ی ۰:۳۰ ۱۰۰ گرم دیگر بریزید (مجموع ۱۵۰).</li><li><strong>گام ۳ (ریختن سوم):</strong> در ثانیه‌ی ۱:۱۰ ۱۰۰ گرم باقی را بریزید (مجموع ۲۵۰). کل زمان ۲:۳۰ تا ۳:۰۰.</li></ul>","kind":"item","description":"کالیتا ویو دریپر کف‌تخت ژاپنی با سه سوراخ کوچک در کف است و فیلتر موجی دارد که کاغذ را از بیشتر دیواره دور نگه می‌دارد.","difficulty":"","prepTime":"","totalTime":"","origin":"ژاپن","caffeineLevel":0,"equipment":["کالیتا ویو","فیلتر موجی","کتری گردن‌غازی","ترازو"],"ingredients":[{"amount":"۱۵","unit":"گرم","name":"قهوه‌ی آسیاب‌شده‌ی متوسط (ویو ۱۵۵؛ برای ویو ۱۸۵: ۳۰ گرم)"},{"amount":"۲۵۰","unit":"گرم","name":"آب ۹۳ درجه (ویو ۱۸۵: ۵۰۰ گرم)"}],"steps":[{"label":"بلوم","text":"۵۰ گرم آب بریزید و تا ثانیه‌ی ۰:۳۰ صبر کنید.","meta":"۵۰ گرم · ۰:۳۰"},{"label":"ریختن دوم","text":"در ثانیه‌ی ۰:۳۰ ۱۰۰ گرم دیگر بریزید (مجموع ۱۵۰).","meta":"۱۵۰ گرم"},{"label":"ریختن سوم","text":"در ثانیه‌ی ۱:۱۰ ۱۰۰ گرم باقی را بریزید (مجموع ۲۵۰). کل زمان ۲:۳۰ تا ۳:۰۰.","meta":"۲۵۰ گرم · ۲:۳۰–۳:۰۰"}],"proTip":"برای ویو ۱۸۵ (برای دو نفر): ۳۰ گرم قهوه و ۵۰۰ گرم آب ۹۳ درجه؛ بلوم ۱۰۰ گرم تا ۰:۳۰، سپس تا ۳۰۰ گرم در ۰:۳۰ و تا ۵۰۰ گرم در ۱:۳۰؛ کل زمان ۳:۳۰ تا ۴:۰۰. (دستور از راهنمای یک برشته‌کار.)","variation":"ویو ۱۵۵ برای فنجان‌های حدود ۲۰۰ تا ۲۵۰ میلی‌لیتر مناسب است و ویو ۱۸۵ برای ۴۰۰ تا ۵۰۰ میلی‌لیتر یا بیشتر.","history":"","src":[["Ozone Coffee Roasters — How to use a Kalita Wave","https://ozonecoffee.co.uk/pages/kalita-wave-brew-guide"]]},{"id":65,"title":"ریخته‌گری معمولی/دستی (Pour-Over)","body":"<ul><li><strong>گام ۱ (شستن فیلتر):</strong> فیلتر کاغذی را با کمی آب داغ خیس کنید تا طعم کاغذ از بین برود.</li><li><strong>گام ۲ (ریختن قهوه):</strong> قهوه را داخل فیلتر بریزید و سطح آن را صاف کنید.</li><li><strong>گام ۳ (بلوم):</strong> کمی آب داغ روی قهوه بریزید و حدود ۳۰ تا ۴۵ ثانیه صبر کنید تا گاز آزاد شود.</li><li><strong>گام ۴ (ریختن آهسته):</strong> باقی آب را آهسته و با حرکت دایره‌وار روی قهوه بریزید؛ ریختن سریع، فنجان را کم‌مایه می‌کند.</li><li><strong>گام ۵ (چرخاندن ملایم):</strong> در صورت تمایل، بستر قهوه را آرام بچرخانید تا استخراج بیشتر شود.</li></ul>","kind":"item","description":"در روش ریختن دستی (پوراوور) آب داغ روی بستر قهوه در یک فیلتر ریخته می‌شود و هنگام عبور، قهوه را دم می‌کند.","difficulty":"","prepTime":"","totalTime":"","origin":"آلمان (فیلتر کاغذی)","caffeineLevel":0,"equipment":["دریپر و فیلتر","کتری گردن‌غازی","ترازو و تایمر","آسیاب برر"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی آسیاب‌شده"},{"amount":"—","unit":"","name":"آب داغ"}],"steps":[{"label":"شستن فیلتر","text":"فیلتر کاغذی را با کمی آب داغ خیس کنید تا طعم کاغذ از بین برود."},{"label":"ریختن قهوه","text":"قهوه را داخل فیلتر بریزید و سطح آن را صاف کنید."},{"label":"بلوم","text":"کمی آب داغ روی قهوه بریزید و حدود ۳۰ تا ۴۵ ثانیه صبر کنید تا گاز آزاد شود.","meta":"۳۰–۴۵ ثانیه"},{"label":"ریختن آهسته","text":"باقی آب را آهسته و با حرکت دایره‌وار روی قهوه بریزید؛ ریختن سریع، فنجان را کم‌مایه می‌کند."},{"label":"چرخاندن ملایم","text":"در صورت تمایل، بستر قهوه را آرام بچرخانید تا استخراج بیشتر شود."}],"proTip":"کیفیت قهوه به‌شدت به تکنیک دم‌کننده بستگی دارد؛ هم‌زدن یا چرخاندن می‌تواند استخراج را بیشتر کند. فیلتر کاغذی قهوه‌ی شفاف و سبک‌بدنه می‌دهد.","variation":"","history":"فیلتر کاغذی قهوه را ملیتا بنتز در ۱۹۰۸ در آلمان اختراع کرد.","src":[["Wikipedia — Pour-over coffee","https://en.wikipedia.org/wiki/Pour-over_coffee"],["Wikipedia — Drip brewing","https://en.wikipedia.org/wiki/Drip_brewing"]]}],"hero":"assets/images/pour_over.svg"},{"id":"immersion","icon":"immersion","title":"غوطه‌وری و تحت فشار","items":[{"id":69,"title":"فرنچ پرس (French Press)","body":"<ul><li><strong>گام ۱ (آسیاب):</strong> قهوه را درشت، حدود شبیه نمک آشپزی، آسیاب کنید. حدود ۳۰ گرم برای ۵۰۰ میلی‌لیتر آب (قابل تنظیم با سلیقه).</li><li><strong>گام ۲ (آب):</strong> آب ۹۳ تا ۹۶ درجه اضافه کنید.</li><li><strong>گام ۳ (خیساندن):</strong> برخی نویسنده‌ها زمان بهینه را حدود چهار دقیقه می‌دانند.</li><li><strong>گام ۴ (پرس):</strong> پیستون را آهسته پایین ببرید؛ پایین‌بردن آهسته از پاشیدن آب داغ و سوختگی جلوگیری می‌کند.</li></ul>","kind":"item","description":"در فرنچ پرس قهوه‌ی درشت در آب داغ خیس می‌خورد و بعد با پیستون جدا می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"فرانسه / ایتالیا","caffeineLevel":0,"equipment":["فرنچ پرس","آسیاب برر (درشت)","کتری","ترازو و تایمر"],"ingredients":[{"amount":"۳۰","unit":"گرم","name":"قهوه‌ی درشت‌آسیاب (شبیه نمک آشپزی)"},{"amount":"۵۰۰","unit":"میلی‌لیتر","name":"آب ۹۳ تا ۹۶ درجه"}],"steps":[{"label":"آسیاب","text":"قهوه را درشت، حدود شبیه نمک آشپزی، آسیاب کنید. حدود ۳۰ گرم برای ۵۰۰ میلی‌لیتر آب (قابل تنظیم با سلیقه).","meta":"۳۰ گرم / ۵۰۰ میلی‌لیتر"},{"label":"آب","text":"آب ۹۳ تا ۹۶ درجه اضافه کنید.","meta":"۹۳–۹۶ درجه‌ی سانتی‌گراد"},{"label":"خیساندن","text":"برخی نویسنده‌ها زمان بهینه را حدود چهار دقیقه می‌دانند.","meta":"≈۴ دقیقه"},{"label":"پرس","text":"پیستون را آهسته پایین ببرید؛ پایین‌بردن آهسته از پاشیدن آب داغ و سوختگی جلوگیری می‌کند."}],"proTip":"زیر پیستون در پایین‌ترین حالتش حدود ۳۰ میلی‌متر فضای خالی می‌ماند. دم‌آوری سرد چند ساعت زمان می‌برد.","variation":"فرنچ‌پول (فرنچ پرس معکوس): قهوه در سبدی توری قرار دارد و بعد از دم‌آوری به سمت درپوش کشیده می‌شود. مدل‌های مسافرتی و عایق‌دار هم هست و می‌توان از فرنچ پرس برای کلد برو استفاده کرد.","history":"در ۱۸۱۲ بنجامین تامسون دستگاه دم‌آوری «چکه‌ـ‌پرس» ساخت. در ۱۸۵۲ هانری‌اتو مایر و ژاک‌ویکتور دلفورژ پیشینی از فرنچ پرس را ثبت کردند که دور فیلتر آب‌بندی نداشت. در ۱۹۲۴ ثبت اختراع مارسل‌پیر پاکه (ژولبر) منتشر شد. در ۱۹۲۸–۱۹۲۹ جولیو مونتا و آتیلیو کالیمانی پرسی با فنر برای آب‌بندی فیلتر ساختند و در ۱۹۲۹ در آمریکا ثبت کردند. در ۱۹۵۸ فالیرو بوندانینی نسخه‌ی خود را ثبت کرد و با نام «ملیور» در کارخانه‌ی مارتن فرانسه ساخت.","src":[["Wikipedia — French press","https://en.wikipedia.org/wiki/French_press"]]},{"id":70,"title":"موکاپات (Moka Pot – قهوه‌جوش روی اجاق)","body":"<ul><li><strong>گام ۱ (پر کردن مخزن):</strong> مخزن پایین را تا خط حکاکی‌شده یا کمی زیر سوپاپ ایمنی از آب پر کنید.</li><li><strong>گام ۲ (قرار دادن فیلتر):</strong> قیف فیلتر را داخل مخزن بگذارید.</li><li><strong>گام ۳ (ریختن قهوه):</strong> قهوه‌ی ریزآسیاب‌شده را در قیف بریزید و سطحش را صاف کنید؛ فشرده‌تر بودن، جریان را کندتر و استخراج را بیشتر می‌کند.</li><li><strong>گام ۴ (بستن):</strong> بخش بالایی را محکم ببندید تا واشر آب‌بندی شود.</li><li><strong>گام ۵ (حرارت):</strong> روی حرارت متوسط بگذارید و وقتی صدای قل‌قل شنیدید، موکاپات را از روی حرارت بردارید تا قهوه بیش‌ازحد استخراج نشود.</li></ul>","kind":"item","description":"موکاپات روی اجاق قهوه‌ای غلیظ با فشار کم (۱ تا ۲ بار) استخراج می‌کند؛ اسپرسو طبق استاندارد ۹ بار فشار دارد.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا","caffeineLevel":0,"equipment":["موکاپات","آسیاب برر","اجاق"],"ingredients":[{"amount":"۱:۱۰","unit":"","name":"نسبت تقریبی قهوه به آب بر اساس جرم"},{"amount":"—","unit":"","name":"قهوه‌ی ریزآسیاب‌شده"},{"amount":"—","unit":"","name":"آب تا خط سوپاپ"}],"steps":[{"label":"پر کردن مخزن","text":"مخزن پایین را تا خط حکاکی‌شده یا کمی زیر سوپاپ ایمنی از آب پر کنید."},{"label":"قرار دادن فیلتر","text":"قیف فیلتر را داخل مخزن بگذارید."},{"label":"ریختن قهوه","text":"قهوه‌ی ریزآسیاب‌شده را در قیف بریزید و سطحش را صاف کنید؛ فشرده‌تر بودن، جریان را کندتر و استخراج را بیشتر می‌کند."},{"label":"بستن","text":"بخش بالایی را محکم ببندید تا واشر آب‌بندی شود."},{"label":"حرارت","text":"روی حرارت متوسط بگذارید و وقتی صدای قل‌قل شنیدید، موکاپات را از روی حرارت بردارید تا قهوه بیش‌ازحد استخراج نشود."}],"proTip":"ظرفیت موکاپات‌ها از یک تا هجده سروینگ ۵۰ میلی‌لیتری متغیر است؛ هر فنجان تقریباً ۴۰ تا ۶۰ میلی‌لیتر. در نمونه‌های آلومینیومی «موکا اکسپرس»: ۱ فنجان ۶۰، ۲ فنجان ۹۰، ۳ فنجان ۱۳۰، ۶ فنجان ۲۵۰، ۱۲ فنجان ۵۹۵ و ۱۸ فنجان ۸۰۰ میلی‌لیتر. مواد جامد محلول: حدود ۳ تا ۴ درصد (اسپرسو ۹ تا ۱۰، قطره‌ای حدود ۲).","variation":"سوپاپ وزنه‌دار «کرمه‌وانت» جریان را سریع‌تر می‌کند و کرمای بیشتری می‌دهد. موکاپات‌های استیل برای اجاق القایی مناسب‌اند.","history":"ساموئل پارکر، مسگری از میدلسکس انگلستان، در ۱۱ ژانویه ۱۸۳۳ حق ثبت دریافت کرد. آلفونسو بیالتی از ۱۹۳۳ «موکا اکسپرس» را برای مصرف خانگی عرضه و رایج کرد. پسرش رناتو در دهه‌ی ۱۹۴۰ بنگاه خانوادگی را به دست گرفت و تبلیغات او به تثبیت آن کمک کرد؛ نماد معروف در ۱۹۵۲ آمد.","src":[["Wikipedia — Moka pot","https://en.wikipedia.org/wiki/Moka_pot"]]},{"id":71,"title":"ایروپرس (AeroPress)","body":"<ul><li><strong>گام ۱ (آماده‌سازی):</strong> فیلتر کاغذی را در درپوش بگذارید و درپوش را روی استوانه ببندید.</li><li><strong>گام ۲ (ریختن قهوه):</strong> قهوه‌ی ریزآسیاب‌شده را در استوانه بریزید.</li><li><strong>گام ۳ (ریختن آب):</strong> آب داغ را روی قهوه بریزید.</li><li><strong>گام ۴ (هم‌زدن):</strong> حدود ۱۰ ثانیه هم بزنید و در مسابقات ۳۰ تا ۶۰ ثانیه صبر می‌کنند.</li><li><strong>گام ۵ (فشار دادن):</strong> پیستون را یکنواخت و آرام پایین بفشارید تا قهوه از فیلتر رد شود.</li></ul>","kind":"item","description":"ایروپرس دم‌کننده‌ی دستی است که قهوه را داخل استوانه خیسانده و با پیستون از فیلتر کاغذی عبور می‌دهد؛ می‌تواند قهوه‌ای غلیظ شبیه اسپرسو یا قهوه‌ی فیلتری بسازد.","difficulty":"","prepTime":"","totalTime":"","origin":"آمریکا","caffeineLevel":0,"equipment":["استوانه‌ی دم‌آوری","پیستون با واشر سیلیکونی","درپوش فیلتر و فیلتر کاغذی","قاشق پیمانه و همزن","ترازو و تایمر"],"ingredients":[{"amount":"۱۴–۲۰","unit":"گرم","name":"قهوه (مقدار مسابقات)"},{"amount":"۲۰۰–۲۳۰","unit":"میلی‌لیتر","name":"آب ۸۰ تا ۹۲ درجه (۸۰ برای برشته‌ی تیره، ۸۵ برای روشن در دستورالعمل رسمی)"}],"steps":[{"label":"آماده‌سازی","text":"فیلتر کاغذی را در درپوش بگذارید و درپوش را روی استوانه ببندید."},{"label":"ریختن قهوه","text":"قهوه‌ی ریزآسیاب‌شده را در استوانه بریزید."},{"label":"ریختن آب","text":"آب داغ را روی قهوه بریزید."},{"label":"هم‌زدن","text":"حدود ۱۰ ثانیه هم بزنید و در مسابقات ۳۰ تا ۶۰ ثانیه صبر می‌کنند.","meta":"۳۰–۶۰ ثانیه"},{"label":"فشار دادن","text":"پیستون را یکنواخت و آرام پایین بفشارید تا قهوه از فیلتر رد شود."}],"proTip":"در روش وارونه (Inverted) کل ایروپرس سرپا ولی وارونه، روی سر پیستون، قرار می‌گیرد.","variation":"روش وارونه: پیستون را اول داخل استوانه می‌گذارند و دستگاه را وارونه می‌ایستانند تا قهوه و آب مثل فرنچ پرس مدت بیشتری بخیسند. مدل‌های گو و ایکس‌ال هم وجود دارند.","history":"ایروپرس را آلن آدلر، مدرس بازنشسته‌ی مهندسی استنفورد، اختراع کرد؛ ساخت نمونه در گاراژش را در ۲۰۰۴ آغاز کرد و در نوامبر ۲۰۰۵ در نمایشگاه کافی‌فست سیاتل رونمایی شد. آدلر آن را از طریق شرکتش «آئروبی» می‌فروخت و در ۲۰۱۷ اسپین مستر حقوق آئروبی را خرید. در مسابقات جهانی ایروپرس شرکت‌کنندگان پنج دقیقه برای دم‌کردن وقت دارند؛ رویداد ۲۰۱۸ حدود ۳۱۵۷ شرکت‌کننده از ۶۱ کشور داشت. هر بسته شامل ۳۵۰ فیلتر کاغذی گرد است.","src":[["Wikipedia — AeroPress","https://en.wikipedia.org/wiki/AeroPress"]]},{"id":72,"title":"کلور دریپر (Clever Dripper)","body":"<ul><li><strong>گام ۱ (آسیاب):</strong> قهوه را متوسط آسیاب کنید (بین فرنچ پرس و پوراوور).</li><li><strong>گام ۲ (آماده‌سازی فیلتر):</strong> فیلتر کاغذی را در دریپر بگذارید، با آب داغ بشویید و آب را دور بریزید.</li><li><strong>گام ۳ (ریختن قهوه):</strong> ۱۵ گرم قهوه را داخل فیلتر بریزید و دریپر را تکان دهید تا سطحش صاف شود.</li><li><strong>گام ۴ (ریختن آب):</strong> ۲۲۵ گرم آب داغ را یکجا روی قهوه بریزید و درپوش را بگذارید.</li><li><strong>گام ۵ (خیساندن):</strong> بعد از حدود ۲ دقیقه کم‌کم هم بزنید تا قشر بالایی پایین بنشیند؛ در مجموع ۴ دقیقه صبر کنید.</li><li><strong>گام ۶ (تخلیه):</strong> دریپر را روی فنجان یا کارافه بگذارید تا شیر باز شود و قهوه ۱ تا ۲ دقیقه بچکد.</li></ul>","kind":"item","description":"کلور دریپر قیفی با شیر در ته آن است: قهوه مثل فرنچ‌پرس خیس می‌خورد و بعد مثل دریپ از فیلتر کاغذی می‌چکد.","difficulty":"","prepTime":"","totalTime":"","origin":"تایوان","caffeineLevel":0,"equipment":["کلور دریپر با شیر تخلیه","فیلتر کاغذی","کتری برقی","ترازو","آسیاب برر"],"ingredients":[{"amount":"۱۵","unit":"گرم","name":"قهوه‌ی تازه‌آسیاب (متوسط)"},{"amount":"۲۲۵","unit":"گرم","name":"آب داغ"}],"steps":[{"label":"آسیاب","text":"قهوه را متوسط آسیاب کنید (بین فرنچ پرس و پوراوور)."},{"label":"آماده‌سازی فیلتر","text":"فیلتر کاغذی را در دریپر بگذارید، با آب داغ بشویید و آب را دور بریزید."},{"label":"ریختن قهوه","text":"۱۵ گرم قهوه را داخل فیلتر بریزید و دریپر را تکان دهید تا سطحش صاف شود."},{"label":"ریختن آب","text":"۲۲۵ گرم آب داغ را یکجا روی قهوه بریزید و درپوش را بگذارید."},{"label":"خیساندن","text":"بعد از حدود ۲ دقیقه کم‌کم هم بزنید تا قشر بالایی پایین بنشیند؛ در مجموع ۴ دقیقه صبر کنید.","meta":"۴ دقیقه"},{"label":"تخلیه","text":"دریپر را روی فنجان یا کارافه بگذارید تا شیر باز شود و قهوه ۱ تا ۲ دقیقه بچکد.","meta":"۱–۲ دقیقه"}],"proTip":"اگر تخلیه کند بود، اول آب داغ را در دریپر بریزید و بعد قهوه را اضافه کنید تا ذرات ته فیلتر فشرده نشوند. دریپر را روی فنجان پایدار بگذارید.","variation":"نسخه‌ی یخی: آب ۹۶ درجه (۲۰۵ فارنهایت).","history":"کلور دریپر را شرکت تایوانی E.K. INT'L (تأسیس ۱۹۹۶) ساخته؛ نام برند ABID مخفف «Absolutely Best Idea Development» است و سیستم قطع‌کننده‌ی ته آن در کشورهای زیادی ثبت اختراع شده است.","src":[["Brew Coffee Home — Clever Coffee Dripper","https://www.brewcoffeehome.com/clever-coffee-dripper/"]]},{"id":73,"title":"سیفون (Siphon / Vacuum Pot)","body":"<ul><li><strong>گام ۱ (آب):</strong> آب را در مخزن پایین بریزید.</li><li><strong>گام ۲ (مونتاژ):</strong> لوله و فیلتر را جا بزنید و قهوه را در محفظه‌ی بالا بریزید.</li><li><strong>گام ۳ (گرما):</strong> مخزن پایین را گرم کنید تا بخار، آب را از لوله به محفظه‌ی بالا براند.</li><li><strong>گام ۴ (خیساندن):</strong> حرارت را ثابت نگه دارید تا قهوه در آبی که کمی زیر نقطه‌ی جوش است دم بکشد.</li><li><strong>گام ۵ (پایین کشیدن):</strong> حرارت را قطع کنید تا فشار پایین بیاید و قهوه از فیلتر به مخزن پایین برگردد.</li></ul>","kind":"item","description":"سیفون با بخار و اختلاف فشار آب را به محفظه‌ی بالا می‌برد و قهوه را در آنجا به آب اضافه می‌کنند.","difficulty":"","prepTime":"","totalTime":"","origin":"آلمان","caffeineLevel":0,"equipment":["محفظه‌ی بالا و پایین (شیشه‌ی بوروسیلیکات)","لوله‌ی سیفون","فیلتر (توری یا پارچه یا کاغذی)","منبع حرارت"],"ingredients":[{"amount":"—","unit":"","name":"قهوه"},{"amount":"—","unit":"","name":"آب"}],"steps":[{"label":"آب","text":"آب را در مخزن پایین بریزید."},{"label":"مونتاژ","text":"لوله و فیلتر را جا بزنید و قهوه را در محفظه‌ی بالا بریزید."},{"label":"گرما","text":"مخزن پایین را گرم کنید تا بخار، آب را از لوله به محفظه‌ی بالا براند."},{"label":"خیساندن","text":"حرارت را ثابت نگه دارید تا قهوه در آبی که کمی زیر نقطه‌ی جوش است دم بکشد."},{"label":"پایین کشیدن","text":"حرارت را قطع کنید تا فشار پایین بیاید و قهوه از فیلتر به مخزن پایین برگردد."}],"proTip":"چگالی بخار آب حدود ۱/۲۰۰۰ آب مایع است؛ برای نگه‌داشتن آب در ظرف بالا اختلاف فشاری حدود ۱٫۵ کیلوپاسکال کافی است.","variation":"سیفون موازنه‌ای (بلژیکی) وزنه و خاموش‌کننده‌ی فنردار دارد که پس از پایان دم‌آوری شعله را خاموش می‌کند.","history":"سیفون را یوهان نورنبرگ در ۱۸۲۷ اختراع کرد. «ماشین خلأ نیپیر» در ۱۸۴۰ ارائه شد، «سینتراکس» گرهارد مارکس در ۱۹۲۵ و مدل برقی «سیفونیستا»ی تایگر در ۲۰۲۲.","src":[["Wikipedia — Siphon coffee","https://en.wikipedia.org/wiki/Siphon_coffee"]]},{"id":74,"title":"پرکولاتور (Percolator)","body":"<ul><li><strong>گام ۱ (آب):</strong> آب را در دیگ بریزید و سطح آن را زیر کف سبد نگه دارید.</li><li><strong>گام ۲ (قهوه):</strong> قهوه‌ی نسبتاً درشت را در سبد بریزید.</li><li><strong>گام ۳ (مونتاژ):</strong> سبد را روی لوله‌ی مرکزی قرار دهید و درپوش را ببندید.</li><li><strong>گام ۴ (حرارت):</strong> دیگ را روی اجاق بگذارید تا آب بجوشد و بخار، آب را از لوله بالا ببرد و روی قهوه بپاشد.</li><li><strong>گام ۵ (گوش دادن):</strong> صدای متناوب «پرک» یعنی دم‌آوری ادامه دارد؛ وقتی صدا یکنواخت شد، قهوه تقریباً آماده است.</li><li><strong>گام ۶ (پایان):</strong> دیگ را از حرارت بردارید یا حرارت را کم کنید تا قهوه تلخ نشود.</li></ul>","kind":"item","description":"پرکولاتور قهوه را با چرخه‌ی مداوم عبور مایع جوشان یا نزدیک جوش از میان تفاله دم می‌کند.","difficulty":"","prepTime":"","totalTime":"","origin":"فرانسه / آمریکا","caffeineLevel":0,"equipment":["دیگ با محفظه‌ی گرم‌شونده","لوله‌ی مرکزی","سبد سوراخ‌دار با درپوش","اجاق یا المنت برقی","حلقه‌ی فیلتر کاغذی (اختیاری)"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی نسبتاً درشت‌آسیاب"},{"amount":"—","unit":"","name":"آب"}],"steps":[{"label":"آب","text":"آب را در دیگ بریزید و سطح آن را زیر کف سبد نگه دارید."},{"label":"قهوه","text":"قهوه‌ی نسبتاً درشت را در سبد بریزید."},{"label":"مونتاژ","text":"سبد را روی لوله‌ی مرکزی قرار دهید و درپوش را ببندید."},{"label":"حرارت","text":"دیگ را روی اجاق بگذارید تا آب بجوشد و بخار، آب را از لوله بالا ببرد و روی قهوه بپاشد."},{"label":"گوش دادن","text":"صدای متناوب «پرک» یعنی دم‌آوری ادامه دارد؛ وقتی صدا یکنواخت شد، قهوه تقریباً آماده است."},{"label":"پایان","text":"دیگ را از حرارت بردارید یا حرارت را کم کنید تا قهوه تلخ نشود."}],"proTip":"پرکولاتور مستعد استخراج بیش‌ازحد است؛ اگر روی نقطه‌ی جوش بماند قهوه تلخ و زبر می‌شود و ممکن است قهوه‌ی دم‌شده را دوباره از دانه‌ها عبور دهد.","variation":"حلقه‌های فیلتر کاغذی از ۱۹۷۰ عرضه شدند و تمیز کردن و رسوب ته فنجان را کمتر می‌کنند. پرکولاتور با موکاپات فرق دارد.","history":"پرکولاتور در ۱۸۱۹ توسط حلبی‌ساز پاریسی ژوزف‌هانری‌ماری لورن ابداع شده است. در ۱۸۶۵ جیمز نیسن از فرانکلین ماساچوست حق ثبت آمریکایی گرفت و در ۱۳ اوت ۱۸۸۹ هانسون گودریچ، کشاورزی از ایلینوی، پرکولاتور روی اجاق مدرن آمریکایی را ثبت کرد (ثبت ۴۰۸٬۷۰۷). پرکولاتورهای خودکار از دهه‌ی ۱۹۴۰ یا زودتر در دسترس بودند و محبوبیت آن‌ها در اوایل دهه‌ی ۱۹۷۰ به شدت افت کرد.","src":[["Wikipedia — Percolator","https://en.wikipedia.org/wiki/Percolator"]]}],"hero":"assets/images/immersion.svg"},{"id":"drip","icon":"autodrip","title":"قطره‌ای و اتوماتیک","items":[{"id":78,"title":"قهوه‌ساز قطره‌ای صنعتی (Batch Brew – مانند Fetco یا Curtis)","body":"<ul><li><strong>گام ۱ (حجم هر دم):</strong> هر بار یک قهوه و در دسته‌های حداکثر دو لیتری دم کنید (به توصیه‌ی اسکات رائو).</li><li><strong>گام ۲ (ضخامت بستر):</strong> ضخامت بستر قهوه‌ی خشک را ۳ تا ۵ سانتی‌متر نگه دارید.</li><li><strong>گام ۳ (سرو):</strong> قهوه را تا ۳۰ دقیقه پس از دم سرو کنید.</li></ul>","kind":"item","description":"بچ برو روشی شبیه دریپ برای حجم‌های بالاست، مناسب کافه‌ها و رستوران‌ها.","difficulty":"","prepTime":"","totalTime":"","origin":"","caffeineLevel":0,"equipment":["قهوه‌ساز قطره‌ای صنعتی (Batch Brew)","فیلتر کاغذی بزرگ","آسیاب قهوه"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی تازه‌آسیاب"},{"amount":"—","unit":"","name":"آب"}],"steps":[{"label":"حجم هر دم","text":"هر بار یک قهوه و در دسته‌های حداکثر دو لیتری دم کنید (به توصیه‌ی اسکات رائو)."},{"label":"ضخامت بستر","text":"ضخامت بستر قهوه‌ی خشک را ۳ تا ۵ سانتی‌متر نگه دارید."},{"label":"سرو","text":"قهوه را تا ۳۰ دقیقه پس از دم سرو کنید.","meta":"۳۰ دقیقه"}],"proTip":"طبق اسکات رائو بستر کم‌عمق کانال‌زدن را بیشتر و بستر خیلی عمیق نیاز به آسیاب بسیار درشت می‌کند. ","variation":"","history":"طبق Genuine Origin ظرفیت دستگاه‌های بچ برو از ۱ تا ۱۸ لیتر است و بیشتر دریپ‌های کافه‌ها با آن‌ها و برندهایی مثل Fetco، Curtis و Bunn دم می‌شود.","src":[["Genuine Origin — Batch brew","https://blog.genuineorigin.com/coffee-glossary/batch-brew/"],["Scott Rao — Batch Brew Basics Part 1","https://www.scottrao.com/blog/batch-brew-basics-part-1-the-setup"]]},{"id":79,"title":"قهوه‌ساز قطره‌ای خانگی (Home Drip Coffee Maker)","body":"<ul><li><strong>گام ۱ (فیلتر):</strong> فیلتر را در سبد بگذارید و قهوه را بریزید.</li><li><strong>گام ۲ (آب):</strong> آب سرد را در مخزن بریزید.</li><li><strong>گام ۳ (روشن کردن):</strong> دستگاه را روشن کنید؛ آب در محفظه‌ی گرمایش داغ می‌شود و از لوله‌ی بالارو بالا می‌آید.</li><li><strong>گام ۴ (چکیدن):</strong> آب روی قهوه پاشیده می‌شود، از فیلتر می‌گذرد و داخل کارافه می‌چکد.</li><li><strong>گام ۵ (نگهداری):</strong> کارافه روی صفحه‌ی گرم می‌ماند؛ در کارافه‌ی بلند، قهوه‌ی ته آن غلیظ‌تر از بالاست، پس قبل از ریختن هم بزنید.</li></ul>","kind":"item","description":"قهوه‌ساز قطره‌ای آب را از مخزن سرد به لوله‌ای انعطاف‌پذیر در کف مخزن می‌برد، گرم می‌کند و روی قهوه می‌چکاند.","difficulty":"","prepTime":"","totalTime":"","origin":"آلمان / آمریکا","caffeineLevel":0,"equipment":["قهوه‌ساز قطره‌ای خانگی","فیلتر کاغذی #۴","آسیاب قهوه"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی آسیاب‌شده"},{"amount":"—","unit":"","name":"آب سرد مخزن"}],"steps":[{"label":"فیلتر","text":"فیلتر را در سبد بگذارید و قهوه را بریزید."},{"label":"آب","text":"آب سرد را در مخزن بریزید."},{"label":"روشن کردن","text":"دستگاه را روشن کنید؛ آب در محفظه‌ی گرمایش داغ می‌شود و از لوله‌ی بالارو بالا می‌آید."},{"label":"چکیدن","text":"آب روی قهوه پاشیده می‌شود، از فیلتر می‌گذرد و داخل کارافه می‌چکد."},{"label":"نگهداری","text":"کارافه روی صفحه‌ی گرم می‌ماند؛ در کارافه‌ی بلند، قهوه‌ی ته آن غلیظ‌تر از بالاست، پس قبل از ریختن هم بزنید."}],"proTip":"ترموستات متصل به المنت هنگام لزوم المنت را خاموش می‌کند. فیلترهای دائمی معمولاً از ورق فلزی سوراخ‌دار یا توری پلاستیکی ریز ساخته می‌شوند.","variation":"فیلتر دائمی (فلزی یا توری) روغن بیشتری عبور می‌دهد و پسماند کمتری دارد، اما برای جلوگیری از رسوب به آسیاب درشت‌تری نیاز دارد.","history":"فیلتر کاغذی قهوه را ملیتا بنتز در ۱۹۰۸ در آلمان اختراع کرد. یکی از نخستین قهوه‌سازهای قطره‌ای برقی «ویگوماتِ» آلمانی بود که در ۱۹۵۴ ثبت شد؛ و در اوایل دهه‌ی ۱۹۷۰ با نام «مستر کافی» فروخته می‌شد.","src":[["Wikipedia — Drip coffee","https://en.wikipedia.org/wiki/Drip_coffee"],["Wikipedia — Drip brewing","https://en.wikipedia.org/wiki/Drip_brewing"]]}],"hero":"assets/images/drip.svg"},{"id":"cold","icon":"cold","title":"سرد و یخی","items":[{"id":85,"title":"کلد برو (Cold Brew)","body":"<ul><li><strong>گام ۱ (آسیاب):</strong> قهوه را درشت آسیاب کنید.</li><li><strong>گام ۲ (خیساندن):</strong> قهوه را با آب هم‌دمای اتاق (یا آب سرد) مخلوط کنید و ۱۲ تا ۲۴ ساعت بگذارید بماند.</li><li><strong>گام ۳ (صاف کردن):</strong> دانه‌ها را با فیلتر کاغذی یا صافی ریز بگیرید تا کنسانتره بماند.</li><li><strong>گام ۴ (رقیق کردن):</strong> کنسانتره را با آب یا شیر رقیق کنید و سرد یا روی یخ بنوشید.</li></ul>","kind":"item","description":"کلد برو قهوه‌ی درشت‌آسیاب است که ۱۲ تا ۲۴ ساعت در آب خیسانده می‌شود و معمولاً کنسانتره‌ای است که با آب یا شیر رقیق می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"ژاپن (از طریق هلندی‌ها)","caffeineLevel":0,"equipment":["ظرف دم‌آوری","فیلتر کاغذی","صافی فلزی ریز مثل صافی فرنچ پرس"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی درشت‌آسیاب"},{"amount":"—","unit":"","name":"آب (معمولاً دمای اتاق؛ آب سرد هم ممکن است)"}],"steps":[{"label":"آسیاب","text":"قهوه را درشت آسیاب کنید."},{"label":"خیساندن","text":"قهوه را با آب هم‌دمای اتاق (یا آب سرد) مخلوط کنید و ۱۲ تا ۲۴ ساعت بگذارید بماند.","meta":"۱۲–۲۴ ساعت"},{"label":"صاف کردن","text":"دانه‌ها را با فیلتر کاغذی یا صافی ریز بگیرید تا کنسانتره بماند."},{"label":"رقیق کردن","text":"کنسانتره را با آب یا شیر رقیق کنید و سرد یا روی یخ بنوشید."}],"proTip":"دم‌آوری در دمای پایین‌تر به مدت ۲۴ ساعت، در حجم برابر، کافئین بیشتری از ۶ دقیقه دم‌آوری در ۹۸ درجه‌ی سانتی‌گراد می‌دهد. در روش چکه‌ی آهسته، آب طی ساعت‌ها در دمای اتاق قطره‌قطره از قهوه می‌گذرد.","variation":"کلد برو قطره‌ای (سبک کیوتو یا «قهوه‌ی هلندی»): آب اتاق ساعت‌ها قطره‌قطره از میان قهوه می‌گذرد.","history":"هلندی‌ها کلد برو را به ژاپن آوردند و در آنجا قرن‌هاست روش سنتی دم‌آوری است؛ به آن «سبک کیوتو» و در شرق آسیا «قهوه‌ی هلندی» می‌گویند.","src":[["Wikipedia — Cold brew coffee","https://en.wikipedia.org/wiki/Cold_brew_coffee"]]},{"id":86,"title":"نیترو کلد برو (Nitro Cold Brew)","body":"<ul><li><strong>گام ۱ (کلد برو):</strong> ابتدا کلد برو معمولی را آماده کنید.</li><li><strong>گام ۲ (پر کردن):</strong> آن را در کگ یا بطری هم‌دمای اتاق بریزید.</li><li><strong>گام ۳ (نیتروژن):</strong> گاز نیتروژن را هنگام ریختن در لیوان به قهوه بدمید.</li><li><strong>گام ۴ (سرو):</strong> از شیر مخصوص آبجو بدون یخ و سرد سرو کنید.</li></ul>","kind":"item","description":"نیترو کلد برو گونه‌ای از کلد برو است که با افزودن گاز نیتروژن بافتی نرم می‌یابد.","difficulty":"","prepTime":"","totalTime":"","origin":"آمریکا","caffeineLevel":0,"equipment":["کگ و سیستم شیر شبیه آبجو","سیلندر گاز نیتروژن","لیوان"],"ingredients":[{"amount":"—","unit":"","name":"کلد برو"},{"amount":"—","unit":"","name":"گاز نیتروژن"}],"steps":[{"label":"کلد برو","text":"ابتدا کلد برو معمولی را آماده کنید."},{"label":"پر کردن","text":"آن را در کگ یا بطری هم‌دمای اتاق بریزید."},{"label":"نیتروژن","text":"گاز نیتروژن را هنگام ریختن در لیوان به قهوه بدمید."},{"label":"سرو","text":"از شیر مخصوص آبجو بدون یخ و سرد سرو کنید."}],"proTip":"نیترو کلد برو را بدون یخ سرو کنید، چون یخ کف نرم و کرمی آن را از بین می‌برد.","variation":"نسخه‌ی قوطی‌شده با کپسول نیتروژن از حدود ۲۰۱۵ توسط چند کافه عرضه شد.","history":"نیترو کلد برو در اوایل دهه‌ی ۲۰۱۰ معرفی شد. «کووه کافی» نخستین‌بار در ۱۴ اوت ۲۰۱۲ آن را در «اسلو فود کوییز بول» در آستین تگزاس عرضه کرد و استارباکس تابستان ۲۰۱۶ آن را در ۵۰۰ فروشگاه معرفی کرد.","src":[["Wikipedia — Cold brew coffee","https://en.wikipedia.org/wiki/Cold_brew_coffee"]]},{"id":87,"title":"آیس فیلتر / ژاپنی (Iced Pour-Over / Japanese Iced)","body":"<ul><li><strong>گام ۱ (یخ):</strong> یخ را داخل کارافه یا لیوان بریزید.</li><li><strong>گام ۲ (دم‌آوری):</strong> قهوه را با آب داغ کمتر از معمول روی یخ دم کنید؛ یخ جایگزین بخشی از آب می‌شود.</li><li><strong>گام ۳ (چرخاندن):</strong> کارافه را بچرخانید تا قهوه سرد شود.</li><li><strong>گام ۴ (سرو):</strong> قهوه را روی یخ تازه بریزید و بنوشید.</li></ul>","kind":"item","description":"در روش ژاپنی آب داغ روی یخ می‌چکد و حجم آب داغ برای جبران رقیق‌شدن با یخ آب‌شده کم می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"ژاپن","caffeineLevel":0,"equipment":["دریپر V۶۰ یا کمکس","فیلتر کاغذی","آسیاب قهوه"],"ingredients":[{"amount":"۱۵","unit":"گرم","name":"قهوه (نمونه)"},{"amount":"۱۳۵","unit":"گرم","name":"آب داغ ۹۶ درجه (نمونه)"},{"amount":"۹۰","unit":"گرم","name":"یخ (نمونه)"}],"steps":[{"label":"یخ","text":"یخ را داخل کارافه یا لیوان بریزید."},{"label":"دم‌آوری","text":"قهوه را با آب داغ کمتر از معمول روی یخ دم کنید؛ یخ جایگزین بخشی از آب می‌شود."},{"label":"چرخاندن","text":"کارافه را بچرخانید تا قهوه سرد شود."},{"label":"سرو","text":"قهوه را روی یخ تازه بریزید و بنوشید."}],"proTip":"قهوه‌ی سرد معمولاً با قدرت بیشتر از قهوه‌ی عادی دم می‌شود تا رقیق‌شدن با یخ جبران شود.","variation":"","history":"قهوه‌ی سرد از دوران تایشو (حدود ۱۹۲۰) در قهوه‌خانه‌های ژاپن نوشیده می‌شود. در ۱۹۶۹ UCC اوشیما قهوه‌ی کنسروی عرضه کرد.","src":[["Wikipedia — Iced coffee","https://en.wikipedia.org/wiki/Iced_coffee"],["Brew Coffee Home — Clever Dripper","https://www.brewcoffeehome.com/clever-coffee-dripper/"]]},{"id":88,"title":"فراپه یونانی (Greek Frappe)","body":"<ul><li><strong>گام ۱ (مخلوط):</strong> قهوه‌ی فوری، شکر و کمی آب را در شیکر یا با همزن مخلوط کنید.</li><li><strong>گام ۲ (کف):</strong> تا تشکیل کف غلیظ بزنید.</li><li><strong>گام ۳ (لیوان):</strong> کف را روی یخ در لیوان بریزید.</li><li><strong>گام ۴ (آب):</strong> روی آن آب سرد اضافه کنید.</li><li><strong>گام ۵ (شیر):</strong> در صورت دلخواه شیر تبخیرشده یا شیرین‌شده‌ی غلیظ اضافه کنید و با نی سرو کنید.</li></ul>","kind":"item","description":"فراپه معمولاً از قهوه‌ی فوری خشک‌شده با اسپری، آب، شکر و شیر ساخته می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"یونان (تسالونیکی، ۱۹۵۷)","caffeineLevel":0,"equipment":["شیکر","لیوان بلند"],"ingredients":[{"amount":"۲","unit":"قاشق","name":"قهوه‌ی فوری (به‌طور سنتی نسکافه)"},{"amount":"۰–۴","unit":"قاشق","name":"شکر: ساده ۰، متوسط ۲، شیرین ۴ (به‌ازای ۲ قاشق قهوه)"},{"amount":"—","unit":"","name":"کمی آب، آب سرد و یخ؛ شیر اختیاری (سنتی: شیر تبخیرشده)"}],"steps":[{"label":"مخلوط","text":"قهوه‌ی فوری، شکر و کمی آب را در شیکر یا با همزن مخلوط کنید."},{"label":"کف","text":"تا تشکیل کف غلیظ بزنید."},{"label":"لیوان","text":"کف را روی یخ در لیوان بریزید."},{"label":"آب","text":"روی آن آب سرد اضافه کنید."},{"label":"شیر","text":"در صورت دلخواه شیر تبخیرشده یا شیرین‌شده‌ی غلیظ اضافه کنید و با نی سرو کنید."}],"proTip":"قهوه‌ی فوری اسپری‌خشک روغن کمی دارد و کف غلیظ می‌دهد؛ قهوه‌ی تازه یا فریزدرای کف ماندگار نمی‌سازد. با نی بنوشید چون کف رویی تلخ است.","variation":"سه نوع سفارش: گلیکوس (شیرین)، متریوس (متوسط) و اسکتوس (ساده).","history":"فراپه در ۱۹۵۷ در تسالونیکی ابداع شد؛ طبق روایت، دیمیتریس واکوندیوس، نماینده‌ی نستله، با آزمایش قهوه‌ی فوری را با آب سرد و یخ در شیکر مخلوط کرد. شواهد بعدی نشان می‌دهد پیش از ۱۹۵۷ هم با نام «نسکافه فراپه» تبلیغ می‌شد.","src":[["Wikipedia — Frapp%C3%A9 coffee","https://en.wikipedia.org/wiki/Frapp%C3%A9_coffee"]]},{"id":89,"title":"فراپوچینو (Frappuccino – نسخه خانگی)","body":"<ul><li><strong>گام ۱ (ترکیب):</strong> قهوه‌ی فوری، شیر، شکر، یخ و کمی صمغ زانتان را در مخلوط‌کن بریزید.</li><li><strong>گام ۲ (مخلوط کردن):</strong> تا یکدست شدن و غلظت دلخواه بزنید؛ مقدار یخ بافت را تنظیم می‌کند.</li><li><strong>گام ۳ (سرو):</strong> شربت یا سس و خامه‌ی فرم‌گرفته اضافه کنید.</li></ul>","kind":"item","description":"فراپوچینو با مخلوط قهوه‌ی فوری، یخ، عامل امولسیون‌کننده‌ای مثل صمغ زانتان و افزودنی‌هایی چون شیر، شکر، شربت و خامه ساخته می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"آمریکا","caffeineLevel":0,"equipment":["مخلوط‌کن"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی فوری"},{"amount":"—","unit":"","name":"یخ"},{"amount":"—","unit":"","name":"صمغ زانتان (امولسیون‌کننده)"},{"amount":"—","unit":"","name":"شیر، شکر، شربت طعم‌دار، خامه (اختیاری)"}],"steps":[{"label":"ترکیب","text":"قهوه‌ی فوری، شیر، شکر، یخ و کمی صمغ زانتان را در مخلوط‌کن بریزید."},{"label":"مخلوط کردن","text":"تا یکدست شدن و غلظت دلخواه بزنید؛ مقدار یخ بافت را تنظیم می‌کند."},{"label":"سرو","text":"شربت یا سس و خامه‌ی فرم‌گرفته اضافه کنید."}],"proTip":"صمغ زانتان کمک می‌کند ترکیب یخ و قهوه جدا نشود.","variation":"نسخه‌ی «کرم» پایه‌ی بدون قهوه دارد.","history":"فراپوچینو را در اصل زنجیره‌ی «کافی کانکشن» جورج هاول در ماساچوست شرقی ساخت، ثبت و فروخت؛ نام را اندرو فرانک، مدیر بازاریابی او، گذاشت. استارباکس در ۱۹۹۴ کافی کانکشن را خرید و نوشیدنی را با دستوری متفاوت در ۱۹۹۵ با نام خود عرضه کرد. نسخه‌ی بطری ۲۸۰ میلی‌لیتری در ۱۹۹۶ تولید شد و در ۲۰۱۲ فروش سالانه‌ی فراپوچینو بیش از ۲ میلیارد دلار بود.","src":[["Wikipedia — Frappuccino","https://en.wikipedia.org/wiki/Frappuccino"]]},{"id":90,"title":"شیکراتو (Shakerato – اسپرسوی تکان‌داده‌شده با یخ)","body":"<ul><li><strong>گام ۱ (اسپرسو در شیکر):</strong> اسپرسو را هنوز داغ مستقیم در شیکرِ حاوی یخ و شیرین‌کننده بریزید.</li><li><strong>گام ۲ (تکان‌دادن):</strong> در شیکر را ببندید و حدود ۱۵ تا ۲۰ ثانیه محکم تکان دهید. یخ کامل (نه خردشده) از رقیق‌شدن بیش‌ازحد جلوگیری می‌کند.</li><li><strong>گام ۳ (سرو):</strong> مخلوط را در لیوان سردشده صاف کنید و یخ را بگذارید بماند؛ معمولاً در لیوان مارتینی یا کوکتل سرو می‌شود.</li></ul>","kind":"item","description":"شیکراتو اسپرسوی داغ است که با یخ و کمی شربت یا شکر تکان داده و در لیوان سرد صاف می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"ایتالیا","caffeineLevel":0,"equipment":["شیکر","یخ"],"ingredients":[{"amount":"۲","unit":"شات","name":"اسپرسوی تازه (معمولاً دوبل)"},{"amount":"—","unit":"","name":"قالب یخ کامل"},{"amount":"—","unit":"","name":"کمی شربت ساده یا شکر (اختیاری، برای پایداری کف)"}],"steps":[{"label":"اسپرسو در شیکر","text":"اسپرسو را هنوز داغ مستقیم در شیکرِ حاوی یخ و شیرین‌کننده بریزید."},{"label":"تکان‌دادن","text":"در شیکر را ببندید و حدود ۱۵ تا ۲۰ ثانیه محکم تکان دهید. یخ کامل (نه خردشده) از رقیق‌شدن بیش‌ازحد جلوگیری می‌کند.","meta":"۱۵–۲۰ ثانیه"},{"label":"سرو","text":"مخلوط را در لیوان سردشده صاف کنید و یخ را بگذارید بماند؛ معمولاً در لیوان مارتینی یا کوکتل سرو می‌شود."}],"proTip":"از قالب یخ کامل استفاده کنید تا رقیق نشود، ۱۵ تا ۲۰ ثانیه محکم تکان دهید و اسپرسو را داغ بریزید تا سریع سرد شود. شیرین‌کننده کف را پایدارتر می‌کند.","variation":"با لیکور (آمارتو، سامبوکا و...)، با پودر کاکائو، با خامه یا با کمی شیر کف‌دار سرو می‌شود.","history":"خاستگاه دقیق شیکراتو نامعلوم است و مبدع یا تاریخ مشخصی ثبت نشده؛ پیدایش آن را عموماً به بارتندرهای ایتالیایی در دهه‌ی ۱۹۹۰ نسبت می‌دهند. واژه نخستین‌بار در ۱۹۶۶ در نشریه‌ی «تمپو پرزنته» برای یک کوکتل تکان‌داده‌شده چاپ شد. نام از فعل انگلیسی «shake» با پسوند ایتالیایی -ato می‌آید.","src":[["Wikipedia — Caff%C3%A8 shakerato","https://en.wikipedia.org/wiki/Caff%C3%A8_shakerato"]]},{"id":91,"title":"آیس لاته (Iced Latte)","body":"<ul><li><strong>گام ۱ (ساخت):</strong> اسپرسو را روی شیر سرد و یخ بریزید.</li></ul>","kind":"item","description":"آیس لاته قهوه‌ی یخی بر پایه‌ی اسپرسو و شیر سرد است؛ قهوه‌ی یخی قهوه‌ای است که روی یخ یا شیر سرد سرو می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"","caffeineLevel":0,"equipment":["دستگاه اسپرسو یا قهوه‌ی غلیظ آماده"],"ingredients":[{"amount":"۱","unit":"شات","name":"اسپرسو"},{"amount":"—","unit":"","name":"شیر سرد"},{"amount":"—","unit":"","name":"یخ"}],"steps":[{"label":"ساخت","text":"اسپرسو را روی شیر سرد و یخ بریزید."}],"proTip":"","variation":"","history":" فقط می‌گوید قهوه‌ی یخی ممکن است روی یخ یا شیر سرد سرو شود و اینکه استارباکس برای جلوگیری از رقیق‌شدن، قهوه را با روش دوبرابر غلیظ دم می‌کند.","src":[["Wikipedia — Iced coffee","https://en.wikipedia.org/wiki/Iced_coffee"]]},{"id":92,"title":"آیس ماکیاتو (Iced Macchiato)","body":"<ul><li><strong>گام ۱ (شیر و یخ):</strong> شیر سرد و یخ را در لیوان شفاف بریزید.</li><li><strong>گام ۲ (اسپرسو):</strong> اسپرسو را آرام، ایده‌آل از روی پشت قاشق، روی آن بریزید تا لایه‌ها جدا بمانند.</li></ul>","kind":"item","description":"آیس ماکیاتو بر پایه‌ی ایده‌ی «لاته ماکیاتو» است: اسپرسو آرام روی شیر ریخته می‌شود و لکه‌ای (macchia) روی سطح می‌ماند.","difficulty":"","prepTime":"","totalTime":"","origin":"","caffeineLevel":0,"equipment":["دستگاه اسپرسو یا قهوه‌ی غلیظ آماده","همزن دستی (برای کف شیر)"],"ingredients":[{"amount":"۱","unit":"شات","name":"اسپرسو"},{"amount":"—","unit":"","name":"شیر سرد"},{"amount":"—","unit":"","name":"یخ"}],"steps":[{"label":"شیر و یخ","text":"شیر سرد و یخ را در لیوان شفاف بریزید."},{"label":"اسپرسو","text":"اسپرسو را آرام، ایده‌آل از روی پشت قاشق، روی آن بریزید تا لایه‌ها جدا بمانند."}],"proTip":"برای دیده‌شدن لایه‌ها لیوان شفاف لازم است.","variation":"","history":"«لاته ماکیاتو» یعنی «شیر لکه‌دار» و تعبیری بازی‌گونه از «کافه ماکیاتو» است که نوشیدنی قدیمی‌تری است. آن صفحه نسخه‌ی یخی را ذکر نمی‌کند.","src":[["Wikipedia — Latte macchiato","https://en.wikipedia.org/wiki/Latte_macchiato"],["Wikipedia — Iced coffee","https://en.wikipedia.org/wiki/Iced_coffee"]]},{"id":655,"title":"فردو اسپرسو (Freddo Espresso)","body":"<ul><li><strong>گام ۱ (اسپرسو):</strong> دو شات اسپرسو (۳۰ تا ۵۰ میلی‌لیتر) بکشید.</li><li><strong>گام ۲ (شیکر):</strong> اسپرسو، شکر و یخ را در میکسر مخصوص بزنید تا سرد شود و کف بگیرد.</li><li><strong>گام ۳ (سرو):</strong> روی یخ تازه در لیوان بلند بریزید.</li></ul>","kind":"item","description":"فردو اسپرسو نوشیدنی یونانی است که اسپرسوی دوبل، شکر و یخ را در شیکر می‌زنند تا کف بگیرد و روی یخ سرو می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"یونان","caffeineLevel":0,"equipment":["دستگاه اسپرسو","میکسر فردو (فراپیرا)","لیوان بلند"],"ingredients":[{"amount":"۳۰–۵۰","unit":"میلی‌لیتر","name":"اسپرسوی دوبل"},{"amount":"—","unit":"","name":"شکر (دانه‌ای یا شربت)"},{"amount":"۶۰–۱۰۰","unit":"میلی‌لیتر","name":"یخ"}],"steps":[{"label":"اسپرسو","text":"دو شات اسپرسو (۳۰ تا ۵۰ میلی‌لیتر) بکشید."},{"label":"شیکر","text":"اسپرسو، شکر و یخ را در میکسر مخصوص بزنید تا سرد شود و کف بگیرد."},{"label":"سرو","text":"روی یخ تازه در لیوان بلند بریزید."}],"proTip":"","variation":"","history":"فردو اسپرسو در سال ۱۹۹۱ در آتن ساخته شد و اغلب نسخه‌ی باکیفیت‌تر فراپه توصیف می‌شود.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Wikipedia — Frappé coffee","https://en.wikipedia.org/wiki/Frapp%C3%A9_coffee"]]},{"id":656,"title":"فردو کاپوچینو (Freddo Cappuccino)","body":"<ul><li><strong>گام ۱ (فردو):</strong> ابتدا فردو اسپرسو را مثل دستور آن آماده کنید.</li><li><strong>گام ۲ (کف شیر):</strong> شیر را در میکسر بزنید تا کف سرد آفروگالا بسازد (نسبت اسپرسو به شیر حدود ۱:۲).</li><li><strong>گام ۳ (سرو):</strong> کف را روی فردو بریزید.</li></ul>","kind":"item","description":"فردو کاپوچینو همان فردو اسپرسو است که روی آن کف شیر سرد (آفروگالا) ریخته می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"یونان","caffeineLevel":0,"equipment":["دستگاه اسپرسو","میکسر فردو (فراپیرا)","لیوان بلند"],"ingredients":[{"amount":"—","unit":"","name":"فردو اسپرسو"},{"amount":"—","unit":"","name":"کف شیر سرد"}],"steps":[{"label":"فردو","text":"ابتدا فردو اسپرسو را مثل دستور آن آماده کنید."},{"label":"کف شیر","text":"شیر را در میکسر بزنید تا کف سرد آفروگالا بسازد (نسبت اسپرسو به شیر حدود ۱:۲)."},{"label":"سرو","text":"کف را روی فردو بریزید."}],"proTip":"","variation":"شیر می‌تواند تازه یا شیرین‌شده‌ی غلیظ باشد؛ برخی کافه‌ها از شیر گیاهی برای کف سفت‌تر و شیرین‌تر استفاده می‌کنند.","history":"فردو کاپوچینو در یونان تقریباً به اندازه‌ی فردو اسپرسو محبوب است و بر پایه‌ی آن ساخته شده است.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":657,"title":"آیس‌شات (Ice Shot)","body":"<ul><li><strong>گام ۱ (لیوان):</strong> لیوان لاته را تا لب از یخ پر کنید.</li><li><strong>گام ۲ (اسپرسو):</strong> یک شات اسپرسوی تازه را روی یخ بریزید.</li><li><strong>گام ۳ (بافت):</strong> یخ کمی آب می‌شود و دوباره یخ می‌زند و بافت گرانیتا می‌سازد. شیر، شکر و طعم‌دهنده لازم نیست.</li><li><strong>گام ۴ (بستنی):</strong> اگر خواستید، یک قاشق بستنی روی آن بگذارید.</li></ul>","kind":"item","description":"یک اسپرسوی تکی در لیوان پر از یخ، به‌صورت اختیاری با بستنی.","difficulty":"","prepTime":"","totalTime":"","origin":"استرالیا","caffeineLevel":0,"equipment":["لیوان لاته"],"ingredients":[{"amount":"۱","unit":"شات","name":"اسپرسو"},{"amount":"—","unit":"","name":"یخ"},{"amount":"—","unit":"","name":"بستنی (اختیاری)"}],"steps":[{"label":"لیوان","text":"لیوان لاته را تا لب از یخ پر کنید."},{"label":"اسپرسو","text":"یک شات اسپرسوی تازه را روی یخ بریزید.","meta":"۱ شات"},{"label":"بافت","text":"یخ کمی آب می‌شود و دوباره یخ می‌زند و بافت گرانیتا می‌سازد. شیر، شکر و طعم‌دهنده لازم نیست."},{"label":"بستنی","text":"اگر خواستید، یک قاشق بستنی روی آن بگذارید."}],"proTip":"اسپرسوی تازه روی یخ بریزید؛ قهوه‌ی داغ بخشی از یخ را آب می‌کند و مخلوط دوباره منجمد می‌شود و بافتی شبیه گرانیتا می‌گیرد.","variation":"یک قاشق بستنی روی آن، نسخه‌ی پرطرفدار این نوشیدنی است.","history":"","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]}],"hero":"assets/images/cold.svg"},{"id":"traditional","icon":"traditional","title":"سنتی، منطقه‌ای و تاریخی","items":[{"id":96,"title":"قهوه ترک (Turkish Coffee)","body":"<ul><li><strong>گام ۱ (آسیاب):</strong> قهوه باید بسیار ریز باشد؛ اندازه‌ی ذره ۷۵ تا ۱۲۵ میکرون است و ریزی آن بر کف و حس دهان اثر دارد. آسیاب‌های برقی خانگی معمولاً مناسب نیستند.</li><li><strong>گام ۲ (جذوه):</strong> چند قاشق چای‌خوری قهوه (دست‌کم ۷ گرم برای هر نفر) را در جذوه، ظرف مسی ضخیم که ته‌اش از دهانه پهن‌تر است، با آب گرم کنید.</li><li><strong>گام ۳ (کف‌کردن):</strong> قهوه تا آستانه‌ی جوش گرم می‌شود؛ به‌محض کف‌کردن از حرارت برداشته می‌شود و معمولاً دو بار دیگر به‌طور کوتاه به جوش نزدیک می‌شود تا کف بیشتر شود.</li><li><strong>گام ۴ (سرو):</strong> در فنجان‌های کوچک حدود ۹۰ میلی‌لیتری سرو کنید؛ کنار آن یک لیوان آب می‌گذارند که ابتدا برای شست‌وشوی دهان نوشیده می‌شود.</li></ul>","kind":"item","description":"قهوه‌ی ترک در جذوه‌ی (cezve) مسی از قهوه‌ی بسیار ریز تا آستانه‌ی جوش گرم می‌شود و با کف ضخیم سرو می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"ترکیه","caffeineLevel":0,"equipment":["جذوه","آسیاب ترک","اجاق"],"ingredients":[{"amount":"۷+","unit":"گرم","name":"قهوه‌ی بسیار ریز به‌ازای هر نفر (دست‌کم)"},{"amount":"—","unit":"","name":"شکر: ساده، کم/متوسط یا شیرین"}],"steps":[{"label":"آسیاب","text":"قهوه باید بسیار ریز باشد؛ اندازه‌ی ذره ۷۵ تا ۱۲۵ میکرون است و ریزی آن بر کف و حس دهان اثر دارد. آسیاب‌های برقی خانگی معمولاً مناسب نیستند.","meta":"۷۵–۱۲۵ میکرون"},{"label":"جذوه","text":"چند قاشق چای‌خوری قهوه (دست‌کم ۷ گرم برای هر نفر) را در جذوه، ظرف مسی ضخیم که ته‌اش از دهانه پهن‌تر است، با آب گرم کنید."},{"label":"کف‌کردن","text":"قهوه تا آستانه‌ی جوش گرم می‌شود؛ به‌محض کف‌کردن از حرارت برداشته می‌شود و معمولاً دو بار دیگر به‌طور کوتاه به جوش نزدیک می‌شود تا کف بیشتر شود."},{"label":"سرو","text":"در فنجان‌های کوچک حدود ۹۰ میلی‌لیتری سرو کنید؛ کنار آن یک لیوان آب می‌گذارند که ابتدا برای شست‌وشوی دهان نوشیده می‌شود.","meta":"≈۹۰ میلی‌لیتر"}],"proTip":"قهوه‌ی ترک خوب لایه‌ی کف بسیار ضخیم دارد. سفارش قند: ساده (sade)، کم‌شکر (az şekerli)، متوسط (orta) یا شیرین (çok şekerli).","variation":"روش شن: جذوه‌ی پر از قهوه را در تابه‌ی پر از شن داغ می‌گذارند و این فرایند معمولاً سه تا چهار بار تکرار می‌شود.","history":"قهوه تا ۱۵۳۹ در استانبول مصرف می‌شد و نخستین قهوه‌خانه‌ی استانبول در ۱۵۵۴ (به گفته‌ی بعضی ۱۵۵۱) گشوده شد. یونسکو فرهنگ و سنت قهوه‌ی ترک را در فهرست نمایندگی میراث ناملموس ثبت کرده است.","src":[["Wikipedia — Turkish coffee","https://en.wikipedia.org/wiki/Turkish_coffee"]]},{"id":97,"title":"قهوه قجری (Persian Qajar Coffee)","body":"<ul><li><strong>گام ۱ (توضیح):</strong> این مورد دستور نوشیدنی نیست و فقط ثبت تاریخی است.</li></ul>","kind":"item","description":"«قهوه قجری» دستور نوشیدنی نیست؛ قهوه‌ی مسمومی بود که در دربار قاجار برای کشتن دشمنان حکومت به کار می‌رفت.","difficulty":"","prepTime":"","totalTime":"","origin":"ایران، دوره‌ی قاجار","caffeineLevel":0,"equipment":["جذوه","آسیاب ترک","اجاق"],"ingredients":[{"amount":"—","unit":"","name":"دستور ندارد"}],"steps":[{"label":"توضیح","text":"این مورد دستور نوشیدنی نیست و فقط ثبت تاریخی است."}],"proTip":"","variation":"","history":"رواج این روش به‌ویژه پس از دوران ناصرالدین‌شاه بود و مسعود میرزا ظل‌السلطان به استفاده از قهوه‌ی مسموم برای حذف مخالفان شهره بود. سه سم نام برده می‌شود: سیانید، اسید آرسنیک و استریکنین.","src":[["Wikipedia — Qajar coffee","https://en.wikipedia.org/wiki/Qajar_coffee"]]},{"id":98,"title":"قهوه عربی (Arabic Gahwa)","body":"<ul><li><strong>گام ۱ (برشته‌کاری):</strong> دانه‌ها از روشن تا تیره برشته می‌شوند (۱۶۵ تا ۲۱۰ درجه‌ی سانتی‌گراد)؛ در عربستان برشته‌ی روشن با رنگ طلایی رایج است. سنتاً دانه در «محماس» برشته و در «محباج» کوبیده می‌شود.</li><li><strong>گام ۲ (دم‌آوری):</strong> قهوه با هل در ظرفی به نام «دَلّه» جوشانده می‌شود اما صاف نمی‌شود؛ نتیجه نوشیدنی قوی و غلیظ است.</li><li><strong>گام ۳ (سرو):</strong> سرو‌کننده دله را با کف دست راست و بالای آن می‌گیرد و مهمان فنجان را با دست راست می‌گیرد و پس می‌دهد. فنجان‌ها معمولاً فقط تا نیمه پر می‌شوند و پذیرفتن سه فنجان مؤدبانه است.</li></ul>","kind":"item","description":"قهوه‌ی عربی از دانه‌ی عربیکای کم‌ تا پررنگ‌برشته با هل ساخته می‌شود و جوشانده اما صاف‌نشده سرو می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"یمن / شبه‌جزیره‌ی عربستان","caffeineLevel":0,"equipment":["دلّه","فنجان بدون دسته"],"ingredients":[{"amount":"—","unit":"","name":"عربیکای برشته (۱۶۵ تا ۲۱۰ درجه‌ی سانتی‌گراد)"},{"amount":"—","unit":"","name":"هل (در عربستان مهم‌ترین ادویه)"},{"amount":"—","unit":"","name":"زعفران (در سبک خلیجی، اختیاری)"}],"steps":[{"label":"برشته‌کاری","text":"دانه‌ها از روشن تا تیره برشته می‌شوند (۱۶۵ تا ۲۱۰ درجه‌ی سانتی‌گراد)؛ در عربستان برشته‌ی روشن با رنگ طلایی رایج است. سنتاً دانه در «محماس» برشته و در «محباج» کوبیده می‌شود.","meta":"۱۶۵–۲۱۰ درجه‌ی سانتی‌گراد"},{"label":"دم‌آوری","text":"قهوه با هل در ظرفی به نام «دَلّه» جوشانده می‌شود اما صاف نمی‌شود؛ نتیجه نوشیدنی قوی و غلیظ است."},{"label":"سرو","text":"سرو‌کننده دله را با کف دست راست و بالای آن می‌گیرد و مهمان فنجان را با دست راست می‌گیرد و پس می‌دهد. فنجان‌ها معمولاً فقط تا نیمه پر می‌شوند و پذیرفتن سه فنجان مؤدبانه است."}],"proTip":"قهوه‌ی عربی معمولاً بدون شکر سرو می‌شود و همراهش خرما، میوه‌ی خشک یا شیرینی می‌گذارند تا تلخی‌اش متعادل شود. فنجان را فقط تا نیمه پر کنید و برای پایان دادن به نوشیدن، فنجان را به‌آرامی تکان دهید.","variation":"سبک خلیجی معمولاً به‌خاطر مصرف زیاد زعفران و هل رنگ زرد روشن دارد؛ قهوه‌ی عربی را ساده یا با شکر هم می‌دهند.","history":"قهوه‌ی عربی در یمن بزرگ و از بندر مخا آغاز شد؛ نخستین شواهد معتبر نوشیدن قهوه به میانه‌ی قرن پانزدهم برمی‌گردد. در ۱۵۱۱ امامان محافظه‌کار در دادگاهی در مکه آن را به‌خاطر اثر محرکش ممنوع کردند و در ۱۵۲۴ فرمان سلطان سلیمان اول این ممنوعیت را لغو کرد؛ در قاهره ممنوعیت مشابهی در ۱۵۳۲ برقرار شد. واژه‌ی «coffee» در ۱۵۸۲ وارد انگلیسی شد. یونسکو قهوه‌ی عربی را میراث ناملموس کشورهای عربی تأیید کرده است.","src":[["Wikipedia — Arabic coffee","https://en.wikipedia.org/wiki/Arabic_coffee"]]},{"id":99,"title":"قهوه اتیوپی (Ethiopian Buna / Jebena)","body":"<ul><li><strong>گام ۱ (برشته‌کاری):</strong> دانه‌های سبز را روی شعله‌ی باز در تابه برشته کنید.</li><li><strong>گام ۲ (آسیاب):</strong> دانه‌ها را با «مکچا»، هاون و دسته‌ی چوبی سنتی، بکوبید و چند بار از صافی بگذرانید.</li><li><strong>گام ۳ (جبنا):</strong> جبنا چند دقیقه روی شعله‌ی باز می‌ماند و بعد قهوه افزوده می‌شود.</li><li><strong>گام ۴ (سه دور):</strong> تفاله سه بار دم می‌شود: «ابول»، «تونا» و «برکه» (به معنای برکت‌یافتن).</li></ul>","kind":"item","description":"در مراسم قهوه، دانه‌ی سبز روی شعله در تابه برشته می‌شود، با هاون چوبی (مکچا) کوبیده می‌شود و در جبنا دم می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"اتیوپی / اریتره","caffeineLevel":0,"equipment":["جبنا","هاون/آسیاب"],"ingredients":[{"amount":"—","unit":"","name":"دانه‌ی سبز قهوه"},{"amount":"—","unit":"","name":"آب"}],"steps":[{"label":"برشته‌کاری","text":"دانه‌های سبز را روی شعله‌ی باز در تابه برشته کنید."},{"label":"آسیاب","text":"دانه‌ها را با «مکچا»، هاون و دسته‌ی چوبی سنتی، بکوبید و چند بار از صافی بگذرانید."},{"label":"جبنا","text":"جبنا چند دقیقه روی شعله‌ی باز می‌ماند و بعد قهوه افزوده می‌شود."},{"label":"سه دور","text":"تفاله سه بار دم می‌شود: «ابول»، «تونا» و «برکه» (به معنای برکت‌یافتن)."}],"proTip":"ممکن است در مراسم انواع بخورهای سنتی هم سوزانده شود. فنجان‌ها کوچک و بدون دسته‌اند و میزبان از ارتفاع حدود یک فوت می‌ریزد.","variation":"در مناطق روستایی گاهی نمک یا کره‌ی سنتی (نیتر کیبه) به قهوه می‌افزایند؛ شکر هم رایج است. معمولاً ذرت بوداده، بادام‌زمینی یا نان هیمباشا همراه آن سرو می‌شود.","history":"","src":[["Wikipedia — Coffee ceremony","https://en.wikipedia.org/wiki/Coffee_ceremony"]]},{"id":100,"title":"قهوه تخم‌مرغ ویتنامی (Vietnamese Egg Coffee)","body":"<ul><li><strong>گام ۱ (قهوه):</strong> قهوه‌ی روبوستا را در «فین» (فیلتر ویتنامی) دم کنید.</li><li><strong>گام ۲ (کف زرده):</strong> زرده‌ی تخم‌مرغ را با شیر تغلیظ‌شده و شکر بزنید و به‌آرامی در حمام آب گرم، گرم کنید؛ جوشاندن مستقیم باعث دلمه‌شدن تخم‌مرغ می‌شود.</li><li><strong>گام ۳ (ترکیب):</strong> قهوه را روی کف زرده بریزید؛ چربی زرده با قهوه می‌آمیزد و تلخی آن را نرم می‌کند و کفی غلیظ و خوشبو می‌سازد.</li><li><strong>گام ۴ (سرو):</strong> در فنجان کوچک و همراه یک قاشق چای‌خوری سرو کنید تا پیش از نوشیدن قهوه‌ی ته فنجان، کف خورده شود.</li></ul>","kind":"item","description":"قهوه‌ی تخم‌مرغ ویتنامی با فیلتر «فین»، زرده‌ی تخم‌مرغ، شکر و شیر تغلیظ‌شده ساخته می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"ویتنام","caffeineLevel":0,"equipment":["همزن برقی","فیلتر قهوه‌ی ویتنامی (فین) یا دستگاه اسپرسو"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی روبوستا"},{"amount":"—","unit":"","name":"زرده‌ی تخم‌مرغ"},{"amount":"—","unit":"","name":"شکر"},{"amount":"—","unit":"","name":"شیر تغلیظ‌شده"}],"steps":[{"label":"قهوه","text":"قهوه‌ی روبوستا را در «فین» (فیلتر ویتنامی) دم کنید."},{"label":"کف زرده","text":"زرده‌ی تخم‌مرغ را با شیر تغلیظ‌شده و شکر بزنید و به‌آرامی در حمام آب گرم، گرم کنید؛ جوشاندن مستقیم باعث دلمه‌شدن تخم‌مرغ می‌شود."},{"label":"ترکیب","text":"قهوه را روی کف زرده بریزید؛ چربی زرده با قهوه می‌آمیزد و تلخی آن را نرم می‌کند و کفی غلیظ و خوشبو می‌سازد."},{"label":"سرو","text":"در فنجان کوچک و همراه یک قاشق چای‌خوری سرو کنید تا پیش از نوشیدن قهوه‌ی ته فنجان، کف خورده شود."}],"proTip":"فنجان را در کاسه‌ای آب گرم یا روی شمع کوچک بگذارید تا گرم بماند. قهوه‌ی ته فنجان پس از ریختن روی کف غنی‌تر مزه می‌دهد.","variation":"می‌توان آن را با کاکائو، لوبیای سفید و ماچا ترکیب کرد و گرم یا یخی سرو کرد.","history":"این نوشیدنی در کافه‌های سراسر ویتنام سرو می‌شود و از هانوی آغاز شده است. پسر بنیان‌گذار کافه، نگوین گیانگ، می‌گوید پدرش دستور را در اواخر دهه‌ی ۱۹۴۰، هنگام کمبود شیر در ویتنام، ابداع کرد.","src":[["Wikipedia — Egg coffee","https://en.wikipedia.org/wiki/Egg_coffee"]]},{"id":101,"title":"بومبون اسپانیایی (Spanish Bombón)","body":"<ul><li><strong>گام ۱ (شیر):</strong> شیر تغلیظ‌شده‌ی شیرین را در لیوان شیشه‌ای بریزید.</li><li><strong>گام ۲ (اسپرسو):</strong> اسپرسو را آرام اضافه کنید تا دو لایه‌ی مجزا بسازد.</li><li><strong>گام ۳ (سرو):</strong> معمولاً پیش از نوشیدن هم زده می‌شود.</li></ul>","kind":"item","description":"بومبون اسپرسو با شیر تغلیظ‌شده‌ی شیرین به نسبت ۱:۱ است که در لیوان شیشه‌ای دو لایه می‌سازد.","difficulty":"","prepTime":"","totalTime":"","origin":"والنسیا، اسپانیا","caffeineLevel":0,"equipment":["لیوان شیشه‌ای کوچک"],"ingredients":[{"amount":"۱","unit":"شات","name":"اسپرسو"},{"amount":"۱","unit":"هم‌وزن/هم‌حجم اسپرسو","name":"شیر تغلیظ‌شده‌ی شیرین"}],"steps":[{"label":"شیر","text":"شیر تغلیظ‌شده‌ی شیرین را در لیوان شیشه‌ای بریزید."},{"label":"اسپرسو","text":"اسپرسو را آرام اضافه کنید تا دو لایه‌ی مجزا بسازد."},{"label":"سرو","text":"معمولاً پیش از نوشیدن هم زده می‌شود."}],"proTip":"شیر تغلیظ‌شده را آرام اضافه کنید تا زیر قهوه فرو برود و دو نوار رنگی بسازد؛ پیش از نوشیدن معمولاً لایه‌ها را هم می‌زنند.","variation":"جزایر قناری: «کافه پروپیو / لارگو کوندنسادا» با کافه لارگو ساخته می‌شود. در آسیا نسخه‌هایی مثل کوپی سوسو پانس و گافه رورن با قهوه‌ی دم‌شده و نسبت‌های متفاوت وجود دارد.","history":"آن را اسپانیایی و از والنسیا می‌دانند.","src":[["Wikipedia — Milk coffee","https://en.wikipedia.org/wiki/Milk_coffee"]]},{"id":102,"title":"کافه‌اوست فنلاندی (Finnish Kaffeost)","body":"<ul><li><strong>گام ۱ (پنیر):</strong> پنیر نان (لیپایوستو) قرصی به ضخامت ۲ تا ۳ سانتی‌متر است که پخته، کبابی یا فلمبه شده و نشان قهوه‌ای یا سوخته دارد.</li><li><strong>گام ۲ (فنجان):</strong> چند تکه از پنیر را در فنجان بگذارید.</li><li><strong>گام ۳ (قهوه):</strong> قهوه‌ی داغ را روی پنیر بریزید و سرو کنید.</li></ul>","kind":"item","description":"در کافه‌اوست چند تکه از پنیر نان (لیپایوستو) در فنجان گذاشته و قهوه‌ی داغ روی آن ریخته می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"فنلاند","caffeineLevel":0,"equipment":["فنجان قهوه معمولی"],"ingredients":[{"amount":"—","unit":"","name":"پنیر نان (leipäjuusto / kaffeost)"},{"amount":"—","unit":"","name":"قهوه‌ی داغ"}],"steps":[{"label":"پنیر","text":"پنیر نان (لیپایوستو) قرصی به ضخامت ۲ تا ۳ سانتی‌متر است که پخته، کبابی یا فلمبه شده و نشان قهوه‌ای یا سوخته دارد."},{"label":"فنجان","text":"چند تکه از پنیر را در فنجان بگذارید."},{"label":"قهوه","text":"قهوه‌ی داغ را روی پنیر بریزید و سرو کنید."}],"proTip":"پنیر از شیر بسته‌شده به‌شکل قرصی به ضخامت ۲ تا ۳ سانتی‌متر ساخته می‌شود و سپس پخته، کبابی یا فلمبه می‌شود تا نشان قهوه‌ای یا سوخته بگیرد.","variation":"پنیر نان را با مربای یا توت ابرتوت (cloudberry) هم می‌خورند.","history":"پنیر نان را قدیم خشک می‌کردند و تا چند سال نگه می‌داشتند؛ پنیر سفت سنگی را روی آتش گرم می‌کردند تا نرم شود و بوی خوشی بدهد. نام سوئدی «kaffeost» یعنی «پنیر قهوه». این پنیر ابتدا از اوستروبوتنیای جنوبی، شمال فنلاند و کایانو آمده است.","src":[["Wikipedia — Kaffeost","https://en.wikipedia.org/wiki/Kaffeost"]]},{"id":103,"title":"قهوه ایرلندی (Irish Coffee)","body":"<ul><li><strong>گام ۱ (گرم‌کردن لیوان):</strong> لیوان یا ماگ مخصوص قهوه‌ی ایرلندی را از پیش گرم کنید.</li><li><strong>گام ۲ (قهوه):</strong> ۱۲۰ میلی‌لیتر قهوه‌ی داغ را در لیوان بریزید.</li><li><strong>گام ۳ (ویسکی و شکر):</strong> ۵۰ میلی‌لیتر ویسکی ایرلندی و یک قاشق چای‌خوری شکر را بیفزایید و هم بزنید تا شکر کاملاً حل شود.</li><li><strong>گام ۴ (خامه):</strong> ۵۰ میلی‌لیتر خامه‌ی سرد را آهسته روی پشت قاشقی که درست بالای سطح قهوه گرفته‌اید بریزید و قاشق را کم‌کم بالا ببرید تا خامه روی قهوه شناور بماند.</li><li><strong>گام ۵ (سرو):</strong> داغ سرو کنید و قهوه را از میان لایه‌ی خامه بنوشید.</li></ul>","kind":"item","description":"قهوه‌ی ایرلندی از ویسکی ایرلندی، قهوه‌ی داغ، شکر و خامه‌ی سرد ساخته می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"ایرلند","caffeineLevel":0,"equipment":["لیوان مقاوم به حرارت"],"ingredients":[{"amount":"۵۰","unit":"میلی‌لیتر","name":"ویسکی ایرلندی"},{"amount":"۱۲۰","unit":"میلی‌لیتر","name":"قهوه‌ی داغ"},{"amount":"۵۰","unit":"میلی‌لیتر","name":"خامه‌ی تازه‌ی سرد"},{"amount":"۱","unit":"قاشق چای‌خوری","name":"شکر"}],"steps":[{"label":"گرم‌کردن لیوان","text":"لیوان یا ماگ مخصوص قهوه‌ی ایرلندی را از پیش گرم کنید."},{"label":"قهوه","text":"۱۲۰ میلی‌لیتر قهوه‌ی داغ را در لیوان بریزید.","meta":"۱۲۰ میلی‌لیتر"},{"label":"ویسکی و شکر","text":"۵۰ میلی‌لیتر ویسکی ایرلندی و یک قاشق چای‌خوری شکر را بیفزایید و هم بزنید تا شکر کاملاً حل شود.","meta":"۵۰ میلی‌لیتر"},{"label":"خامه","text":"۵۰ میلی‌لیتر خامه‌ی سرد را آهسته روی پشت قاشقی که درست بالای سطح قهوه گرفته‌اید بریزید و قاشق را کم‌کم بالا ببرید تا خامه روی قهوه شناور بماند."},{"label":"سرو","text":"داغ سرو کنید و قهوه را از میان لایه‌ی خامه بنوشید."}],"proTip":"خامه‌ی سرد و غلیظ بردارید و آهسته بریزید تا شناور بماند و با قهوه یکی نشود. شکر برای شناور ماندن خامه‌ی مایع ضروری است.","variation":"در اسپانیا آن را لایه‌لایه سرو می‌کنند: ویسکی در ته، سپس قهوه و خامه در بالا. در «قهوه‌ی کِرِم ایرلندی» (بیلیز) لیکور کرم ایرلندی جای ویسکی، خامه و شکر را می‌گیرد. قهوه‌های لیکوردار همنام با اسپرتی دیگر: رام (جامائیکایی)، ویسکی اسکاچ (هایلند)، ودکا (روسی) و تکیلا (مکزیکی).","history":"جو شریدان، سرآشپز رستوران و قهوه‌فروشی پایانه‌ی هواپیماهای آبی فوینز، در ۱۹۴۲ یا ۱۹۴۳ به قهوه‌ی برخی مسافران پیاده‌شده ویسکی افزود. استنتون دلاپلین، نویسنده‌ی سفر «سن‌فرانسیسکو کرونیکل»، می‌گوید قهوه‌ی ایرلندی را در فرودگاه شانون نوشید و با «کافه بوئنا ویستا» در سن‌فرانسیسکو همکاری کرد تا از ۱۰ نوامبر ۱۹۵۲ آن را سرو کنند (روایت خود دلاپلین).","src":[["Wikipedia — Irish coffee","https://en.wikipedia.org/wiki/Irish_coffee"]]},{"id":104,"title":"کافه آوله (Café au Lait – فرانسوی)","body":"<ul><li><strong>گام ۱ (قهوه):</strong> قهوه‌ی قوی را با دم‌آور صافی یا فرنچ‌پرس دم کنید. (در فرانسه قهوه را با شیر داغ می‌آمیزند؛ نوع آمریکایی آن قهوه‌ی دریپ یا فرنچ‌پرس است و نه اسپرسو.)</li><li><strong>گام ۲ (شیر):</strong> شیر را داغ کنید: با بخار، یا در سبک نیواورلینز تا کمی زیر نقطه‌ی جوش.</li><li><strong>گام ۳ (ترکیب):</strong> شیر داغ را به قهوه اضافه کنید؛ در استارباکس (کافه میستو) نسبت قهوه‌ی فرنچ‌پرس به شیر کف‌دار یک به یک است.</li><li><strong>گام ۴ (سرو):</strong> در فرانسه معمولاً در کاسه‌ی بزرگ بدون دسته و هنگام صبحانه سرو می‌شود؛ در کافه‌های آمریکایی در فنجان.</li></ul>","kind":"item","description":"کافه آوله قهوه‌ای است که شیر داغ به آن افزوده می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"فرانسه","caffeineLevel":0,"equipment":["فرنچ پرس یا کمکس"],"ingredients":[{"amount":"—","unit":"","name":"قهوه"},{"amount":"—","unit":"","name":"شیر داغ"}],"steps":[{"label":"قهوه","text":"قهوه‌ی قوی را با دم‌آور صافی یا فرنچ‌پرس دم کنید. (در فرانسه قهوه را با شیر داغ می‌آمیزند؛ نوع آمریکایی آن قهوه‌ی دریپ یا فرنچ‌پرس است و نه اسپرسو.)"},{"label":"شیر","text":"شیر را داغ کنید: با بخار، یا در سبک نیواورلینز تا کمی زیر نقطه‌ی جوش."},{"label":"ترکیب","text":"شیر داغ را به قهوه اضافه کنید؛ در استارباکس (کافه میستو) نسبت قهوه‌ی فرنچ‌پرس به شیر کف‌دار یک به یک است.","meta":"۱ به ۱"},{"label":"سرو","text":"در فرانسه معمولاً در کاسه‌ی بزرگ بدون دسته و هنگام صبحانه سرو می‌شود؛ در کافه‌های آمریکایی در فنجان."}],"proTip":"در نیواورلینز کافه آوله را با بیمیه (بینیه)ی پودرشکری می‌خورند؛ شکر تلخی کاسنی را متعادل می‌کند.","variation":"در استارباکس با نسبت ۱:۱ قهوه‌ی فرنچ‌پرس و شیر کف‌دار سرو می‌شود. برخلاف کافه لاته که پایه‌اش اسپرسوست.","history":"ذوق قهوه با کاسنی را فرانسوی‌ها در جنگ داخلی خود شکل دادند و در جنگ داخلی آمریکا در لوئیزیانا رایج شد.","src":[["Wikipedia — Caf%C3%A9 au lait","https://en.wikipedia.org/wiki/Caf%C3%A9_au_lait"]]},{"id":105,"title":"وینر ملانژ (Wiener Melange – اتریش)","body":"<ul><li><strong>گام ۱ (قهوه):</strong> نیم فنجان قهوه‌ی دم‌شده‌ی ملایم بگیرید.</li><li><strong>گام ۲ (شیر):</strong> نیم فنجان شیر بخارداده‌شده آماده کنید.</li><li><strong>گام ۳ (ترکیب):</strong> قهوه و شیر را با هم مخلوط کنید و روی آن کف شیر بگذارید (روش کافه اشپرل وین).</li></ul>","kind":"item","description":"ملانژ وینی نیم فنجان قهوه‌ی دم‌شده و نیم فنجان شیر بخارداده‌شده است که روی آن کف شیر می‌گذارند.","difficulty":"","prepTime":"","totalTime":"","origin":"اتریش (وین)","caffeineLevel":0,"equipment":["دستگاه اسپرسو","آسیاب قهوه","فرندر بخار شیر"],"ingredients":[{"amount":"۱/۲","unit":"فنجان","name":"قهوه‌ی دم‌شده"},{"amount":"۱/۲","unit":"فنجان","name":"شیر بخارداده‌شده"}],"steps":[{"label":"قهوه","text":"نیم فنجان قهوه‌ی دم‌شده‌ی ملایم بگیرید."},{"label":"شیر","text":"نیم فنجان شیر بخارداده‌شده آماده کنید."},{"label":"ترکیب","text":"قهوه و شیر را با هم مخلوط کنید و روی آن کف شیر بگذارید (روش کافه اشپرل وین).","meta":"۱ به ۱"}],"proTip":"ملانژ شبیه کاپوچینوست اما با قهوه‌ی ملایم‌تر ساخته می‌شود؛ در وین سفارش ملانژ ممکن است اسپرسو کن پانا بیاورد.","variation":"نسکافه، موونپیک و لوفت‌هانزا کترینگ ملانژ را به‌صورت قهوه آمیخته با کاکائو سرو می‌کنند. سفارش ملانژ در وین هم ممکن است اسپرسو کن پانا بیاورد.","history":"ملانژ شبیه کاپوچینوست؛ با این تفاوت که با قهوه‌ی ملایم‌تر ساخته می‌شود. اشاره به راهبان فرانسیسکن مشابه نام کاپوچینو است که از رنگ قهوه‌ای ردای راهبان کاپوچین می‌آید.","src":[["Wikipedia — Wiener Melange","https://en.wikipedia.org/wiki/Wiener_Melange"]]},{"id":106,"title":"کورتادیتوی کوبایی (Cuban Cortadito)","body":"<ul><li><strong>گام ۱ (اسپرسو):</strong> یک شات استاندارد ۳۰ میلی‌لیتری اسپرسو بگیرید.</li><li><strong>گام ۲ (شیر تغلیظ‌شده):</strong> شیر تغلیظ‌شده‌ی شیرین را گرم کنید و به‌جای شیر تازه به اسپرسو بیفزایید؛ در کوبا شیر تازه کم‌یاب بود و شیر تغلیظ‌شده ماندگار.</li><li><strong>گام ۳ (سرو):</strong> در لیوان کوچک، معمولاً با پایه‌ی حلقه‌ی فلزی و دسته‌ی سیمی، سرو کنید.</li></ul>","kind":"item","description":"کورتادیتو در کوبا نوشیدنی کوچکی شبیه «کافه سولو کورتو» است.","difficulty":"","prepTime":"","totalTime":"","origin":"کوبا","caffeineLevel":0,"equipment":["دستگاه اسپرسو","فرندر بخار شیر"],"ingredients":[{"amount":"۳۰","unit":"میلی‌لیتر","name":"یک شات استاندارد اسپرسو"},{"amount":"—","unit":"","name":"شیر تغلیظ‌شده‌ی شیرین گرم‌شده"}],"steps":[{"label":"اسپرسو","text":"یک شات استاندارد ۳۰ میلی‌لیتری اسپرسو بگیرید.","meta":"۳۰ میلی‌لیتر"},{"label":"شیر تغلیظ‌شده","text":"شیر تغلیظ‌شده‌ی شیرین را گرم کنید و به‌جای شیر تازه به اسپرسو بیفزایید؛ در کوبا شیر تازه کم‌یاب بود و شیر تغلیظ‌شده ماندگار."},{"label":"سرو","text":"در لیوان کوچک، معمولاً با پایه‌ی حلقه‌ی فلزی و دسته‌ی سیمی، سرو کنید."}],"proTip":"کورتادیتوی کوبایی برخلاف کافه کوبایی، فقط با شیر تغلیظ‌شده شیرین می‌شود و شکر جداگانه ندارد.","variation":"نام‌های کوبایی دیگر: «کورتادو کوندنسادا»، «کافه کون لچه کوندنسادا» یا «بومبون»؛ «لچه ای لچه» گونه‌ی مشابهی است.","history":"کورتادیتو در دهه‌ی ۱۹۶۰ توسط کوبایی‌های آمریکا به محله‌ی لیتل‌هاوانا در میامی فلوریدا رسید.","src":[["Wikipedia — Cortado","https://en.wikipedia.org/wiki/Cortado"]]},{"id":107,"title":"کافه‌زینهو برزیلی (Brazilian Cafezinho)","body":"<ul><li><strong>گام ۱ (شکر):</strong> شکر را پیش از دم‌آوری به قهوه‌ی خشک اضافه کنید.</li><li><strong>گام ۲ (فیلتر):</strong> فیلتر پارچه‌ای (coador de pano) را خیس کنید.</li><li><strong>گام ۳ (آب):</strong> آب ۹۵ تا ۱۰۰ درجه را پس از ۳۰ ثانیه، آهسته و در ۳ تا ۴ نوبت بریزید.</li><li><strong>گام ۴ (سرو):</strong> بسیار داغ در فنجان کوچک (حدود ۶۰ تا ۸۰ میلی‌لیتر) سرو کنید.</li></ul>","kind":"item","description":"کافه‌زینهو قهوه‌ی کوچک، شیرین و قوی برزیلی است؛ پیش‌فرض خانه‌ها و دفترها و رد کردن آن در بیشتر موقعیت‌ها بی‌ادبانه شمرده می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"برزیل","caffeineLevel":0,"equipment":["فیلتر پارچه‌ای یا کاغذی روی قیف"],"ingredients":[{"amount":"۸–۱۰","unit":"گرم به ازای هر ۱۰۰ میلی‌لیتر","name":"قهوه‌ی رست تیره، آسیاب متوسط‌ریز"},{"amount":"۱–۲","unit":"قاشق چای‌خوری برای هر فنجان","name":"شکر"}],"steps":[{"label":"شکر","text":"شکر را پیش از دم‌آوری به قهوه‌ی خشک اضافه کنید."},{"label":"فیلتر","text":"فیلتر پارچه‌ای (coador de pano) را خیس کنید."},{"label":"آب","text":"آب ۹۵ تا ۱۰۰ درجه را پس از ۳۰ ثانیه، آهسته و در ۳ تا ۴ نوبت بریزید."},{"label":"سرو","text":"بسیار داغ در فنجان کوچک (حدود ۶۰ تا ۸۰ میلی‌لیتر) سرو کنید."}],"proTip":"شکرِ افزوده‌شده بعد از دم‌آوری طعمی متفاوت می‌دهد و فیلتر خشک جریان ناهموار می‌دهد.","variation":"","history":"فرانسیسکو دِ ملو پالیتا در ۱۷۲۷ بذرها را از گویان فرانسه قاچاق کرد (که خود افسانه خوانده شده) و تا میانه‌ی قرن ۱۹ برزیل صادرکننده‌ی غالب جهان بود. شرکت‌ها «کوپیرا» (copeira) استخدام می‌کنند تا در دفاتر کافه‌زینهو بچرخانند.","src":[["Caffè Atlas — Cafezinho","https://caffeatlas.com/coffee/cafezinho"]]},{"id":108,"title":"قهوه ادویه‌دار مغربی (Moroccan Spiced Coffee)","body":"<ul><li><strong>گام ۱ (ترکیب):</strong> قهوه و ادویه‌ها را با هم آسیاب یا مخلوط کنید.</li><li><strong>گام ۲ (دم‌آوری):</strong> با هر روش دلخواه دم کنید.</li><li><strong>گام ۳ (سرو):</strong> با شیر گرم و شکر سرو کنید.</li></ul>","kind":"item","description":"قهوه‌ی ادویه‌دار مراکشی: قهوه با ادویه‌هایی مثل دارچین، زنجبیل، جوزهندی، هل و فلفل سیاه آسیاب و دم می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"مراکش","caffeineLevel":0,"equipment":["جذوه یا قوری"],"ingredients":[{"amount":"½","unit":"پیمانه","name":"قهوه‌ی رست تیره"},{"amount":"۱","unit":"قاشق چای‌خوری","name":"دارچین"},{"amount":"۱","unit":"قاشق چای‌خوری","name":"زنجبیل"},{"amount":"½","unit":"قاشق چای‌خوری","name":"جوزهندی"},{"amount":"½","unit":"قاشق چای‌خوری","name":"هل"},{"amount":"½","unit":"قاشق چای‌خوری","name":"میخک"},{"amount":"½","unit":"قاشق چای‌خوری","name":"فلفل سیاه"},{"amount":"½","unit":"قاشق چای‌خوری","name":"بادیان"}],"steps":[{"label":"ترکیب","text":"قهوه و ادویه‌ها را با هم آسیاب یا مخلوط کنید."},{"label":"دم‌آوری","text":"با هر روش دلخواه دم کنید."},{"label":"سرو","text":"با شیر گرم و شکر سرو کنید."}],"proTip":"ادویه‌ها را به سلیقه تنظیم کنید؛ برای قهوه‌ی ملایم‌تر قهوه‌ی کمتر و آب بیشتر، و برای قوی‌تر برعکس بگیرید. قهوه و ادویه را تازه آسیاب کنید و مخلوط را می‌توان از پیش آماده نگه داشت.","variation":"برای طعم تندتر فلفل سیاه را بیشتر کنید یا کمی فلفل قرمز یا پاپریکا بیفزایید؛ برای نسخه‌ی ملایم‌تر و شیرین‌تر فلفل سیاه را حذف کنید؛ نیم قاشق چای‌خوری زردچوبه قهوه را شیرین‌تر و خامه‌ای‌تر می‌کند.","history":"چای عصرگاهی بخش بزرگی از فرهنگ مراکش است و این قهوه گونه‌ای از قهوه‌ی معمولی با ادویه‌های معطر است.","src":[["Salima's Kitchen — Moroccan Coffee","https://salimaskitchen.com/moroccan-coffee/"],["Wikipedia — Arabic coffee","https://en.wikipedia.org/wiki/Arabic_coffee"]]},{"id":214,"title":"قهوه روی ماسه‌ی داغ (Coffee on Hot Sand / Kumda Kahve)","body":"<ul><li><strong>گام ۱ (جذوه):</strong> قهوه‌ی ترک و آب سرد (و در صورت دلخواه شکر) را در جذوه بریزید.</li><li><strong>گام ۲ (شن داغ):</strong> جذوه را در تابه‌ی پر از شن داغ بر روی شعله بگذارید؛ شن حرارت را کنترل می‌کند و قهوه تقریباً فوراً کف می‌کند.</li><li><strong>گام ۳ (تکرار):</strong> این روند را سه تا چهار بار تکرار کنید.</li><li><strong>گام ۴ (سرو):</strong> قهوه را در فنجان‌های کوچک سرو کنید.</li></ul>","kind":"item","description":"در روش شن، جذوه‌ی پر از قهوه را در تابه‌ای پر از شن داغ می‌گذارند.","difficulty":"","prepTime":"","totalTime":"","origin":"ترکیه","caffeineLevel":0,"equipment":["دیگ مسی","شن داغ (یا ظرف مقاوم پر از ماسه‌ی داغ‌شده)"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی ترک"},{"amount":"—","unit":"","name":"آب"},{"amount":"—","unit":"","name":"شن داغ"}],"steps":[{"label":"جذوه","text":"قهوه‌ی ترک و آب سرد (و در صورت دلخواه شکر) را در جذوه بریزید."},{"label":"شن داغ","text":"جذوه را در تابه‌ی پر از شن داغ بر روی شعله بگذارید؛ شن حرارت را کنترل می‌کند و قهوه تقریباً فوراً کف می‌کند."},{"label":"تکرار","text":"این روند را سه تا چهار بار تکرار کنید.","meta":"۳–۴ بار"},{"label":"سرو","text":"قهوه را در فنجان‌های کوچک سرو کنید."}],"proTip":"با عمیق‌تر یا کم‌عمق‌تر گذاشتن جذوه در شن، حرارت را تنظیم کنید.","variation":"","history":"روش شن از شیوه‌های کهن دم‌کردن قهوه‌ی ترک شمرده می‌شود.","src":[["Wikipedia — Turkish coffee","https://en.wikipedia.org/wiki/Turkish_coffee"]]},{"id":612,"title":"کافه دی اولا (Café de Olla)","body":"<ul><li><strong>گام ۱ (دم‌آوری):</strong> قهوه را با دارچین و پیلونسیلو (و در صورت تمایل پوست پرتقال، انیسون یا میخک) در ظرف سفالی سنتی بپزید؛ ظرف سفالی طعم ویژه‌ای به قهوه می‌دهد.</li></ul>","kind":"item","description":"کافه د اولا (به معنای «قهوه‌ی دیگ») نوشیدنی سنتی مکزیکی است که اساس آن قهوه‌ی آسیاب‌شده، دارچین و پیلونسیلو است.","difficulty":"","prepTime":"","totalTime":"","origin":"مکزیک","caffeineLevel":0,"equipment":["قوری سفالی (اولا)"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی آسیاب‌شده"},{"amount":"—","unit":"","name":"دارچین"},{"amount":"—","unit":"","name":"پیلونسیلو (شکر خام مکزیکی)"},{"amount":"—","unit":"","name":"اختیاری: پوست پرتقال، انیسون، میخک"}],"steps":[{"label":"دم‌آوری","text":"قهوه را با دارچین و پیلونسیلو (و در صورت تمایل پوست پرتقال، انیسون یا میخک) در ظرف سفالی سنتی بپزید؛ ظرف سفالی طعم ویژه‌ای به قهوه می‌دهد."}],"proTip":"این نوع قهوه بیشتر در مناطق سردسیر و روستایی مصرف می‌شود. نوشیدنی را در فنجان سفالی سنتی سرو می‌کنند.","variation":"","history":"","src":[["Wikipedia — Caf%C3%A9 de olla","https://en.wikipedia.org/wiki/Caf%C3%A9_de_olla"]]},{"id":613,"title":"سوبیا کافی (Sobia Coffee – مصر و حجاز)","body":"<ul><li><strong>گام ۱ (سوبیا):</strong> برنج دانه‌کوتاه را حدود دو ساعت خیس کنید، روی حرارت ملایم بپزید تا آب را بکشد، سپس خنک کنید و با شیر سرد، نارگیل، شکر و وانیل مخلوط و صاف کنید.</li><li><strong>گام ۲ (اسپرسو):</strong> یک شات اسپرسو بگیرید.</li><li><strong>گام ۳ (ترکیب):</strong> سوبیا را با اسپرسو بیامیزید؛ شیرینی سوبیا تلخی قهوه را متعادل می‌کند و نوشیدنی خامه‌ای و شبیه لاته می‌شود.</li><li><strong>گام ۴ (سرو):</strong> برخی کافه‌ها آن را به‌صورت آیس لاته یا کلد برو سرو می‌کنند.</li></ul>","kind":"item","description":"سوبیا کافی ترکیب سوبیا (نوشیدنی شیرین و نارگیلی رمضان مصر) با اسپرسو است؛ طعمی شبیه لاته دارد.","difficulty":"","prepTime":"","totalTime":"","origin":"مصر","caffeineLevel":0,"equipment":["مخلوط‌کن یا صافی (برای سوبیا)","دستگاه اسپرسو یا قهوه‌ی سرد آماده"],"ingredients":[{"amount":"۱","unit":"شات","name":"اسپرسو"},{"amount":"—","unit":"","name":"سوبیا"}],"steps":[{"label":"سوبیا","text":"برنج دانه‌کوتاه را حدود دو ساعت خیس کنید، روی حرارت ملایم بپزید تا آب را بکشد، سپس خنک کنید و با شیر سرد، نارگیل، شکر و وانیل مخلوط و صاف کنید.","meta":"≈۲ ساعت"},{"label":"اسپرسو","text":"یک شات اسپرسو بگیرید.","meta":"۱ شات"},{"label":"ترکیب","text":"سوبیا را با اسپرسو بیامیزید؛ شیرینی سوبیا تلخی قهوه را متعادل می‌کند و نوشیدنی خامه‌ای و شبیه لاته می‌شود."},{"label":"سرو","text":"برخی کافه‌ها آن را به‌صورت آیس لاته یا کلد برو سرو می‌کنند."}],"proTip":"شیرینی سوبیا تلخی قهوه را می‌گیرد؛ پس شکر اضافه لازم نیست.","variation":"سوبیا کافی را می‌توان به‌شکل آیس لاته یا کلد برو سرو کرد.","history":"Egyptian Streets آن را «یکی از بزرگ‌ترین ترندهای امسال» می‌نامد که از رمضان فراتر رفته و برخی کافه‌ها آن را در تمام سال عرضه می‌کنند. سوبیا نوشیدنی سردی در مصر و عربستان است: نسخه‌ی مصری امروز برنج، نارگیل، شیر و شکر دارد و نسخه‌ی اولیه احتمالاً تخمیری و بدون نارگیل بوده؛ نسخه‌ی حجازی از آرد گندم، مالت، شکر و ادویه یا شربتی از جو و نان خشک با هل و دارچین ساخته می‌شود.","src":[["Egyptian Streets — Reinventing Ramadan Drinks","https://egyptianstreets.com/2025/03/24/reinventing-ramadan-drinks-how-egypt-is-blending-tradition-with-modern-coffee-culture/"],["Wikipedia — Sobia","https://en.wikipedia.org/wiki/Sobia"]]},{"id":615,"title":"کافه کان لچه (Café con Leche)","body":"<ul><li><strong>گام ۱ (اسپرسو):</strong> اسپرسو را بگیرید (یا قهوه‌ی فوری غلیظ، قهوه‌ی کپسولی یا قهوه‌ی کنسروی).</li><li><strong>گام ۲ (گرم‌کردن شیر):</strong> شیر را با لوله‌ی بخار تا کمی زیر نقطه‌ی جوش گرم کنید؛ گاهی شکر را هنگام گرم‌شدن به شیر می‌افزایند.</li><li><strong>گام ۳ (ترکیب):</strong> شیر گرم را روی اسپرسو بریزید و هم بزنید؛ مقدار قهوه و شیر تقریباً برابر است.</li><li><strong>گام ۴ (سرو):</strong> اسپرسو و شیر داغ‌شده را می‌توان جدا سرو کرد تا خود نوشنده ترکیب کند (yo lo preparo).</li></ul>","kind":"item","description":"کافه کون لچه قهوه‌ی قوی (معمولاً اسپرسو) است که با تقریباً همان مقدار شیر داغ‌شده ترکیب می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"اسپانیا / آمریکای لاتین","caffeineLevel":0,"equipment":["دستگاه اسپرسو یا قهوه‌ی فوری غلیظ"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی قوی (معمولاً اسپرسو)"},{"amount":"≈ برابر قهوه","unit":"","name":"شیر داغ‌شده (scalded)"}],"steps":[{"label":"اسپرسو","text":"اسپرسو را بگیرید (یا قهوه‌ی فوری غلیظ، قهوه‌ی کپسولی یا قهوه‌ی کنسروی)."},{"label":"گرم‌کردن شیر","text":"شیر را با لوله‌ی بخار تا کمی زیر نقطه‌ی جوش گرم کنید؛ گاهی شکر را هنگام گرم‌شدن به شیر می‌افزایند."},{"label":"ترکیب","text":"شیر گرم را روی اسپرسو بریزید و هم بزنید؛ مقدار قهوه و شیر تقریباً برابر است.","meta":"۱ به ۱"},{"label":"سرو","text":"اسپرسو و شیر داغ‌شده را می‌توان جدا سرو کرد تا خود نوشنده ترکیب کند (yo lo preparo)."}],"proTip":"شیر کامل رایج‌ترین است؛ شیرهای دیگر، لبنی یا گیاهی، طعم و بافت را عوض می‌کنند. شکر یا شیرین‌کننده را به سلیقه بیفزایید؛ در بعضی نسخه‌ها کمی نمک هم می‌ریزند.","variation":"در اسپانیا: «کلاریتو» یا «مانچادو» (روشن، شیر بیشتر) و «اوسکوریتو» (تیره، شیر کمتر). در رستوران‌های کوبایی و پورتوریکویی اغلب با شکر.","history":"خاستگاه آن اسپانیاست، هرچند خاستگاه دقیقش روشن نیست. نخست در اسپانیا رواج یافت و سپس به دیگر کشورهای اسپانیایی‌زبان و جوامع مهاجر آمریکای لاتین در سراسر جهان رسید.","src":[["Wikipedia — Caf%C3%A9 con leche","https://en.wikipedia.org/wiki/Caf%C3%A9_con_leche"]]},{"id":616,"title":"مازاگران (Mazagran)","body":"<ul><li><strong>گام ۱ (شیرین‌کردن):</strong> قهوه‌ی قوی یا اسپرسو را با شکر یا شربت شکر شیرین کنید.</li><li><strong>گام ۲ (یخ):</strong> لیوان بلند و باریک را از یخ پر کنید.</li><li><strong>گام ۳ (ریختن):</strong> قهوه‌ی داغ را روی یخ بریزید.</li><li><strong>گام ۴ (سرو):</strong> با یک برش لیمو سرو کنید؛ در سبک سنتی ظرف کوچکی آب هم کنار آن می‌گذارند تا به‌جای شیر با قهوه مخلوط شود.</li></ul>","kind":"item","description":"مازاگران قهوه‌ی شیرین‌شده‌ی سردی است که روی یخ سرو می‌شود و آن را «نخستین قهوه‌ی یخی» می‌نامند؛ خاستگاهش الجزایر است.","difficulty":"","prepTime":"","totalTime":"","origin":"الجزایر","caffeineLevel":0,"equipment":["لیوان بلند و باریک","دستگاه اسپرسو یا قهوه‌ی قوی"],"ingredients":[{"amount":"—","unit":"","name":"اسپرسو یا قهوه‌ی قوی"},{"amount":"—","unit":"","name":"شکر یا شربت شکر"},{"amount":"—","unit":"","name":"یخ"},{"amount":"—","unit":"","name":"آب (برای رقیق‌کردن، اختیاری)"},{"amount":"—","unit":"","name":"برش لیمو (اختیاری)"}],"steps":[{"label":"شیرین‌کردن","text":"قهوه‌ی قوی یا اسپرسو را با شکر یا شربت شکر شیرین کنید."},{"label":"یخ","text":"لیوان بلند و باریک را از یخ پر کنید."},{"label":"ریختن","text":"قهوه‌ی داغ را روی یخ بریزید."},{"label":"سرو","text":"با یک برش لیمو سرو کنید؛ در سبک سنتی ظرف کوچکی آب هم کنار آن می‌گذارند تا به‌جای شیر با قهوه مخلوط شود."}],"proTip":"قهوه یا اسپرسو را قوی بگیرید تا روی یخ طعمش را از دست ندهد.","variation":"پرتغال: قهوه‌ی یخی شیرین با لیمو و گاهی نعناع و رام. اتریش: با یک تکه یخ و رام یا ماراسکینو، معمولاً یک‌جرعه نوشیده می‌شود. کاتالونیا و والنسیا: قهوه روی یخ با پوست لیمو («کافه دل تیمپو»، یعنی قهوه‌ی هوا).","history":"مازاگران حدود ۱۸۴۰ در الجزایر پدید آمد و مردم محلی آن را «اولین قهوه‌ی سرد» می‌نامیدند.","src":[["Wikipedia — Iced coffee","https://en.wikipedia.org/wiki/Iced_coffee"],["Wikipedia — Mazagran (drink)","https://en.wikipedia.org/wiki/Mazagran_(drink)"]]},{"id":617,"title":"قهوه‌ی تخم‌مرغی اسکاندیناوی (Scandinavian Egg Coffee / Farmer’s Coffee)","body":"<ul><li><strong>گام ۱ (آماده‌سازی تخم‌مرغ):</strong> تخم‌مرغ را با کمی آب بزنید تا غلظتش شبیه خمیر نان تُست فرانسوی شود.</li><li><strong>گام ۲ (مخلوط‌کردن):</strong> قهوه‌ی آسیاب‌شده را با مقداری از این مایع خیس کنید و بکوبید تا خمیر شود؛ اگر خواستید پوست خردشده‌ی تخم‌مرغ را هم بیفزایید.</li><li><strong>گام ۳ (جوشاندن):</strong> مخلوط را به آب در حال جوش اضافه کنید، حرارت را طوری تنظیم کنید که سرریز نشود و کوتاه بجوشانید، سپس از روی حرارت بردارید.</li><li><strong>گام ۴ (ته‌نشین‌کردن):</strong> کمی آب سرد روی آن بریزید یا صبر کنید تا تفاله ته‌نشین شود.</li><li><strong>گام ۵ (صاف‌کردن):</strong> قهوه را با صافی کوچک در فنجان‌ها بریزید.</li></ul>","kind":"item","description":"قهوه‌ی تخم‌مرغی سوئدی یک نوشیدنی آمریکایی معرفی شده است.","difficulty":"","prepTime":"","totalTime":"","origin":"آمریکا","caffeineLevel":0,"equipment":["قوری بزرگ","صافی پارچه‌ای"],"ingredients":[{"amount":"۳ تا ۴","unit":"قاشق غذاخوری","name":"قهوه‌ی آسیاب‌شده (برای حدود ۱۲ فنجان)"},{"amount":"۱","unit":"عدد","name":"تخم‌مرغ"},{"amount":"","unit":"","name":"آب"}],"steps":[{"label":"آماده‌سازی تخم‌مرغ","text":"تخم‌مرغ را با کمی آب بزنید تا غلظتش شبیه خمیر نان تُست فرانسوی شود."},{"label":"مخلوط‌کردن","text":"قهوه‌ی آسیاب‌شده را با مقداری از این مایع خیس کنید و بکوبید تا خمیر شود؛ اگر خواستید پوست خردشده‌ی تخم‌مرغ را هم بیفزایید."},{"label":"جوشاندن","text":"مخلوط را به آب در حال جوش اضافه کنید، حرارت را طوری تنظیم کنید که سرریز نشود و کوتاه بجوشانید، سپس از روی حرارت بردارید.","meta":"۳۰ تا ۶۰ ثانیه"},{"label":"ته‌نشین‌کردن","text":"کمی آب سرد روی آن بریزید یا صبر کنید تا تفاله ته‌نشین شود."},{"label":"صاف‌کردن","text":"قهوه را با صافی کوچک در فنجان‌ها بریزید."}],"proTip":"پروتئین تخم‌مرغ به تفاله می‌چسبد و روی سطح لایه‌ای شناور می‌سازد؛ افزودن آب سرد در پایان آن را ته‌نشین می‌کند و قهوه را زلال‌تر می‌کند. پوست تخم‌مرغ تلخی را کم می‌کند.","variation":"این قهوه معمولاً ملایم دم می‌شود و اغلب بدون افزودنی نوشیده می‌شود.","history":"مهاجران اسکاندیناوی در میانه‌ی قرن نوزدهم در غرب میانه‌ی آمریکا، چون قهوه‌ساز و فیلتر نداشتند، قهوه را فقط دم می‌کردند و حاصل پر از ذرات بود؛ برای زلال‌کردنش از تخم‌مرغ استفاده کردند. در نروژ سنتی مشابه با پوست و مثانه‌ی شنای ماهی («کلارشین») وجود داشت. کلیسای سالم لوتری از ۱۹۴۶، همزمان با افتتاح رستورانش، آن را در نمایشگاه ایالتی مینه‌سوتا سرو می‌کند.","src":[["Wikipedia — Egg coffee","https://en.wikipedia.org/wiki/Egg_coffee"],["Atlas Obscura — Midwest Swedish Egg Coffee","https://atlasobscura.com/articles/midwest-swedish-egg-coffee"]]},{"id":618,"title":"قهوه آتشی (Flaming Coffee / Café Brûlot)","body":"<ul><li><strong>گام ۱ (ایمنی):</strong> نوشیدنی شعله‌ور است؛ با احتیاط و روی سطح نسوز کار کنید.</li><li><strong>گام ۲ (گرم‌کردن):</strong> دارچین، میخک، پوست لیمو، شکر و براندی را در ظرف نسوز روی شعله گرم کنید؛ داغ باشد اما نجوشد.</li><li><strong>گام ۳ (شعله):</strong> ظرف را روی میز ببرید، با کبریت روشن کنید و مایع شعله‌ور را حدود ۲ دقیقه با ملاقه به اطراف بریزید.</li><li><strong>گام ۴ (قهوه):</strong> قهوه‌ی داغ را در براندی شعله‌ور بریزید.</li><li><strong>گام ۵ (سرو):</strong> با ملاقه در فنجان‌های دمی‌تاس بریزید.</li></ul>","kind":"item","description":"کافه برولوی دیابولیک نوشیدنی شعله‌ور نیواورلئان با قهوه، براندی و ادویه است.","difficulty":"","prepTime":"","totalTime":"","origin":"نیواورلئان","caffeineLevel":0,"equipment":["فنجان یا ظرف نسوز","قاشق فلزی برای شعله‌ور کردن"],"ingredients":[{"amount":"۳","unit":"فنجان","name":"قهوه‌ی سیاه قوی"},{"amount":"۳","unit":"اونس (حدود ۹۰ میلی‌لیتر)","name":"براندی"},{"amount":"۱٫۵","unit":"قاشق غذاخوری","name":"شکر"},{"amount":"۲","unit":"چوب","name":"دارچین"},{"amount":"۸","unit":"عدد","name":"میخک"},{"amount":"۱","unit":"عدد","name":"پوست لیمو"}],"steps":[{"label":"ایمنی","text":"نوشیدنی شعله‌ور است؛ با احتیاط و روی سطح نسوز کار کنید."},{"label":"گرم‌کردن","text":"دارچین، میخک، پوست لیمو، شکر و براندی را در ظرف نسوز روی شعله گرم کنید؛ داغ باشد اما نجوشد."},{"label":"شعله","text":"ظرف را روی میز ببرید، با کبریت روشن کنید و مایع شعله‌ور را حدود ۲ دقیقه با ملاقه به اطراف بریزید.","meta":"۲ دقیقه"},{"label":"قهوه","text":"قهوه‌ی داغ را در براندی شعله‌ور بریزید."},{"label":"سرو","text":"با ملاقه در فنجان‌های دمی‌تاس بریزید."}],"proTip":"","variation":"دستور Saveur (گالاتوآز): ۳ فنجان قهوه، ½ فنجان براندی، ¼ فنجان لیکور پرتقال، ۱۲ میخک، ۲ چوب دارچین، پوست یک پرتقال ناول و پوست یک لیمو؛ برای ۸ نفر. براندی و لیکور با پوست‌ها ۵ دقیقه ملایم گرم و روشن می‌شود.","history":"طبق New Orleans & Company، آن را اواخر دهه‌ی ۱۸۸۰ در رستوران آنتوان ابداع کردند و ژول آلسیاتور، پسر بنیان‌گذار، مبدع آن بود (به نقل از Mixing New Orleans، الهام‌گرفته از فرانسوی‌هایی که حبه‌ی قندِ خیس‌شده در کنیاک را شعله‌ور در قهوه می‌انداختند). Daily Coffee News می‌نویسد دست‌کم ۲۰۰ سال قدمت دارد، ریشه‌ی فرانسوی و هویت لوئیزیانایی دارد و در لوئیزیانا اغلب با مخلوط قهوه و کاسنی بوده است.","src":[["New Orleans & Company — Café Brulot Diabolique","https://www.neworleans.com/drink/cocktails/cafe-brulot-diabolique/"],["Saveur — Café Brûlot (Creole Coffee)","https://www.saveur.com/article/Wine-and-Drink/Creole-Coffee-"],["Daily Coffee News — The History of the Boozy Café Brûlot","https://dailycoffeenews.com/2019/02/19/playing-with-fire-the-history-of-the-boozy-cafe-brulot/"]]},{"id":619,"title":"سه‌دری (Three-in-One)","body":"<ul><li><strong>گام ۱ (ریختن پودر):</strong> پودر قهوه‌ی فوری پیش‌مخلوط را در فنجان یا لیوان بریزید.</li><li><strong>گام ۲ (افزودن مایع):</strong> آب داغ روی آن بریزید؛ در برخی کشورها مانند پرتغال، اسپانیا و هند به‌جای آب از شیر داغ استفاده می‌کنند.</li><li><strong>گام ۳ (تنظیم قدرت):</strong> قدرت قهوه به نسبت پودر به مایع بستگی دارد؛ برای قهوه‌ی ملایم‌تر مایع بیشتری بریزید.</li></ul>","kind":"item","description":"قهوه‌ی فوری پیش‌مخلوط با خامه‌ی غیرلبنی و شکر در برخی کشورهای آسیا محبوب است.","difficulty":"","prepTime":"","totalTime":"","origin":"آسیا","caffeineLevel":0,"equipment":["فنجان یا لیوان"],"ingredients":[{"amount":"۱","unit":"پاکت","name":"قهوه‌ی فوری + خامه‌ی غیرلبنی + شکر"}],"steps":[{"label":"ریختن پودر","text":"پودر قهوه‌ی فوری پیش‌مخلوط را در فنجان یا لیوان بریزید."},{"label":"افزودن مایع","text":"آب داغ روی آن بریزید؛ در برخی کشورها مانند پرتغال، اسپانیا و هند به‌جای آب از شیر داغ استفاده می‌کنند."},{"label":"تنظیم قدرت","text":"قدرت قهوه به نسبت پودر به مایع بستگی دارد؛ برای قهوه‌ی ملایم‌تر مایع بیشتری بریزید."}],"proTip":"کافئین قهوه‌ی فوری معمولاً کمتر از قهوه‌ی دم‌شده است: میانه‌ی ۶۶ میلی‌گرم هر فنجان در برابر ۱۱۲ میلی‌گرم در قهوه‌ی قطره‌ای (فنجان ۲۲۵ میلی‌لیتر).","variation":"برای قهوه‌ی سرد می‌توان آب سرد به کار برد، مانند فراپه‌ی یونانی.","history":"قهوه‌ی فوری «با خامه‌ی غیرلبنی و شکر نیز پیش‌مخلوط فروخته می‌شود؛ در کره‌ی جنوبی محبوب است و «coffee mix» نام دارد.» در ۲۰۲۵ آسیا-اقیانوسیه ۳۹ درصد بازار قهوه‌ی فوری را داشت.","src":[["Wikipedia — Instant coffee","https://en.wikipedia.org/wiki/Instant_coffee"]]},{"id":630,"title":"کافه سوا دا ویتنامی (Cà phê sữa đá)","body":"<ul><li><strong>گام ۱ (شیر تغلیظ‌شده):</strong> شیر تغلیظ‌شده‌ی شیرین را در یک فنجان کوچک بریزید.</li><li><strong>گام ۲ (دم‌آوری):</strong> قهوه‌ی روبوستای تیره‌برشته را در فین بریزید و آب داغ روی آن بریزید تا قطره‌قطره داخل فنجان بچکد.</li><li><strong>گام ۳ (هم‌زدن):</strong> قهوه و شیر تغلیظ‌شده را خوب هم بزنید.</li><li><strong>گام ۴ (یخ):</strong> مخلوط را در لیوان بلندی پر از یخ بریزید.</li></ul>","kind":"item","description":"کافه سوا دا از ریختن آب داغ از فیلتر فلزی سنتی «فین» روی قهوه‌ی روبوستای تیره‌برشته، با شیر تغلیظ‌شده و یخ ساخته می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"ویتنام","caffeineLevel":0,"equipment":["فین (فیلتر فلزی ویتنامی)","آسیاب","کتری"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی روبوستای تیره‌برشته"},{"amount":"—","unit":"","name":"شیر تغلیظ‌شده‌ی شیرین"},{"amount":"—","unit":"","name":"یخ"}],"steps":[{"label":"شیر تغلیظ‌شده","text":"شیر تغلیظ‌شده‌ی شیرین را در یک فنجان کوچک بریزید."},{"label":"دم‌آوری","text":"قهوه‌ی روبوستای تیره‌برشته را در فین بریزید و آب داغ روی آن بریزید تا قطره‌قطره داخل فنجان بچکد.","meta":"۴ تا ۵ دقیقه"},{"label":"هم‌زدن","text":"قهوه و شیر تغلیظ‌شده را خوب هم بزنید."},{"label":"یخ","text":"مخلوط را در لیوان بلندی پر از یخ بریزید."}],"proTip":"روبوستای تیره‌برشته با شیر تغلیظ‌شده بهترین جفت شناخته شد و تقریباً دو برابر کافئین آرابیکای متوسط‌برشته را دارد.","variation":"کافه دا (قهوه‌ی سیاه)؛ باک‌شیو (شیر تغلیظ‌شده و شیر تازه با کمی قهوه، از دهه‌ی ۱۹۵۰ در چولون سایگون)؛ کافه چونگ (قهوه با کف زرده‌ی تخم‌مرغ و شیر تغلیظ‌شده، هانوی ۱۹۴۶)؛ کافه موئی (با کف خامه‌ی شور، هوئه ۲۰۱۰)؛ قهوه با ماست (هانوی ۲۰۱۲)؛ قهوه‌ی نارگیل؛ قهوه‌ی آووکادو؛ قهوه‌ی پاندان.","history":"ریشه‌ی این نوشیدنی در ویتنامِ مستعمره‌ی فرانسه است و آن را اقتباسی از «کافه‌ او لِه» می‌دانند. صنعت لبنیات ویتنام نوپا بود و شیر تازه در گرما زود فاسد می‌شد؛ پس شیر تغلیظ‌شده‌ی شیرین وارداتی با ماندگاری بالا جایگزین شد. روبوستای تیره‌برشته به‌دلیل تلخی بیشتر، شیرینی شیر را بهتر متعادل می‌کرد و یخ را برای مقابله با گرمای استوایی افزودند.","src":[["Wikipedia — Vietnamese iced coffee","https://en.wikipedia.org/wiki/Vietnamese_iced_coffee"],["CoffeeGeek — How to Make Vietnamese Iced Coffee","https://coffeegeek.com/guides/howtos/how-to-make-vietnamese-iced-coffee/"]]},{"id":631,"title":"کوپی توبروک اندونزیایی (Kopi Tubruk)","body":"<ul><li><strong>گام ۱ (آماده‌سازی):</strong> قهوه‌ی بسیار ریزآسیاب‌شده را در یک لیوان شفاف بریزید.</li><li><strong>گام ۲ (دم‌آوری):</strong> آب جوشیده را مستقیم در لیوان روی قهوه بریزید؛ فیلتر یا صافی به کار نمی‌رود.</li><li><strong>گام ۳ (شیرین‌کردن):</strong> معمولاً شکر هم اضافه می‌شود؛ برخی گونه‌های مدرن شیر تغلیظ‌شده می‌افزایند.</li><li><strong>گام ۴ (ته‌نشین‌شدن):</strong> صبر کنید تا تفاله ته لیوان بنشیند و بعد بنوشید.</li></ul>","kind":"item","description":"کوپی توبروک قهوه‌ی ریزآسیاب است که آب جوش مستقیم در لیوان روی آن ریخته می‌شود، بدون صاف‌کردن و معمولاً با شکر.","difficulty":"","prepTime":"","totalTime":"","origin":"اندونزی","caffeineLevel":0,"equipment":["لیوان","کتری"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی ریزآسیاب"},{"amount":"—","unit":"","name":"آب جوشیده"},{"amount":"—","unit":"","name":"شکر (اختیاری)"}],"steps":[{"label":"آماده‌سازی","text":"قهوه‌ی بسیار ریزآسیاب‌شده را در یک لیوان شفاف بریزید."},{"label":"دم‌آوری","text":"آب جوشیده را مستقیم در لیوان روی قهوه بریزید؛ فیلتر یا صافی به کار نمی‌رود."},{"label":"شیرین‌کردن","text":"معمولاً شکر هم اضافه می‌شود؛ برخی گونه‌های مدرن شیر تغلیظ‌شده می‌افزایند."},{"label":"ته‌نشین‌شدن","text":"صبر کنید تا تفاله ته لیوان بنشیند و بعد بنوشید."}],"proTip":"«کوپی» در اندونزیایی یعنی قهوه و «توبروک» واژه‌ای جاوه‌ای به معنی برخورد است؛ نام هم به نوشیدنی و هم به روش دم‌آوری آن اشاره دارد. گاهی به‌جای قهوه‌ی آسیاب‌شده، قهوه‌ی فوری بدون شکر و شیر به کار می‌رود.","variation":"در بالی «کوپی سِلِم» (قهوه‌ی سیاه) نام دارد.","history":"گمان می‌رود تاجران خاورمیانه کوپی توبروک را به اندونزی آورده باشند. در یوگیاکارتا و جاوه‌ی مرکزی محبوب است و در بیشتر «وارونگ»‌هایی که قهوه می‌فروشند پیدا می‌شود.","src":[["Wikipedia — Kopi tubruk","https://en.wikipedia.org/wiki/Kopi_tubruk"]]},{"id":632,"title":"اینشپنر وینی (Einspänner)","body":"<ul><li><strong>گام ۱ (اسپرسو):</strong> اسپرسو (در اصطلاح وینی «موکا») را آماده کنید.</li><li><strong>گام ۲ (لیوان):</strong> اسپرسو را در لیوان بریزید؛ این نوشیدنی به‌طور سنتی در لیوان سرو می‌شود، نه فنجان.</li><li><strong>گام ۳ (خامه):</strong> روی اسپرسو خامه‌ی فرم‌گرفته بگذارید.</li></ul>","kind":"item","description":"اینشپنر اسپرسو («موکا» در اصطلاح وینی) با خامه‌ی فرم‌گرفته است که به‌طور سنتی در لیوان سرو می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"اتریش (وین)","caffeineLevel":0,"equipment":["لیوان دسته‌دار","همزن"],"ingredients":[{"amount":"—","unit":"","name":"اسپرسو"},{"amount":"—","unit":"","name":"خامه‌ی فرم‌گرفته"}],"steps":[{"label":"اسپرسو","text":"اسپرسو (در اصطلاح وینی «موکا») را آماده کنید."},{"label":"لیوان","text":"اسپرسو را در لیوان بریزید؛ این نوشیدنی به‌طور سنتی در لیوان سرو می‌شود، نه فنجان."},{"label":"خامه","text":"روی اسپرسو خامه‌ی فرم‌گرفته بگذارید."}],"proTip":"","variation":"در دهه‌ی ۲۰۲۰ اینشپنر پیشگام نوشیدنی‌های خامه‌دار در کافه‌های کره‌ی جنوبی (از قهوه‌ی سرد تا لاته‌ی ماچا) دانسته شد و کافه‌های سبک کره‌ای آن و مشتقاتش را در آمریکا رواج داده‌اند.","history":"نام به کالسکه‌ی تک‌اسبه‌ی رایج در وین قرن نوزدهم اشاره دارد و نوشیدنی برای کالسکه‌چی‌ها بود. خامه برای عایق‌کردن قهوه در روزهای سرد و گرم‌نگه‌داشتن آن به کار می‌رفت و اینشپنر به‌سرعت در قهوه‌خانه‌های وین جا افتاد.","src":[["Wikipedia — Einsp%C3%A4nner","https://en.wikipedia.org/wiki/Einsp%C3%A4nner"]]},{"id":633,"title":"کافه توبا سنگالی (Café Touba)","body":"<ul><li><strong>گام ۱ (برشته‌کاری):</strong> ادویه با دانه‌های قهوه مخلوط و برشته و سپس پودر می‌شود.</li><li><strong>گام ۲ (دم‌آوری):</strong> با فیلتر، مشابه قهوه‌ی قطره‌ای دم می‌شود.</li></ul>","kind":"item","description":"کافه توبا قهوه‌ای است که با دانه‌های سلیم (فلفل گینه‌ای، djar) طعم‌دار می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"سنگال","caffeineLevel":0,"equipment":["قهوه‌جوش","صافی پارچه‌ای"],"ingredients":[{"amount":"۸۰","unit":"درصد","name":"قهوه"},{"amount":"۲۰","unit":"درصد","name":"djar (فلفل گینه‌ای؛ گاهی میخک)"}],"steps":[{"label":"برشته‌کاری","text":"ادویه با دانه‌های قهوه مخلوط و برشته و سپس پودر می‌شود."},{"label":"دم‌آوری","text":"با فیلتر، مشابه قهوه‌ی قطره‌ای دم می‌شود."}],"proTip":"افزودن djar که در توبا کشت می‌شود عامل اصلی تمایز کافه توبا از قهوه‌ی ساده است.","variation":"قهوه‌ی ساده بدون djar کافه توبا شمرده نمی‌شود؛ گاهی میخک هم به ترکیب افزوده می‌شود. نستله در واکنش به محبوبیت آن محصول «نسکافه جینجر اند اسپایس» را عرضه کرد.","history":"نام از شهر توبای سنگال است. نوشیدنی را به‌طور سنتی برادری اسلامی «مرید» می‌نوشد؛ بنیان‌گذار، شیخ احمدو بامبا، در ۱۹۰۲ از تبعید در گابن بازگشت. در مراسم، بزرگداشت‌ها و «گراند ماگال توبا» سرو می‌شود. در گینه‌بیسائو هم مصرف می‌شود و در شهرهای دین‌های مختلف رایج‌تر شده است؛ پس از رکود جهانی ۲۰۰۹، گزارش شده که بعضی مناطق فقیرتر سنگال، حتی در صبحانه، بیشتر آن را نوشیدند.","src":[["Wikipedia — Caf%C3%A9 Touba","https://en.wikipedia.org/wiki/Caf%C3%A9_Touba"]]},{"id":634,"title":"کافه‌سیتو کوبایی (Cafecito)","body":"<ul><li><strong>گام ۱ (اسپومیتا):</strong> سنتی است که شکر قهوه‌ای را با اولین و قوی‌ترین قطره‌های اسپرسو به‌شدت با قاشق بزنند تا کف کرمی بسازد. گرمای قهوه شکر بیشتری را حل می‌کند.</li><li><strong>گام ۲ (قهوه):</strong> اسپرسو با دستگاه الکتریکی یا (رایج‌تر) با موکاپات ساخته می‌شود.</li></ul>","kind":"item","description":"کافه کوبایی اسپرسویی با دارچینی‌رنگ‌ترین بُن‌تیره و «اسپومیتا»ی شکر است.","difficulty":"","prepTime":"","totalTime":"","origin":"کوبا","caffeineLevel":0,"equipment":["موکاپات یا دستگاه اسپرسو"],"ingredients":[{"amount":"—","unit":"","name":"اسپرسو (برشته‌ی تیره، ایتالیایی یا اسپانیایی)"},{"amount":"—","unit":"","name":"شکر دمارا یا قهوه‌ای"}],"steps":[{"label":"اسپومیتا","text":"سنتی است که شکر قهوه‌ای را با اولین و قوی‌ترین قطره‌های اسپرسو به‌شدت با قاشق بزنند تا کف کرمی بسازد. گرمای قهوه شکر بیشتری را حل می‌کند."},{"label":"قهوه","text":"اسپرسو با دستگاه الکتریکی یا (رایج‌تر) با موکاپات ساخته می‌شود."}],"proTip":"","variation":"کورتادیتو: نسبت اسپرسو به شیر بین ۵۰/۵۰ تا ۷۵/۲۵. کولادا: ۳ تا ۶ شات اسپرسوی کوبایی در لیوان بزرگ همراه فنجان‌های کوچک.","history":"«کافه کوبانو» نوعی اسپرسوست که در کوبا پدید آمد و نوشیدنش در کوبا و جوامع کوبایی‌تبار فعالیت اجتماعی و فرهنگی برجسته‌ای است. برندهای محبوب: کافه بوستلو، کافه لا یاوه و کافه پیلون.","src":[["Wikipedia — Cuban espresso","https://en.wikipedia.org/wiki/Cuban_espresso"]]},{"id":635,"title":"یوئن‌یانگ هنگ‌کنگی (Yuenyang)","body":"<ul><li><strong>گام ۱ (ترکیب):</strong> طبق ادارهٔ خدمات فرهنگی و فراغتی هنگ‌کنگ، سه قسمت قهوه با هفت قسمت چای شیر سبک هنگ‌کنگی مخلوط می‌شود؛ ترکیب دقیق بسته به فروشنده و منطقه فرق می‌کند. گرم یا سرد سرو می‌شود.</li></ul>","kind":"item","description":"یوئن‌یانگ ترکیبی از قهوه‌ی دم‌شده و چای سیاه با شکر و شیر است.","difficulty":"","prepTime":"","totalTime":"","origin":"هنگ‌کنگ","caffeineLevel":0,"equipment":["قهوه‌ساز","صافی"],"ingredients":[{"amount":"۳","unit":"قسمت","name":"قهوه"},{"amount":"۷","unit":"قسمت","name":"چای شیر هنگ‌کنگی"}],"steps":[{"label":"ترکیب","text":"طبق ادارهٔ خدمات فرهنگی و فراغتی هنگ‌کنگ، سه قسمت قهوه با هفت قسمت چای شیر سبک هنگ‌کنگی مخلوط می‌شود؛ ترکیب دقیق بسته به فروشنده و منطقه فرق می‌کند. گرم یا سرد سرو می‌شود.","meta":"۳:۷"}],"proTip":"","variation":"نسخه‌ی یخ یا گرم؛ استارباکس هنگ‌کنگ و ماکائو در تابستان ۲۰۱۰ نسخه‌ی فراپاچینوی آن را فروخت. در مالزی «کوپی چم» نام دارد. نسخه‌ی کودکان بدون کافئین با هورلیکس و اووالتین ساخته می‌شود.","history":"نوشیدنی در هنگ‌کنگ، در دای‌پای‌دونگ (فروشندگان فضای باز) و چا‌چان‌تنگ (کافه‌ها) پدید آمد. ادعای لان‌فونگ‌یوئن مبنی بر ابداع آن در ۱۹۵۲ توسط لام موک‌هو تأییدنشده است. نام به مرغابی‌های ماندارین (یوان‌یانگ)، نماد عشق زناشویی در فرهنگ چینی، اشاره دارد.","src":[["Wikipedia — Yuenyeung","https://en.wikipedia.org/wiki/Yuenyeung"]]},{"id":643,"title":"کاراخیو (Carajillo)","body":"<ul><li><strong>گام ۱ (اسپرسو):</strong> دو شات اسپرسو بگیرید؛ هر شات حدود ۴۵ میلی‌لیتر.</li><li><strong>گام ۲ (یخ و لیکور):</strong> لیوان را پر از یخ کنید و دو شات لیکور ۴۳ در آن بریزید.</li><li><strong>گام ۳ (افزودن قهوه):</strong> اسپرسو را آهسته روی پشت یک قاشق پهن در لیوان بریزید و ملایم هم بزنید تا لایه‌لایه دیده شود.</li><li><strong>گام ۴ (تزئین):</strong> روی آن خامه‌ی زده‌شده بگذارید و با چند دانه‌ی قهوه‌ی شکلاتی تزئین کنید.</li></ul>","kind":"item","description":"قهوه با براندی، ویسکی، آنیسِت یا رام؛ نسخه‌ی آمریکایی با رام، تریپل‌سک و لیکور قهوه ساخته و با قهوه و خامه‌ی زده‌شده کامل می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"اسپانیا","caffeineLevel":0,"equipment":["لیوان کوکتل","قاشق پهن"],"ingredients":[{"amount":"۲","unit":"شات (حدود ۹۰ میلی‌لیتر)","name":"اسپرسو"},{"amount":"۲","unit":"شات (حدود ۹۰ میلی‌لیتر)","name":"لیکور ۴۳"},{"amount":"","unit":"","name":"یخ"},{"amount":"","unit":"","name":"خامه‌ی زده‌شده"},{"amount":"","unit":"","name":"دانه‌ی قهوه‌ی شکلاتی برای تزئین"}],"steps":[{"label":"اسپرسو","text":"دو شات اسپرسو بگیرید؛ هر شات حدود ۴۵ میلی‌لیتر."},{"label":"یخ و لیکور","text":"لیوان را پر از یخ کنید و دو شات لیکور ۴۳ در آن بریزید."},{"label":"افزودن قهوه","text":"اسپرسو را آهسته روی پشت یک قاشق پهن در لیوان بریزید و ملایم هم بزنید تا لایه‌لایه دیده شود."},{"label":"تزئین","text":"روی آن خامه‌ی زده‌شده بگذارید و با چند دانه‌ی قهوه‌ی شکلاتی تزئین کنید."}],"proTip":"بدون دستگاه اسپرسو می‌توان از قهوه‌ی غلیظ یا کولد برو استفاده کرد و با شیر تغلیظ‌شده، عسل یا شکر قهوه‌ای شیرین‌اش کرد.","variation":"آن را اسپرسو با لیکور ۴۳ روی یخ و نوشیدنی بعد از غذا می‌نامند.","history":"خاستگاه دقیق کاراخیو روشن نیست و کوبا هم محتمل دانسته شده است؛ روایتی عامیانه نام آن را به سربازان اسپانیایی در کوبا نسبت می‌دهد. در کاستاریکا از دهه‌ی ۱۹۵۰ تا ۱۹۷۰ نوشیدنی بعد از شام بود. در کلمبیا و ونزوئلا با براندی، در کوبا با رام و در مکزیک با مزکال یا لیکور قهوه‌ای مانند کالوا، تیا ماریا یا لیکور ۴۳ ساخته می‌شود.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Wikipedia — Liqueur coffee","https://en.wikipedia.org/wiki/Liqueur_coffee"],["Wikipedia — Carajillo","https://en.wikipedia.org/wiki/Carajillo"],["Homegrounds — Carajillo Recipe","https://www.homegrounds.co/carajillo-recipe/"]]},{"id":645,"title":"پونچ لیورنو (Ponce)","body":"<ul><li><strong>گام ۱ (پوست لیمو):</strong> یک تکه‌ی ضخیم پوست لیمو به اندازه‌ی یک سکه را در گیلاس بگذارید و روی آن شکر بریزید.</li><li><strong>گام ۲ (بخار):</strong> شکر را با بخارساز دستگاه اسپرسو نم بدهید و گیلاس را گرم کنید؛ یا کمی آب جوش بیفزایید.</li><li><strong>گام ۳ (له‌کردن):</strong> پوست لیمو و شکر را ته گیلاس له کنید.</li><li><strong>گام ۴ (رام):</strong> رام را بریزید.</li><li><strong>گام ۵ (اسپرسو):</strong> یک شات اسپرسو را مستقیم روی آن بگیرید و در صورت تمایل دارچین رنده‌شده بپاشید.</li></ul>","kind":"item","description":"اسپرسو که روی رامِ بخارداده‌شده ریخته می‌شود، اغلب با پوست لیمو.","difficulty":"","prepTime":"","totalTime":"","origin":"بندر لیورنو","caffeineLevel":0,"equipment":["گیلاس شات","بخارساز دستگاه اسپرسو"],"ingredients":[{"amount":"۱","unit":"قاشق بارمن","name":"شکر پودری"},{"amount":"حدود ۵","unit":"میلی‌لیتر","name":"آب جوش"},{"amount":"۱","unit":"تکه","name":"پوست لیمو"},{"amount":"۱۵","unit":"میلی‌لیتر","name":"رام"},{"amount":"۳۰","unit":"میلی‌لیتر","name":"اسپرسوی تازه و داغ"},{"amount":"","unit":"","name":"دارچین رنده‌شده برای تزئین"}],"steps":[{"label":"پوست لیمو","text":"یک تکه‌ی ضخیم پوست لیمو به اندازه‌ی یک سکه را در گیلاس بگذارید و روی آن شکر بریزید."},{"label":"بخار","text":"شکر را با بخارساز دستگاه اسپرسو نم بدهید و گیلاس را گرم کنید؛ یا کمی آب جوش بیفزایید."},{"label":"له‌کردن","text":"پوست لیمو و شکر را ته گیلاس له کنید."},{"label":"رام","text":"رام را بریزید."},{"label":"اسپرسو","text":"یک شات اسپرسو را مستقیم روی آن بگیرید و در صورت تمایل دارچین رنده‌شده بپاشید."}],"proTip":"","variation":"نسخه‌ی اصیل لیورنو با ساسولینو (لیکور انیسون‌دار) ساخته می‌شود. گونه‌های «نیمه‌نیمه»، «آمریکایی» و «تقویت‌شده» هم هست. در نسخه‌ای دیگر شکر و رام را با بخارساز تا جوش گرم می‌کنند و بعد ریسترتو می‌افزایند.","history":"پونچ لیورنو نوشیدنی شاخص بندر لیورنو در توسکانی است و قدمت آن را به قرن‌های هفدهم و هجدهم، یا دست‌کم قرن هجدهم، می‌رسانند. گمان می‌رود از پانچ انگلیسی گرفته شده باشد، چون در قرن هفدهم جامعه‌ی بزرگ بریتانیایی در این منطقه زندگی می‌کرد؛ مردم محلی چای را با قهوه و آکوویت را با رام عوض کردند و شکر، لیمو و دارچین ماند. کافه‌ی تاریخی «چیویل» در لیورنو (تأسیس دهه‌ی ۱۸۹۰) خانه‌ی معنوی آن شمرده می‌شود.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Difford's Guide — Livorno Punch (Ponce alla Livornese)","https://www.diffordsguide.com/cocktails/recipe/11890/livorno-punch-ponce-alla-livornese"],["Visit Tuscany — Ponce livornese","https://www.visittuscany.com/en/food/ponce-livornese-energy-character-and-passion/"]]},{"id":646,"title":"هات‌شات (Hotshot)","body":"<ul><li><strong>گام ۱ (گرم‌کردن گیلاس):</strong> گیلاس شات را از قبل گرم کنید.</li><li><strong>گام ۲ (گالیانو):</strong> ابتدا گالیانو را بریزید.</li><li><strong>گام ۳ (قهوه):</strong> قهوه‌ی داغ را آهسته روی آن بریزید.</li><li><strong>گام ۴ (خامه):</strong> در پایان خامه را با احتیاط روی قهوه بریزید تا سه لایه جدا بماند.</li></ul>","kind":"item","description":"به‌اندازه‌ی مساوی گالیانو، قهوه و خامه‌ی سنگین.","difficulty":"","prepTime":"","totalTime":"","origin":"سوئد","caffeineLevel":0,"equipment":["گیلاس شات"],"ingredients":[{"amount":"۱۵","unit":"میلی‌لیتر","name":"گالیانو"},{"amount":"۱۵","unit":"میلی‌لیتر","name":"قهوه‌ی فیلتری داغ"},{"amount":"۱۵","unit":"میلی‌لیتر","name":"خامه‌ی مایع"}],"steps":[{"label":"گرم‌کردن گیلاس","text":"گیلاس شات را از قبل گرم کنید."},{"label":"گالیانو","text":"ابتدا گالیانو را بریزید."},{"label":"قهوه","text":"قهوه‌ی داغ را آهسته روی آن بریزید."},{"label":"خامه","text":"در پایان خامه را با احتیاط روی قهوه بریزید تا سه لایه جدا بماند."}],"proTip":"","variation":"","history":"بارتندر سوئدی بوسه برگستروم آن را در ۱۹۸۷ برای مسابقه‌ی نوشیدنی‌های قهوه‌ای در استکهلم ساخت. در سوئد و فراتر از آن محبوب شد و جمعه‌ی سوم نوامبر در سوئد «روز هات‌شات» است. آن را «پاسخ سوئد به ایریش کافی» نامیده‌اند.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Difford's Guide — Hot Shot","https://www.diffordsguide.com/cocktails/recipe/986/hot-shot"]]},{"id":647,"title":"روده‌سهایمر کافه (Rüdesheimer Kaffee)","body":"<ul><li><strong>گام ۱ (شعله):</strong> براندی را همراه قند در فنجان شعله‌ور کنید.</li><li><strong>گام ۲ (هم‌زدن):</strong> حدود یک دقیقه هم بزنید تا قند حل شود.</li><li><strong>گام ۳ (قهوه):</strong> قهوه‌ی داغ را بیفزایید.</li><li><strong>گام ۴ (خامه):</strong> روی آن خامه‌ی غلیظ شیرین‌شده با وانیل بگذارید.</li><li><strong>گام ۵ (تزئین):</strong> با تراشه‌ی شکلات تزئین کنید و داغ سرو کنید.</li></ul>","kind":"item","description":"قهوه با براندی آسباخ اورالت، شکر و خامه‌ی زده‌شده.","difficulty":"","prepTime":"","totalTime":"","origin":"آلمان","caffeineLevel":0,"equipment":["فنجان مخصوص روده‌سهایمر","لیوان ایریش کافی"],"ingredients":[{"amount":"۱۲۵","unit":"میلی‌لیتر","name":"قهوه‌ی سیاه داغ و قوی"},{"amount":"۳","unit":"حبه","name":"قند"},{"amount":"۴۰","unit":"میلی‌لیتر","name":"براندی آسباخ اورالت (یا کنیاک یا آرمانیاک)"},{"amount":"","unit":"","name":"خامه‌ی زده‌شده با شکر وانیلی"},{"amount":"","unit":"","name":"تراشه‌ی شکلات تلخ"}],"steps":[{"label":"شعله","text":"براندی را همراه قند در فنجان شعله‌ور کنید."},{"label":"هم‌زدن","text":"حدود یک دقیقه هم بزنید تا قند حل شود.","meta":"۱ دقیقه"},{"label":"قهوه","text":"قهوه‌ی داغ را بیفزایید."},{"label":"خامه","text":"روی آن خامه‌ی غلیظ شیرین‌شده با وانیل بگذارید."},{"label":"تزئین","text":"با تراشه‌ی شکلات تزئین کنید و داغ سرو کنید."}],"proTip":"","variation":"اجزای آن حبه‌قند، براندی آسباخ، خامه‌ی شیرین‌شده و تراشه‌ی شکلات است.","history":"روده‌سهایمر کافه در ۱۹۵۷ در روده‌سهایم‌ام‌راین آلمان به‌دست هانس کارل آدام، آشپز تلویزیونی، ابداع شد و در قهوه‌خانه‌ها محبوب است.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Wikipedia — Liqueur coffee","https://en.wikipedia.org/wiki/Liqueur_coffee"],["Wikipedia — Rüdesheimer Kaffee","https://en.wikipedia.org/wiki/R%C3%BCdesheimer_Kaffee"]]},{"id":648,"title":"فاریزِئر (Pharisäer)","body":"<ul><li><strong>گام ۱ (قهوه):</strong> قهوه‌ی سیاه (یا دابل اسپرسو) را در فنجان یا لیوان بلند بریزید.</li><li><strong>گام ۲ (شکر و رام):</strong> شکر و رام را در آن حل کنید.</li><li><strong>گام ۳ (خامه):</strong> خامه‌ی زده‌شده را روی آن بگذارید.</li><li><strong>گام ۴ (نوشیدن):</strong> هم نزنید؛ قهوه را از میان خامه بنوشید.</li></ul>","kind":"item","description":"قهوه‌ی سیاه با دو شات رام و خامه‌ی زده‌شده.","difficulty":"","prepTime":"","totalTime":"","origin":"نوردفریزلاند، آلمان","caffeineLevel":0,"equipment":["لیوان بلند","نعلبکی"],"ingredients":[{"amount":"۱","unit":"قاشق غذاخوری","name":"شکر"},{"amount":"۲","unit":"شات","name":"رام"},{"amount":"","unit":"","name":"قهوه‌ی سیاه یا دابل اسپرسو"},{"amount":"","unit":"","name":"خامه‌ی زده‌شده"}],"steps":[{"label":"قهوه","text":"قهوه‌ی سیاه (یا دابل اسپرسو) را در فنجان یا لیوان بلند بریزید."},{"label":"شکر و رام","text":"شکر و رام را در آن حل کنید."},{"label":"خامه","text":"خامه‌ی زده‌شده را روی آن بگذارید."},{"label":"نوشیدن","text":"هم نزنید؛ قهوه را از میان خامه بنوشید."}],"proTip":"هم‌زدن توصیه نمی‌شود؛ رسم است که هم‌زننده باید دور بعدی را حساب کند.","variation":"به‌جای رام می‌توان ویسکی به کار برد.","history":"طبق روایتی، این نوشیدنی در مراسم تعمید در جزیره‌ی نوردشتراند پدید آمد: کشیش پرهیزکار حاضر بود و مهمانان پنهانی به قهوه‌شان رام ریختند و برای پوشاندن بو خامه روی آن گذاشتند؛ کشیش متوجه شد و آنان را «فریسی» (ریاکار) خواند و نام ماندگار شد. این روایت ممکن است افسانه باشد.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Tasting Table — The German Coffee Drink With A Boozy Twist","https://www.tastingtable.com/1186582/the-german-coffee-drink-with-a-boozy-twist"]]},{"id":658,"title":"بیتن کافی (Beaten Coffee)","body":"<ul><li><strong>گام ۱ (کوبیدن):</strong> قهوه‌ی فوری و شکر را با قاشق بکوبید تا خمیری کرکی و قهوه‌ای روشن شود.</li><li><strong>گام ۲ (افزودن مایع):</strong> شیر و آب داغ را بیفزایید و ادامه بدهید تا مخلوط کف کند؛ شیر قهوه را بیشتر حل می‌کند و هوا وارد آن می‌شود.</li><li><strong>گام ۳ (سرو):</strong> خمیر کف‌دار را روی شیر گرم بریزید تا کف غلیظی بسازد.</li></ul>","kind":"item","description":"قهوه‌ی فوری که با شکر کوبیده می‌شود و روی شیر گرم سرو می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"هند","caffeineLevel":0,"equipment":["قاشق"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی فوری"},{"amount":"—","unit":"","name":"شکر"},{"amount":"—","unit":"","name":"شیر گرم"}],"steps":[{"label":"کوبیدن","text":"قهوه‌ی فوری و شکر را با قاشق بکوبید تا خمیری کرکی و قهوه‌ای روشن شود."},{"label":"افزودن مایع","text":"شیر و آب داغ را بیفزایید و ادامه بدهید تا مخلوط کف کند؛ شیر قهوه را بیشتر حل می‌کند و هوا وارد آن می‌شود."},{"label":"سرو","text":"خمیر کف‌دار را روی شیر گرم بریزید تا کف غلیظی بسازد."}],"proTip":"","variation":"خمیر را می‌توان روی شیر گرم یا سرد ریخت. فراپه‌ی یونانی (۱۹۵۷) نوشیدنی مشابهی است که با تکان‌دادن دستی یا همزن شیرکف‌زن ساخته می‌شود و معمولاً سرد است.","history":"","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Wikipedia — Beaten coffee","https://en.wikipedia.org/wiki/Beaten_coffee"]]},{"id":660,"title":"کوپی آلپوکات (Kopi Alpukat)","body":"<ul><li><strong>گام ۱ (پوره):</strong> آووکادو و شیر تغلیظ‌شده را بلند کنید تا خمیری یکدست شود.</li><li><strong>گام ۲ (لیوان):</strong> پوره را با قاشق در لیوان بریزید و شربت شکلات روی آن بپاشید.</li><li><strong>گام ۳ (یخ و قهوه):</strong> یخ و در پایان قهوه را روی آن بریزید.</li></ul>","kind":"item","description":"قهوه که با میلک‌شیک آووکادو ترکیب می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"اندونزی","caffeineLevel":0,"equipment":["مخلوط‌کن","لیوان بلند"],"ingredients":[{"amount":"","unit":"","name":"آووکادو"},{"amount":"","unit":"","name":"شیر تغلیظ‌شده‌ی شیرین"},{"amount":"","unit":"","name":"شربت شکلات"},{"amount":"","unit":"","name":"قهوه‌ی تیره"},{"amount":"","unit":"","name":"یخ"}],"steps":[{"label":"پوره","text":"آووکادو و شیر تغلیظ‌شده را بلند کنید تا خمیری یکدست شود."},{"label":"لیوان","text":"پوره را با قاشق در لیوان بریزید و شربت شکلات روی آن بپاشید."},{"label":"یخ و قهوه","text":"یخ و در پایان قهوه را روی آن بریزید."}],"proTip":"لایه‌ها را هم نزنید؛ تضاد شیرینی و تلخی و گرم و سرد در هر جرعه حس می‌شود.","variation":"به‌جای شیر تغلیظ‌شده می‌توان شیر یا شربت شکر به کار برد؛ کولد برو، قهوه‌ی فوری شیرین، یخ تراشه‌ای یا یک اسکوپ بستنی هم رایج است. نسخه‌ی کاملاً بلندشده «جوس آلپوکات» نام دارد و اغلب قهوه ندارد.","history":"آووکادو در قرن هجدهم به اندونزی رسید، اما حدود ۱۹۹۷ در نوشیدنی‌های یخی جا افتاد؛ این رواج را اغلب به غرفه‌ی «اس تلر ۷۷» و نوشیدنی آووکادو، کاکل‌شاه‌بلوط و شیر تغلیظ‌شده‌اش نسبت می‌دهند. «اس آلپوکات» ساده‌تر بود و آووکادو بیشتر بافت می‌داد؛ بعدها قهوه یا شکلات به آن افزوده شد و «اس آلپوکات کوپی» پدید آمد.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Tasting Table — The Indonesian Iced Coffee That Features Blended Avocado","https://tastingtable.com/1359543/indonesia-iced-coffee-blended-avocado"]]},{"id":661,"title":"آبجوی قهوه (Coffee Beer)","body":"<ul><li><strong>گام ۱ (سرد‌کردن):</strong> بطری را سرد نگه دارید.</li><li><strong>گام ۲ (سرو):</strong> روی یخ بریزید؛ این نوشیدنی هنگام ریختن کف نمی‌کند.</li></ul>","kind":"item","description":"نوشیدنی بدون الکل از قهوه، شکر، آب، کارامل و نوشابه که روی یخ سرو می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"جومبانگ، اندونزی","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"","unit":"","name":"عصاره‌ی قهوه"},{"amount":"","unit":"","name":"شکر"},{"amount":"","unit":"","name":"آب"},{"amount":"","unit":"","name":"گاز CO2"},{"amount":"","unit":"","name":"کارامل"},{"amount":"","unit":"","name":"نوشابه"}],"steps":[{"label":"سرد‌کردن","text":"بطری را سرد نگه دارید."},{"label":"سرو","text":"روی یخ بریزید؛ این نوشیدنی هنگام ریختن کف نمی‌کند."}],"proTip":"با وجود واژه‌ی «بیر» در نام، الکل ندارد و در بطری‌های سبز تیره شبیه بطری آبجو عرضه می‌شود.","variation":"نسخه‌ای هم با عصاره‌ی کورکوما (تماولاک) به‌جای عصاره‌ی قهوه ساخته می‌شود.","history":"این نوشیدنی ساخت شرکت «پی‌تی تیرتا آگونگ» در نگورو، جومبانگ جاوه‌ی شرقی است و مردم محلی آن را «سی‌بی نگورو» می‌نامند. نخست فقط ساکنان جومبانگ می‌شناختندش؛ مهاجرانی که در وارونگ‌های محلی غذا می‌خوردند آن را پسندیدند و رواجش دادند، تا به جاکارتا رسید و کافه‌ها به سبک کافه سرو کردند.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Orami — Coffee Beer","https://www.orami.co.id/magazine/coffee-beer"]]},{"id":662,"title":"کافی میلک (Coffee Milk)","body":"<ul><li><strong>گام ۱ (شیر):</strong> شیر را در لیوان بریزید.</li><li><strong>گام ۲ (شربت):</strong> شربت قهوه را بیفزایید؛ برای شیرینی کمتر مقدار آن را کم کنید.</li><li><strong>گام ۳ (هم‌زدن):</strong> هم بزنید و بنوشید.</li></ul>","kind":"item","description":"شیر مخلوط‌شده با شربت قهوه‌ی شیرین؛ نوشیدنی رسمی ایالت رود آیلند.","difficulty":"","prepTime":"","totalTime":"","origin":"رود آیلند، آمریکا","caffeineLevel":0,"equipment":["لیوان"],"ingredients":[{"amount":"۲۴۰","unit":"میلی‌لیتر","name":"شیر"},{"amount":"۲","unit":"قاشق غذاخوری","name":"شربت قهوه‌ی شیرین"}],"steps":[{"label":"شیر","text":"شیر را در لیوان بریزید."},{"label":"شربت","text":"شربت قهوه را بیفزایید؛ برای شیرینی کمتر مقدار آن را کم کنید."},{"label":"هم‌زدن","text":"هم بزنید و بنوشید."}],"proTip":"شربت قهوه را می‌توان با دم‌کردن قهوه و افزودن شکر، یا با گذراندن آب داغ و شکر از تفاله‌ی قهوه ساخت. شیر ۲ درصد چربی رایج‌ترین انتخاب است.","variation":"«کافی کابینت» شیک بستنی قهوه با شربت قهوه و شیر است که بیشتر در رود آیلند و جنوب‌شرقی ماساچوست دیده می‌شود.","history":"خاستگاه دقیق کافی میلک روشن نیست، اما آن را به مهاجران ایتالیایی پراویدنس در رود آیلند و شیوه‌ی نوشیدن قهوه‌ی شیرین با شیر نسبت می‌دهند. در اوایل قرن بیستم در رستوران‌ها و فواره‌های نوشابه پدید آمد؛ گفته می‌شود مسئول یکی از آنها نخستین شربت را از تفاله‌ی باقی‌مانده ساخت. در دهه‌ی ۱۹۳۰ پیشخوان داروخانه‌ها آن را برای کودکان و نوجوانان سرو می‌کردند. «دی. آبلسن و پسر» در ۱۹۲۶ نخستین بطری شربت قهوه را فروختند و بعدها اتوکرت در دهه‌ی ۱۹۹۰ بازار را در دست گرفت. مجلس عمومی رود آیلند در ۱۹۹۳ آن را بر لیموناد دل ترجیح داد و در ۲۹ ژوئیه‌ی ۱۹۹۳ نوشیدنی رسمی ایالت شد.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Wikipedia — Coffee milk","https://en.wikipedia.org/wiki/Coffee_milk"],["The Manual — What Is Coffee Milk","https://themanual.com/food-and-drink/what-is-coffee-milk"]]},{"id":664,"title":"قهوه‌ی یزدی (روزه)","body":"<ul><li><strong>گام ۱ (آسیاب و برشته‌کردن):</strong> دانه‌ها را برشته و آسیاب کنید.</li><li><strong>گام ۲ (جوشاندن):</strong> پودر را در دیگ مسی بزرگ در آب حل کنید و شدید بجوشانید؛ سپس با هم‌زدن مداوم، که سرریز نشود، بگذارید آرام بجوشد.</li><li><strong>گام ۳ (زغال و صاف‌کردن):</strong> زغال داغ بیندازید و قهوه را از ابریشم صاف کنید تا ناخالصی‌ها جدا شود.</li><li><strong>گام ۴ (شیرین‌کردن):</strong> شکر بیفزایید و تا رسیدن به غلظت دلخواه بگذارید بجوشد.</li><li><strong>گام ۵ (عطر):</strong> درست پیش از سرو گلاب و هل آسیاب‌شده را در آن بریزید.</li></ul>","kind":"item","description":"قهوه‌ی برشته که ساعت‌ها با گلاب، هل و شکر جوشانده و از ابریشم صاف می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"ایران (یزد)","caffeineLevel":0,"equipment":["آسیاب سنگی","دیگ مسی بزرگ","ابریشم برای صاف‌کردن","فنجان‌های کوچک"],"ingredients":[{"amount":"","unit":"","name":"قهوه‌ی برشته و آسیاب‌شده"},{"amount":"","unit":"","name":"آب"},{"amount":"","unit":"","name":"زغال داغ"},{"amount":"","unit":"","name":"شکر"},{"amount":"","unit":"","name":"گلاب"},{"amount":"","unit":"","name":"هل آسیاب‌شده"}],"steps":[{"label":"آسیاب و برشته‌کردن","text":"دانه‌ها را برشته و آسیاب کنید."},{"label":"جوشاندن","text":"پودر را در دیگ مسی بزرگ در آب حل کنید و شدید بجوشانید؛ سپس با هم‌زدن مداوم، که سرریز نشود، بگذارید آرام بجوشد.","meta":"۴ تا ۶ ساعت"},{"label":"زغال و صاف‌کردن","text":"زغال داغ بیندازید و قهوه را از ابریشم صاف کنید تا ناخالصی‌ها جدا شود."},{"label":"شیرین‌کردن","text":"شکر بیفزایید و تا رسیدن به غلظت دلخواه بگذارید بجوشد."},{"label":"عطر","text":"درست پیش از سرو گلاب و هل آسیاب‌شده را در آن بریزید."}],"proTip":"در یزد این قهوه در تکیه‌ها و حسینیه‌ها در ایام محرم سرو می‌شود و حسینیه‌ی امام حسینی اصیل‌ترین تهیه‌ی آن شمرده می‌شود.","variation":"«قهوه‌ی ترحیم» شبیه قهوه‌ی ترکی است و با گلاب و نبات معطر می‌شود. در جهان عرب قهوه با زنجبیل، دارچین و هل برشته می‌شود و معمولاً بدون شکر است.","history":"قهوه‌ی یزدی، که قهوه‌ی روضه‌ای و قهوه‌ی عزاداری هم نامیده می‌شود، دست‌کم از دوره‌ی قاجار برای عزاداران یزد سرو می‌شد. روایت شفاهی آن را به دوره‌ی صفوی می‌رساند، اما کهن‌ترین سند مکتوب وقف‌نامه‌ی ۱۸۳۲ میلادی حسینیه‌ی امام حسینی است. پژوهشگری ریشه‌ی زرتشتی برای آن احتمال داده است. در ژوئیه‌ی ۲۰۱۹ در فهرست میراث ناملموس ملی ایران ثبت شد.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Wikipedia — Yazdi coffee","https://en.wikipedia.org/wiki/Yazdi_coffee"]]},{"id":665,"title":"کافه تروپیرو (Café Tropeiro)","body":"<ul><li><strong>گام ۱ (جوشاندن):</strong> پودر قهوه را با آب بجوشانید تا دم بکشد.</li><li><strong>گام ۲ (ته‌نشین‌کردن):</strong> با کمک زغال گداخته پودر را ته‌نشین کنید.</li><li><strong>گام ۳ (سرو):</strong> قهوه‌ی زلال‌شده را جدا کنید و سرو کنید.</li></ul>","kind":"item","description":"پودر قهوه که با آب جوشانده و بعد ته‌نشین می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"برزیل","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"—","unit":"","name":"پودر قهوه"},{"amount":"—","unit":"","name":"آب"}],"steps":[{"label":"جوشاندن","text":"پودر قهوه را با آب بجوشانید تا دم بکشد.","meta":""},{"label":"ته‌نشین‌کردن","text":"با کمک زغال گداخته پودر را ته‌نشین کنید.","meta":""},{"label":"سرو","text":"قهوه‌ی زلال‌شده را جدا کنید و سرو کنید.","meta":""}],"proTip":"","variation":"","history":"قهوه‌ی تروپیرو از آشپزی سنتی «تروپیرو»ها در برزیل است و تروپیروها آن را در قرن‌های هفدهم و هجدهم رایج کردند.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":667,"title":"دبل‌دبل (Double-Double)","body":"<ul><li><strong>گام ۱ (دم‌کردن):</strong> قهوه‌ی دریپ را آماده کنید.</li><li><strong>گام ۲ (افزودن):</strong> دو خامه و دو شکر به فنجان اضافه کنید.</li><li><strong>گام ۳ (هم‌زدن):</strong> نوشیدنی را هم بزنید و سرو کنید.</li></ul>","kind":"item","description":"قهوه‌ی دریپ تیم هورتنز با دو خامه و دو شکر.","difficulty":"","prepTime":"","totalTime":"","origin":"کانادا","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی دریپ"},{"amount":"۲","unit":"","name":"خامه"},{"amount":"۲","unit":"","name":"شکر"}],"steps":[{"label":"دم‌کردن","text":"قهوه‌ی دریپ را آماده کنید.","meta":""},{"label":"افزودن","text":"دو خامه و دو شکر به فنجان اضافه کنید.","meta":""},{"label":"هم‌زدن","text":"نوشیدنی را هم بزنید و سرو کنید.","meta":""}],"proTip":"","variation":"نسخه‌ها: ریگولار، تریپل‌تریپل، فور‌بای‌فور و «وین گرتزکی» (شوخی).","history":"«دبل‌دبل» اصطلاحی کاملاً کانادایی و علامت ثبت‌شده‌ی تیم هورتنز است.","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":669,"title":"کافه کام شیرینیو (Café com Cheirinho)","body":"<ul><li><strong>گام ۱ (دم‌کردن):</strong> قهوه را آماده کنید.</li><li><strong>گام ۲ (افزودن):</strong> شراب یا براندی را به قهوه اضافه کنید.</li><li><strong>گام ۳ (سرو):</strong> پس از شام سرو کنید.</li></ul>","kind":"item","description":"قهوه که معمولاً با شراب یا براندی ساخته می‌شود و بعد از شام نوشیده می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"پرتغال","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"—","unit":"","name":"قهوه"},{"amount":"—","unit":"","name":"شراب یا براندی"}],"steps":[{"label":"دم‌کردن","text":"قهوه را آماده کنید.","meta":""},{"label":"افزودن","text":"شراب یا براندی را به قهوه اضافه کنید.","meta":""},{"label":"سرو","text":"پس از شام سرو کنید.","meta":""}],"proTip":"","variation":"","history":"این نوشیدنی از پرتغال آمده و در گروه قهوه‌های همراه با مشروب جای دارد؛ آن را پس از شام و به‌عنوان هاضم می‌نوشند.","src":[["Wikipedia — Liqueur coffee","https://en.wikipedia.org/wiki/Liqueur_coffee"]]},{"id":670,"title":"کافه کالوا (Café Calva)","body":"<ul><li><strong>گام ۱ (قهوه):</strong> قهوه را به روش دلخواه دم کنید.</li><li><strong>گام ۲ (روش اول):</strong> کالوادوس را مستقیم به قهوه اضافه کنید.</li><li><strong>گام ۳ (روش دوم):</strong> کالوادوس را روی حبه‌قند بریزید و قند را با قهوه بنوشید.</li><li><strong>گام ۴ (روش سوم):</strong> پس از نوشیدن قهوه، ته فنجان را با کالوادوس آبکشی کنید.</li></ul>","kind":"item","description":"قهوه با کالوادوس؛ کالوادوس به قهوه افزوده می‌شود، روی حبه‌قند می‌ریزند یا ظرف را با آن آبکشی می‌کنند.","difficulty":"","prepTime":"","totalTime":"","origin":"نرماندی، فرانسه","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"—","unit":"","name":"قهوه"},{"amount":"—","unit":"","name":"کالوادوس"}],"steps":[{"label":"قهوه","text":"قهوه را به روش دلخواه دم کنید.","meta":""},{"label":"روش اول","text":"کالوادوس را مستقیم به قهوه اضافه کنید.","meta":""},{"label":"روش دوم","text":"کالوادوس را روی حبه‌قند بریزید و قند را با قهوه بنوشید.","meta":""},{"label":"روش سوم","text":"پس از نوشیدن قهوه، ته فنجان را با کالوادوس آبکشی کنید.","meta":""}],"proTip":"","variation":"سه روش مصرف: افزودن کالوادوس به قهوه، خیساندن حبه‌قند در آن، یا آبکشی فنجان پس از نوشیدن.","history":"","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":676,"title":"قهوه‌ی فیلتر هندی (Filter Kaapi)","body":"<ul><li><strong>گام ۱ (پرس):</strong> مخلوط قهوه و کاسنی را در فنجان بالایی فیلتر بریزید و با دیسک فشار دهید.</li><li><strong>گام ۲ (آب):</strong> آب جوش را روی دیسک و قهوه بریزید و درِ فیلتر را ببندید تا دم بکشد.</li><li><strong>گام ۳ (ترکیب):</strong> دم‌کرده را با شیر داغ و در صورت تمایل شکر ترکیب کنید.</li><li><strong>گام ۴ (کف):</strong> قهوه را بین لیوان استیل (tumbler) و بشقابک «دابرا» جابه‌جا کنید تا خنک شود و کف کند.</li></ul>","kind":"item","description":"شیر داغ و شکر با دم‌کرده‌ی قهوه و کاسنی که در فیلتر سنتی هندی چکانده می‌شود؛ «داغ، قوی، شیرین و با کف».","difficulty":"","prepTime":"","totalTime":"","origin":"جنوب هند","caffeineLevel":0,"equipment":["فیلتر استیل دوتکه با دیسک پرس و درپوش","لیوان استیل","بشقابک دابرا"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی آسیاب‌شده‌ی برشته‌ی تیره (۸۰ تا ۹۰٪ مخلوط)"},{"amount":"—","unit":"","name":"کاسنی (۱۰ تا ۲۰٪ مخلوط)"},{"amount":"—","unit":"","name":"شیر داغ"},{"amount":"—","unit":"","name":"شکر (در گذشته نیشکر خام یا عسل)"}],"steps":[{"label":"پرس","text":"مخلوط قهوه و کاسنی را در فنجان بالایی فیلتر بریزید و با دیسک فشار دهید."},{"label":"آب","text":"آب جوش را روی دیسک و قهوه بریزید و درِ فیلتر را ببندید تا دم بکشد."},{"label":"ترکیب","text":"دم‌کرده را با شیر داغ و در صورت تمایل شکر ترکیب کنید."},{"label":"کف","text":"قهوه را بین لیوان استیل (tumbler) و بشقابک «دابرا» جابه‌جا کنید تا خنک شود و کف کند."}],"proTip":"قهوه‌ی برشته‌ی تیره با کاسنی (۱۰ تا ۲۰ درصد) بهترین طعم را می‌دهد؛ جابه‌جایی بین لیوان و دابرا هم قهوه را خنک و هم کف‌دار می‌کند.","variation":"","history":"شکر از اواسط قرن بیستم جای شیرین‌کننده‌های سنتی را گرفت. صفحه یادآور می‌شود طبق افسانه صوفی بابا بودان هفت دانه‌ی خام را از مکه قاچاق و در تپه‌های چیکمگالور کاشت.","src":[["Wikipedia — Indian filter coffee","https://en.wikipedia.org/wiki/Indian_filter_coffee"]]},{"id":677,"title":"کافه‌اولِ نیواورلئان (New Orleans Café au Lait)","body":"<ul><li><strong>گام ۱ (داغ‌کردن شیر):</strong> شیر را روی حرارت تا نزدیک جوش گرم کنید.</li><li><strong>گام ۲ (دم‌کردن):</strong> قهوه‌ی مخلوط با کاسنی را دم کنید.</li><li><strong>گام ۳ (ترکیب):</strong> قهوه و شیر داغ‌شده را با هم مخلوط کنید.</li><li><strong>گام ۴ (سرو):</strong> با بنیه‌ی پاشیده‌شده با پودر قند سرو کنید.</li></ul>","kind":"item","description":"قهوه‌ی مخلوط با کاسنی و شیر جوشانده‌شده که به‌طور سنتی با بنیه (beignet) سرو می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"نیواورلئان","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"—","unit":"","name":"قهوه با کاسنی"},{"amount":"—","unit":"","name":"شیر جوشانده‌شده"}],"steps":[{"label":"داغ‌کردن شیر","text":"شیر را روی حرارت تا نزدیک جوش گرم کنید.","meta":""},{"label":"دم‌کردن","text":"قهوه‌ی مخلوط با کاسنی را دم کنید.","meta":""},{"label":"ترکیب","text":"قهوه و شیر داغ‌شده را با هم مخلوط کنید.","meta":""},{"label":"سرو","text":"با بنیه‌ی پاشیده‌شده با پودر قند سرو کنید.","meta":""}],"proTip":"بنیه‌ی پودرقندی تلخی کاسنی را تعدیل می‌کند.","variation":"","history":"کاسنی در جنگ داخلی آمریکا و در پی محاصره‌ی دریایی بندر نیواورلئان در لوئیزیانا رایج شد. گفته می‌شود فرانسوی‌ها طعم قهوه با کاسنی را در جنگ داخلی خودشان پسندیدند و آکادیایی‌ها آن را به لوئیزیانا بردند.","src":[["Wikipedia — Caf%C3%A9 au lait","https://en.wikipedia.org/wiki/Caf%C3%A9_au_lait"]]},{"id":678,"title":"کافه میستو (Caffè Misto)","body":"<ul><li><strong>گام ۱ (دم‌کردن):</strong> قهوه را با فرنچ‌پرس دم کنید.</li><li><strong>گام ۲ (کف‌دادن):</strong> شیر را کف‌دار کنید.</li><li><strong>گام ۳ (ترکیب):</strong> قهوه و شیر را به نسبت ۱ به ۱ ترکیب کنید.</li></ul>","kind":"item","description":"نام استارباکس برای کافه‌اوله: قهوه‌ی فرنچ‌پرس و شیر کف‌دار به نسبت ۱ به ۱.","difficulty":"","prepTime":"","totalTime":"","origin":"","caffeineLevel":0,"equipment":[],"ingredients":[{"amount":"۱","unit":"بخش","name":"قهوه‌ی فرنچ‌پرس"},{"amount":"۱","unit":"بخش","name":"شیر کف‌دار"}],"steps":[{"label":"دم‌کردن","text":"قهوه را با فرنچ‌پرس دم کنید.","meta":""},{"label":"کف‌دادن","text":"شیر را کف‌دار کنید.","meta":""},{"label":"ترکیب","text":"قهوه و شیر را به نسبت ۱ به ۱ ترکیب کنید.","meta":""}],"proTip":"","variation":"","history":"استارباکس کافه‌اوله را با نام «کافه میستو» عرضه می‌کند.","src":[["Wikipedia — Caf%C3%A9 au lait","https://en.wikipedia.org/wiki/Caf%C3%A9_au_lait"]]}],"hero":"assets/images/traditional.svg"},{"id":"modern","icon":"future","title":"مدرن، عملکردی و عجیب","items":[{"id":112,"title":"دالگونا (Dalgona Coffee – قهوه کف‌دار کره‌ای)","body":"<ul><li><strong>گام ۱ (مواد):</strong> مقادیر برابر قهوه‌ی فوری، شکر و آب داغ را در کاسه بریزید.</li><li><strong>گام ۲ (زدن):</strong> مخلوط را بزنید تا غلیظ و کرمی شود.</li><li><strong>گام ۳ (شیر):</strong> شیر سرد یا گرم را در لیوان بریزید.</li><li><strong>گام ۴ (سرو):</strong> مخلوط کف‌دار را با قاشق روی شیر بگذارید و در صورت دلخواه پودر قهوه، کاکائو یا عسل اضافه کنید.</li></ul>","kind":"item","description":"دالگونا از زدن مقادیر برابر قهوه‌ی فوری، شکر و آب داغ تا کرمی‌شدن ساخته می‌شود و روی شیر سرد یا گرم می‌رود.","difficulty":"","prepTime":"","totalTime":"","origin":"ماکائو (رواج: کره‌ی جنوبی)","caffeineLevel":0,"equipment":["همزن برقی دستی","کاسه"],"ingredients":[{"amount":"۱","unit":"بخش","name":"قهوه‌ی فوری"},{"amount":"۱","unit":"بخش","name":"شکر"},{"amount":"۱","unit":"بخش","name":"آب داغ"},{"amount":"","unit":"","name":"شیر سرد یا گرم"}],"steps":[{"label":"مواد","text":"مقادیر برابر قهوه‌ی فوری، شکر و آب داغ را در کاسه بریزید.","meta":""},{"label":"زدن","text":"مخلوط را بزنید تا غلیظ و کرمی شود.","meta":""},{"label":"شیر","text":"شیر سرد یا گرم را در لیوان بریزید.","meta":""},{"label":"سرو","text":"مخلوط کف‌دار را با قاشق روی شیر بگذارید و در صورت دلخواه پودر قهوه، کاکائو یا عسل اضافه کنید.","meta":""}],"proTip":"فقط قهوه‌ی فوری استفاده کنید؛ دانه‌ی آسیاب‌شده به دلیل روش خشک‌شدن، کف غلیظ نمی‌دهد.","variation":"در راجستان هند «فنتی هوئی کافی» نام دارد؛ تفاوت اصلی این است که شیر روی مخلوط زده‌شده ریخته می‌شود، نه برعکس.","history":"خاستگاه نوشیدنی را ماکائو (۱۹۹۷) می‌دانند؛ لئونگ کام هون می‌گوید آن را برای زوج گردشگری ساخته است. در کره‌ی جنوبی در دوران کووید-۱۹ رواج یافت و در ۲۰۲۰ با نام «دالگونا» شناخته شد؛ این نام را بازیگر جونگ ایل‌وو پس از سفارش آن در ماکائو در ژانویه ۲۰۲۰ در یک برنامه‌ی تلویزیونی رواج داد. همچنین گفته شده که ریشه‌ای در راجستان هند دارد.","src":[["Wikipedia — Dalgona coffee","https://en.wikipedia.org/wiki/Dalgona_coffee"]]},{"id":113,"title":"قهوه ضدگلوله (Bulletproof Coffee)","body":"<ul><li><strong>گام ۱ (ترکیب):</strong> آسپری دستور نوشیدنی قهوه‌ی کره‌دار خود را در ۲۰۰۹ در وبلاگش منتشر کرد.</li></ul>","kind":"item","description":"قهوه‌ی کره‌ای: دستور قهوه‌ی کره‌دار را دیو آسپری پس از سفر به تبت و نوشیدن چای کره‌ی یاک ساخت.","difficulty":"","prepTime":"","totalTime":"","origin":"آمریکا","caffeineLevel":0,"equipment":["بلندر"],"ingredients":[{"amount":"—","unit":"","name":"قهوه"},{"amount":"—","unit":"","name":"کره"}],"steps":[{"label":"ترکیب","text":"آسپری دستور نوشیدنی قهوه‌ی کره‌دار خود را در ۲۰۰۹ در وبلاگش منتشر کرد."}],"proTip":"ادعاهای آسپری (مثل افزایش بیش از ۲۰ امتیازی IQ) مبنای علمی ندارد و متخصصان تغذیه آن را فقط «هیجان کافئین» می‌دانند.","variation":"","history":"آسپری این دستور را پس از سفر به تبت و نوشیدن چای کره‌ی یاک ساخت و در ۲۰۰۹ در وبلاگش منتشر کرد. رژیم «بولت‌پروف» مصرف گوشت و کره‌ی گاو چرا‌کرده را ترویج می‌کند.","src":[["Wikipedia — Bulletproof Coffee","https://en.wikipedia.org/wiki/Bulletproof_Coffee"]]},{"id":114,"title":"ردآی (Red Eye – قهوه با یک شات اسپرسو اضافه)","body":"<ul><li><strong>گام ۱ (دم‌کردن):</strong> قهوه را با روش دلخواه (کمکس، وی۶۰ یا فرنچ‌پرس) دم کنید.</li><li><strong>گام ۲ (اسپرسو):</strong> همزمان یک شات اسپرسو بگیرید.</li><li><strong>گام ۳ (ریختن):</strong> قهوه را در لیوان بلند بریزید و جا برای اسپرسو بگذارید.</li><li><strong>گام ۴ (افزودن):</strong> اسپرسو را آرام روی قهوه بریزید.</li><li><strong>گام ۵ (سرو):</strong> در صورت دلخواه شیرین کنید، کمی هم بزنید و بنوشید.</li></ul>","kind":"item","description":"ردآی قهوه‌ی دم‌شده با یک شات اسپرسو است؛ کافئین آن حدود ۱۵۸ میلی‌گرم برآورد می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"آمریکا","caffeineLevel":0,"equipment":["قهوه‌ساز قطره‌ای","دستگاه اسپرسو"],"ingredients":[{"amount":"۱","unit":"فنجان (۲۴۰ میلی‌لیتر)","name":"قهوه‌ی دم‌شده"},{"amount":"۱","unit":"شات (۳۰ میلی‌لیتر)","name":"اسپرسو"}],"steps":[{"label":"دم‌کردن","text":"قهوه را با روش دلخواه (کمکس، وی۶۰ یا فرنچ‌پرس) دم کنید.","meta":""},{"label":"اسپرسو","text":"همزمان یک شات اسپرسو بگیرید.","meta":""},{"label":"ریختن","text":"قهوه را در لیوان بلند بریزید و جا برای اسپرسو بگذارید.","meta":""},{"label":"افزودن","text":"اسپرسو را آرام روی قهوه بریزید.","meta":""},{"label":"سرو","text":"در صورت دلخواه شیرین کنید، کمی هم بزنید و بنوشید.","meta":"حدود ۵ دقیقه"}],"proTip":"بیشتر نوشیدنی‌های «آی» با برشته‌ی متوسط ساخته می‌شوند. اگر به کافئین حساسید از ردآی شروع کنید.","variation":"بلک‌آی: دو شات؛ ددآی: سه شات.","history":"می‌گویند نام آن از جنب‌وجوی لازم برای بیدار ماندن در پرواز شبانه‌ی «red eye» از ساحل غربی به نیویورک آمده است.","src":[["Your Dream Coffee — Red Eye, Black Eye, Dead Eye","https://yourdreamcoffee.com/red-eye-coffee/"],["Coffee Wiki (Fandom) — Red eye","https://coffee.fandom.com/wiki/Red_eye"]]},{"id":115,"title":"بلک‌آی (Black Eye – قهوه با دو شات اسپرسو)","body":"<ul><li><strong>گام ۱ (دم‌کردن):</strong> قهوه را با روش دلخواه دم کنید.</li><li><strong>گام ۲ (اسپرسو):</strong> دو شات اسپرسو بگیرید.</li><li><strong>گام ۳ (ریختن):</strong> قهوه را در لیوان بلند بریزید و اسپرسو را آرام روی آن بیفزایید.</li><li><strong>گام ۴ (سرو):</strong> در صورت دلخواه شیرین کنید و بنوشید.</li></ul>","kind":"item","description":"بلک‌آی قهوه‌ی دم‌شده با دو شات اسپرسو است؛ کافئین آن حدود ۲۲۱ میلی‌گرم برآورد می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"","caffeineLevel":0,"equipment":["قهوه‌ساز قطره‌ای","دستگاه اسپرسو"],"ingredients":[{"amount":"۱","unit":"فنجان (۲۴۰ میلی‌لیتر)","name":"قهوه‌ی دم‌شده"},{"amount":"۲","unit":"شات","name":"اسپرسو"}],"steps":[{"label":"دم‌کردن","text":"قهوه را با روش دلخواه دم کنید.","meta":""},{"label":"اسپرسو","text":"دو شات اسپرسو بگیرید.","meta":""},{"label":"ریختن","text":"قهوه را در لیوان بلند بریزید و اسپرسو را آرام روی آن بیفزایید.","meta":""},{"label":"سرو","text":"در صورت دلخواه شیرین کنید و بنوشید.","meta":"حدود ۵ دقیقه"}],"proTip":"","variation":"نسخه‌ی شیری: قهوه و شیر داغ را به نسبت مساوی ترکیب و به‌دلخواه شیرین کنید.","history":"نام آن به حلقه‌ی سیاهی اشاره دارد که پس از ریختن شات‌ها در قهوه پدید می‌آید.","src":[["Your Dream Coffee — Red Eye, Black Eye, Dead Eye","https://yourdreamcoffee.com/red-eye-coffee/"],["Coffee Wiki (Fandom) — Red eye","https://coffee.fandom.com/wiki/Red_eye"],["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":116,"title":"ددآی (Dead Eye – قهوه با سه شات اسپرسو)","body":"<ul><li><strong>گام ۱ (دم‌کردن):</strong> قهوه را با روش دلخواه دم کنید.</li><li><strong>گام ۲ (اسپرسو):</strong> سه شات اسپرسو بگیرید.</li><li><strong>گام ۳ (ریختن):</strong> قهوه را در لیوان بلند بریزید و اسپرسو را آرام روی آن بیفزایید.</li><li><strong>گام ۴ (سرو):</strong> در صورت دلخواه شیرین کنید و بنوشید.</li></ul>","kind":"item","description":"ددآی قهوه‌ی دم‌شده با سه شات اسپرسو است؛ کافئین آن حدود ۲۸۴ میلی‌گرم برآورد می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"","caffeineLevel":0,"equipment":["قهوه‌ساز قطره‌ای","دستگاه اسپرسو"],"ingredients":[{"amount":"۱","unit":"فنجان (۲۴۰ میلی‌لیتر)","name":"قهوه‌ی دم‌شده"},{"amount":"۳","unit":"شات","name":"اسپرسو"}],"steps":[{"label":"دم‌کردن","text":"قهوه را با روش دلخواه دم کنید.","meta":""},{"label":"اسپرسو","text":"سه شات اسپرسو بگیرید.","meta":""},{"label":"ریختن","text":"قهوه را در لیوان بلند بریزید و اسپرسو را آرام روی آن بیفزایید.","meta":""},{"label":"سرو","text":"در صورت دلخواه شیرین کنید و بنوشید.","meta":"حدود ۵ دقیقه"}],"proTip":"طعم آن بسیار قوی است؛ شیر، شکر یا شربت می‌تواند آن را ملایم کند.","variation":"","history":"با نام «triple red eye» هم شناخته می‌شود و در استارباکس با نام «Green Eye» فروخته می‌شود. منشأ نام را توضیح نمی‌دهد.","src":[["Your Dream Coffee — Red Eye, Black Eye, Dead Eye","https://yourdreamcoffee.com/red-eye-coffee/"],["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":117,"title":"قهوه فوری ساده (Instant Black)","body":"<ul><li><strong>گام ۱ (پودر):</strong> مقداری پودر قهوه‌ی فوری را در فنجان بریزید.</li><li><strong>گام ۲ (آب):</strong> آب داغ اضافه کنید؛ برای قهوه‌ی سرد از آب سرد یا شیر استفاده می‌شود.</li><li><strong>گام ۳ (هم‌زدن):</strong> هم بزنید تا حل شود.</li><li><strong>گام ۴ (تنظیم):</strong> شیر و شکر را در صورت تمایل اضافه کنید؛ غلظت را با نسبت پودر به مایع تنظیم کنید.</li></ul>","kind":"item","description":"قهوه‌ی فوری با افزودن آب داغ (یا شیر یا آب سرد) آماده می‌شود و قدرتش با نسبت پودر به مایع تنظیم می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"","caffeineLevel":0,"equipment":["کتری"],"ingredients":[{"amount":"—","unit":"","name":"پودر قهوه‌ی فوری"},{"amount":"—","unit":"","name":"آب داغ، شیر یا آب سرد؛ شیر و شکر در صورت تمایل"}],"steps":[{"label":"پودر","text":"مقداری پودر قهوه‌ی فوری را در فنجان بریزید.","meta":""},{"label":"آب","text":"آب داغ اضافه کنید؛ برای قهوه‌ی سرد از آب سرد یا شیر استفاده می‌شود.","meta":""},{"label":"هم‌زدن","text":"هم بزنید تا حل شود.","meta":""},{"label":"تنظیم","text":"شیر و شکر را در صورت تمایل اضافه کنید؛ غلظت را با نسبت پودر به مایع تنظیم کنید.","meta":""}],"proTip":"کافئین قهوه‌ی فوری معمولاً کمتر از قهوه‌ی دم‌شده است: میانه‌ی ۶۶ میلی‌گرم هر فنجان (بازه‌ی ۲۹ تا ۱۱۷) در برابر ۱۱۲ میلی‌گرم در قهوه‌ی قطره‌ای، برای فنجان ۲۲۵ میلی‌لیتر.","variation":"در پرتغال، اسپانیا و هند اغلب با شیر داغ به‌جای آب مخلوط می‌شود؛ در کره‌ی جنوبی به‌صورت آماده با کرم‌ساز و شکر («کافی میکس») فروخته می‌شود و فراپه‌ی یونانی با آب سرد ساخته می‌شود.","history":"قهوه‌ی فوری به روش انجماد‌-خشک‌کردن یا پاشش‌خشک‌کردن تولید می‌شود. اختراع پودر قهوه‌ی محلول فوری را دیوید استرانگ در ۲۸ ژانویه ۱۸۸۹ ثبت و در ۱۸۹۰ به نام خود گرفت؛ نسبت‌دادن آن به ساتوری کاتو (۱۹۰۱) منسوخ تلقی می‌شود. نستله در ۱۹۳۸ با برند نسکافه پودری پایدارتر عرضه کرد و جورج واشنگتن روش خود را کمی بعد و در ۱۹۱۰ تجاری کرد.","src":[["Wikipedia — Instant coffee","https://en.wikipedia.org/wiki/Instant_coffee"]]},{"id":118,"title":"کنسانتره مایع (Liquid Coffee Concentrate – قهوه مایع غلیظ برای مصارف خانگی)","body":"<ul><li><strong>گام ۱ (آسیاب):</strong> قهوه را درشت آسیاب کنید.</li><li><strong>گام ۲ (خیساندن):</strong> قهوه را در آب هم‌دمای اتاق (یا آب خنک) بریزید و بخیسانید.</li><li><strong>گام ۳ (صاف‌کردن):</strong> با فیلتر کاغذی، آبکش ریز فلزی یا نمد صاف کنید.</li><li><strong>گام ۴ (رقیق‌کردن):</strong> کنسانتره را با آب یا شیر رقیق کنید.</li></ul>","kind":"item","description":"کنسانتره‌ی قهوه‌ی سرد غلیظ است که قبل از نوشیدن با آب یا شیر رقیق می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"جهانی (مدرن)","caffeineLevel":0,"equipment":["ظرف بزرگ درب‌دار","فیلتر پارچه‌ای یا کاغذی","بطری شیشه‌ای برای نگهداری"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی درشت‌آسیاب"},{"amount":"—","unit":"","name":"آب"}],"steps":[{"label":"آسیاب","text":"قهوه را درشت آسیاب کنید.","meta":""},{"label":"خیساندن","text":"قهوه را در آب هم‌دمای اتاق (یا آب خنک) بریزید و بخیسانید.","meta":"۱۲–۲۴ ساعت"},{"label":"صاف‌کردن","text":"با فیلتر کاغذی، آبکش ریز فلزی یا نمد صاف کنید.","meta":""},{"label":"رقیق‌کردن","text":"کنسانتره را با آب یا شیر رقیق کنید.","meta":""}],"proTip":"","variation":"می‌توان آن را سرد، روی یخ یا همراه یخ و موادی مثل شکلات بلند کرد، یا گرم نوشید.","history":"هلندی‌ها دم‌آوری سرد را به ژاپن بردند و در آنجا قرن‌هاست روشی سنتی است. نوع قطره‌ای آهسته را «سبک کیوتو» یا در شرق آسیا «قهوه‌ی هلندی» می‌نامند.","src":[["Wikipedia — Cold brew coffee","https://en.wikipedia.org/wiki/Cold_brew_coffee"]]}],"hero":"assets/images/modern.svg"},{"id":"unusual","icon":"unusual","title":"شگفت‌انگیز و غیرمعمول","items":[{"id":621,"title":"کافه موئی (قهوه‌ی نمکی ویتنامی – Cà Phê Muối)","body":"<ul><li><strong>گام ۱ (دم‌آوری):</strong> قهوه را از فیلتر روی مخلوط نمکی بچکانید.</li><li><strong>گام ۲ (سرو):</strong> مشتری یخ را خودش اضافه می‌کند یا بدون یخ می‌نوشد.</li></ul>","kind":"item","description":"کافه موئی قهوه‌ی نمکی شهر هوئه است: قهوه‌ی روبوستا با کمی نمک که شیرینی و تلخی را متعادل می‌کند و طعمش را به کارامل نمکی تشبیه می‌کنند.","difficulty":"","prepTime":"","totalTime":"","origin":"هوئه، ویتنام","caffeineLevel":0,"equipment":["قهوه‌ساز فیلتری"],"ingredients":[{"amount":"—","unit":"","name":"قهوه‌ی روبوستا"},{"amount":"—","unit":"","name":"مخلوط نمکی"}],"steps":[{"label":"دم‌آوری","text":"قهوه را از فیلتر روی مخلوط نمکی بچکانید."},{"label":"سرو","text":"مشتری یخ را خودش اضافه می‌کند یا بدون یخ می‌نوشد."}],"proTip":"بهترین کافه موئی هنوز در شعبه‌ی اصلی هوئه سرو می‌شود؛ آنجا می‌توانید یخ بخواهید یا نخواهید.","variation":"در بیشتر جاها آماده سرو می‌شود و برخی لبه‌ی لیوان را مثل مارگریتا نمکی می‌کنند.","history":"آن را کافه‌ی «Cà Phê Muối» در هوئه، با زوج بنیان‌گذار آقای فونگ و خانم هوانگ، ساخت. دستور آن مدتی راز نگه داشته می‌شد و تا اواخر دهه‌ی ۲۰۱۰ نوشیدنی‌های مشابه به کافه‌های همسایه و مرکز ویتنام رسید.","src":[["Vietnam Coracle — Salt Coffee: Cà Phê Muối","https://www.vietnamcoracle.com/salt-coffee-ca-phe-muoi/"]]}],"hero":"assets/images/unusual.svg"},{"id":"rare_beans","icon":"rarebeans","title":"دانه‌های نادر و گران‌قیمت","items":[{"id":625,"title":"قهوه کوپی لواک اندونزیایی (Kopi Luwak)","body":"<ul><li><strong>گام ۱ (خوردن):</strong> زباد خرمایی آسیایی میوه‌های قهوه را می‌خورد.</li><li><strong>گام ۲ (تخمیر):</strong> آنزیم‌های دستگاه گوارش پروتئین‌های دانه را تغییر می‌دهند.</li><li><strong>گام ۳ (جمع‌آوری):</strong> دانه‌ها از فضله جمع‌آوری می‌شوند.</li><li><strong>گام ۴ (شست‌وشو):</strong> دانه‌ها پاک‌سازی می‌شوند.</li><li><strong>گام ۵ (برشته‌کردن):</strong> دانه‌ها را برشته و سپس دم کنید.</li></ul>","kind":"item","description":"کوپی لواک قهوه‌ای از میوه‌های نیمه‌هضم‌شده‌ی قهوه است که زباد خرمایی آسیایی می‌خورد و دفع می‌کند و بعد جمع‌آوری می‌شود.","difficulty":"","prepTime":"","totalTime":"","origin":"اندونزی","caffeineLevel":0,"equipment":["دستگاه دم‌آوری دلخواه (پوراوور یا فرنچ‌پرس)","آسیاب قهوه"],"ingredients":[{"amount":"—","unit":"","name":"دانه‌های نیمه‌هضم‌شده‌ی قهوه (دفع زباد آسیایی)"}],"steps":[{"label":"خوردن","text":"زباد خرمایی آسیایی میوه‌های قهوه را می‌خورد.","meta":""},{"label":"تخمیر","text":"آنزیم‌های دستگاه گوارش پروتئین‌های دانه را تغییر می‌دهند.","meta":""},{"label":"جمع‌آوری","text":"دانه‌ها از فضله جمع‌آوری می‌شوند.","meta":""},{"label":"شست‌وشو","text":"دانه‌ها پاک‌سازی می‌شوند.","meta":""},{"label":"برشته‌کردن","text":"دانه‌ها را برشته و سپس دم کنید.","meta":""}],"proTip":"انجمن SCAA گزارش می‌کند «اجماع صنعت این است که طعم بدی دارد»؛ در ارزیابی کاپینگ نتیجه این بود که لواک «برای داستانش فروخته می‌شود، نه کیفیت برتر». حقوق حیوانات: زبادهای قفسی اغلب به‌زور تغذیه می‌شوند و در قفس کوچک نگه داشته می‌شوند؛ تحقیقات PETA و BBC تقلب فراوان در این صنعت یافتند.","variation":"در فیلیپین با نام‌هایی مثل کاپه موتیت و در ویتنام با نام «قهوه‌ی راسو» تولید می‌شود؛ نمونه‌ی ویتنامی حدود ۵۰۰ دلار در کیلو قیمت دارد.","history":"استعمارگران هلندی مزارع قهوه در اندونزی ساختند و دانه از یمن آوردند. در قرن نوزدهم کشاورزان جاوه‌ی مرکزی شروع به دم‌کردن و نوشیدن قهوه از دانه‌های دفع‌شده کردند. قیمت: ۱۳۰۰ دلار در کیلو برای دانه‌های وحشی و ۱۰۰ دلار برای دانه‌های پرورشی (خرده‌فروشی)؛ در ۲۰۱۰ بین ۲۲۰ و ۱۱۰۰ دلار. تولید عمدتاً در سوماترا، جاوه، بالی، سولاوسی و تیمور شرقی است.","src":[["Wikipedia — Kopi luwak","https://en.wikipedia.org/wiki/Kopi_luwak"]]},{"id":626,"title":"قهوه ژاکوبرد برزیلی (Jacu Bird Coffee)","body":"<ul><li><strong>گام ۱ (خوردن):</strong> پرنده‌ی ژاکو فقط میوه‌ی رسیده‌ی قهوه را می‌خورد.</li><li><strong>گام ۲ (جمع‌آوری):</strong> کارگران دانه‌ها را از روی زمین بین درختان جمع می‌کنند.</li><li><strong>گام ۳ (آماده‌سازی):</strong> دانه‌ها را خشک، دسته‌بندی و پوست‌گیری کنید.</li><li><strong>گام ۴ (نگهداری):</strong> در اتاق خنک نگه دارید.</li></ul>","kind":"item","description":"قهوه‌ی ژاکو از دانه‌هایی است که پرنده‌ی وحشی ژاکو پس از خوردن میوه‌ی رسیده‌ی قهوه دفع می‌کند.","difficulty":"","prepTime":"","totalTime":"","origin":"اسپیریتو سانتو، برزیل","caffeineLevel":0,"equipment":["دستگاه دم‌آوری دلخواه (پوراوور)","آسیاب قهوه"],"ingredients":[{"amount":"—","unit":"","name":"دانه‌ی قهوه‌ی ژاکو"}],"steps":[{"label":"خوردن","text":"پرنده‌ی ژاکو فقط میوه‌ی رسیده‌ی قهوه را می‌خورد.","meta":""},{"label":"جمع‌آوری","text":"کارگران دانه‌ها را از روی زمین بین درختان جمع می‌کنند.","meta":""},{"label":"آماده‌سازی","text":"دانه‌ها را خشک، دسته‌بندی و پوست‌گیری کنید.","meta":""},{"label":"نگهداری","text":"در اتاق خنک نگه دارید.","meta":""}],"proTip":"کارشناس مزرعه طعم آن را شیرین با اسیدیته‌ی خوب توصیف می‌کند.","variation":"","history":"ژاکو پرنده‌ای فازان‌مانند با پرهای سیاه و گلوی قرمز در جنگل‌های اطلس برزیل است. مزرعه‌ی Camocim (ایالت اسپیریتو سانتو، مالک هنریکه اسلوپر) آن را جمع می‌کند. ژاکو فقط جایی می‌خورد که قهوه رسیده است؛ گذر دانه از روده کوتاه است و فرایند بیوشیمیایی خاصی رخ نمی‌دهد. قیمت داخلی ۱٬۱۱۸ رئال به‌ازای هر کیلو (حدود ۱۰۰ دلار برای هر پوند) و کمتر از ۲ درصد تولید مزرعه است.","src":[["Phys.org (AFP) — Jacu bird coffee","https://phys.org/news/2023-09-rear-pheasant-brazil-coffee.html"]]},{"id":627,"title":"قهوه فیل (Elephant Coffee)","body":"<ul><li><strong>گام ۱ (خوراندن):</strong> میوه‌ی خام قهوه را کنار غذای معمول فیل‌ها می‌دهند.</li><li><strong>گام ۲ (عبور):</strong> دانه‌ها در دستگاه گوارش فیل می‌مانند.</li><li><strong>گام ۳ (جمع‌آوری):</strong> مهوت‌ها و همسرانشان دانه‌ها را از فضله برمی‌دارند؛ بسیاری از دانه‌ها جویده یا گم می‌شوند.</li><li><strong>گام ۴ (بازده):</strong> برای هر ۱ کیلوگرم فراورده حدود ۳۳ کیلوگرم میوه لازم است.</li></ul>","kind":"item","description":"قهوه‌ی فیل قهوه‌ای است که دانه‌های آن پس از عبور از دستگاه گوارش فیل جمع می‌شود؛ نمونه‌ی مشهور آن «عاج سیاه» در تایلند است.","difficulty":"","prepTime":"","totalTime":"","origin":"تایلند","caffeineLevel":0,"equipment":["دستگاه دم‌آوری دلخواه (فرنچ‌پرس یا پوراوور)","آسیاب قهوه"],"ingredients":[{"amount":"۳۳","unit":"کیلوگرم","name":"میوه‌ی خام قهوه برای هر ۱ کیلوگرم فراورده (عاج سیاه)"}],"steps":[{"label":"خوراندن","text":"میوه‌ی خام قهوه را کنار غذای معمول فیل‌ها می‌دهند.","meta":""},{"label":"عبور","text":"دانه‌ها در دستگاه گوارش فیل می‌مانند.","meta":"۱۰–۷۲ ساعت"},{"label":"جمع‌آوری","text":"مهوت‌ها و همسرانشان دانه‌ها را از فضله برمی‌دارند؛ بسیاری از دانه‌ها جویده یا گم می‌شوند.","meta":""},{"label":"بازده","text":"برای هر ۱ کیلوگرم فراورده حدود ۳۳ کیلوگرم میوه لازم است.","meta":""}],"proTip":"","variation":"","history":"نمونه‌ی مشهور آن «عاج سیاه» است؛ بلیک دینکین کانادایی پس از ۹ سال آزمایش در ۲۰۱۲ با تولید اولیه‌ی ۱۵۰ کیلوگرم به کیفیت رضایت‌بخش رسید و تولید بعدها از شمال تایلند به استان سورین رفت.","src":[["Wikipedia — Black Ivory coffee","https://en.wikipedia.org/wiki/Black_Ivory_coffee"]]},{"id":628,"title":"قهوه عاج سیاه تایلندی (Black Ivory Coffee)","body":"<ul><li><strong>گام ۱ (خوراندن):</strong> میوه‌ی خام قهوه را کنار برنج و موز به فیل‌ها می‌دهند.</li><li><strong>گام ۲ (عبور):</strong> دانه‌ها در دستگاه گوارش فیل می‌مانند.</li><li><strong>گام ۳ (جمع‌آوری):</strong> مهوت‌ها و همسرانشان دانه‌ها را از فضله برمی‌دارند؛ بسیاری از دانه‌ها جویده یا گم می‌شوند.</li><li><strong>گام ۴ (بازده):</strong> برای هر ۱ کیلوگرم فراورده حدود ۳۳ کیلوگرم میوه لازم است.</li></ul>","kind":"item","description":"عاج سیاه (Black Ivory) قهوه‌ای است که فیل‌ها در تایلند با خوردن میوه‌ی قهوه تولید می‌کنند.","difficulty":"","prepTime":"","totalTime":"","origin":"تایلند","caffeineLevel":0,"equipment":["دستگاه دم‌آوری دلخواه (پوراوور)","آسیاب قهوه"],"ingredients":[{"amount":"۳۳","unit":"کیلوگرم","name":"میوه‌ی خام قهوه برای هر ۱ کیلوگرم فراورده"}],"steps":[{"label":"خوراندن","text":"میوه‌ی خام قهوه را کنار برنج و موز به فیل‌ها می‌دهند.","meta":""},{"label":"عبور","text":"دانه‌ها در دستگاه گوارش فیل می‌مانند.","meta":"۱۰–۷۲ ساعت"},{"label":"جمع‌آوری","text":"مهوت‌ها و همسرانشان دانه‌ها را از فضله برمی‌دارند؛ بسیاری از دانه‌ها جویده یا گم می‌شوند.","meta":""},{"label":"بازده","text":"برای هر ۱ کیلوگرم فراورده حدود ۳۳ کیلوگرم میوه لازم است.","meta":""}],"proTip":"طعم آن را نرم، شکلاتی و کم‌تلخ‌تر از قهوه‌ی معمولی توصیف کرده‌اند.","variation":"","history":"تولید توسط شرکت Black Ivory Coffee و بنیان‌گذار کانادایی، بلیک دینکین، انجام می‌شود. پس از ۹ سال آزمایش، او در ۲۰۱۲ با تولید اولیه‌ی ۱۵۰ کیلوگرم به کیفیت رضایت‌بخش رسید. تولید ابتدا در پناهگاهی در شمال تایلند بود و بعد به استان سورین منتقل شد (۲۰ فیل مشارکت‌کننده). هر فنجان حدود ۵۰ دلار.","src":[["Wikipedia — Black Ivory coffee","https://en.wikipedia.org/wiki/Black_Ivory_coffee"]]}],"hero":"assets/images/rare_beans.svg"}];
